# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------


def _run_git(*args: str, cwd: Path) -> None:
    """Run a git command, raising on failure."""
    subprocess.run(["git", *args], cwd=cwd, check=True, capture_output=True)


def _run_git_stdout(*args: str, cwd: Path) -> str:
    """Run a git command and return stdout."""
    result = subprocess.run(
        ["git", *args],
        cwd=cwd,
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout


def _run_git_expect_fail(*args: str, cwd: Path) -> bool:
    """Return True when git command fails (expected in negative assertions)."""
    result = subprocess.run(["git", *args], cwd=cwd, capture_output=True, text=True)
    return result.returncode != 0


def _run_make_dry_run(*args: str, cwd: Path) -> str:
    """Return the commands `make -n` would execute."""
    env = os.environ.copy()
    env.pop("MAKEFLAGS", None)
    result = subprocess.run(
        ["make", "-n", *args],
        cwd=cwd,
        check=True,
        capture_output=True,
        text=True,
        env=env,
    )
    return result.stdout


def _create_annotated_merge_tag(
    cwd: Path,
    *,
    spec_id: str,
    target_ref: str = "HEAD",
    merge_commit_sha: str | None = None,
    pr_number: int | None = 12,
    source_branch: str | None = None,
    actor: str = "tester",
    timestamp: str = "2026-01-02T03:04:05Z",
) -> None:
    if merge_commit_sha is None:
        merge_commit_sha = _run_git_stdout(
            "rev-parse",
            f"{target_ref}^{{commit}}",
            cwd=cwd,
        ).strip()
    provenance = merge_tags.MergeTagProvenance(
        spec_id=spec_id,
        merge_commit_sha=merge_commit_sha,
        pr_number=pr_number,
        source_branch=source_branch or f"code/{spec_id}--test",
        actor=actor,
        timestamp=timestamp,
    )
    command = merge_tags.annotated_tag_command(
        merge_tags.merge_tag_name(spec_id),
        target_ref,
        merge_tags.build_tag_message(provenance),
    )
    _run_git(*command[1:], cwd=cwd)


def _init_git_repo(work: Path) -> Path:
    """Initialise a git repo at *work* with a bare remote and origin/master."""
    remote = work.parent / "remote.git"
    subprocess.run(["git", "init", "--bare", str(remote)], check=True, capture_output=True)

    _run_git("init", cwd=work)
    _run_git("config", "user.email", "test@test.com", cwd=work)
    _run_git("config", "user.name", "Test", cwd=work)
    _run_git("remote", "add", "origin", str(remote), cwd=work)

    return remote


def _unreachable_commit(repo: Path) -> str:
    """Create a commit object not reachable from any branch (real branch work).

    Remote implementation branches always carry commits beyond the base ref;
    a ref pointing at HEAD would be classified as empty bootstrap residue and
    ignored for status purposes.
    """
    result = subprocess.run(
        ["git", "commit-tree", "HEAD^{tree}", "-p", "HEAD", "-m", "implementation work"],
        cwd=repo,
        check=True,
        capture_output=True,
        text=True,
    )
    return result.stdout.strip()


class TestEmptyRemoteBranchesAreNotInProgress:
    def test_zero_commit_branch_does_not_park_spec(self, tmp_path: Path):
        """Bootstrap residue: a code/ branch pointing at a base-ref commit must
        not project the spec as in-progress."""
        work = tmp_path / "work"
        work.mkdir()
        _init_git_repo(work)
        (work / "README.md").write_text("hello\n")
        _run_git("add", "README.md", cwd=work)
        _run_git("commit", "-m", "init", cwd=work)
        _run_git("branch", "-M", "master", cwd=work)
        _run_git("push", "-u", "origin", "master", cwd=work)

        # Empty branch: same head as master — a run died at bootstrap.
        _run_git("branch", "code/parked-spec--20260101T000000", cwd=work)
        # Real branch: one unique commit of implementation work.
        _run_git("checkout", "-b", "code/active-spec--20260101T000000", cwd=work)
        (work / "impl.py").write_text("work\n")
        _run_git("add", "impl.py", cwd=work)
        _run_git("commit", "-m", "implement", cwd=work)
        _run_git("checkout", "master", cwd=work)
        _run_git(
            "push",
            "origin",
            "code/parked-spec--20260101T000000",
            "code/active-spec--20260101T000000",
            cwd=work,
        )
        _run_git("fetch", "origin", cwd=work)

        config = replace(spec_status.SPEC_RUNTIME_CONFIG, base_ref="origin/master")
        specs = spec_status._collect_remote_in_progress_specs(work, config=config)

        assert "active-spec" in specs
        assert "parked-spec" not in specs


