class TestOrchestratorRequest:
    def test_valid_request(self):
        req = orch.OrchestratorRequest(
            request_id="req-001",
            spec_id="my-feature",
            branch="spec/my-feature",
            action="run",
        )
        assert req.validate() == []

    def test_invalid_spec_id(self):
        req = orch.OrchestratorRequest(
            request_id="req-002",
            spec_id="INVALID ID!",
            branch="spec/my-feature",
            action="run",
        )
        errors = req.validate()
        assert len(errors) == 1
        assert "spec_id" in errors[0]

    @pytest.mark.parametrize("spec_id", ["con", "a" * 65])
    def test_windows_unsafe_spec_id(self, spec_id):
        req = orch.OrchestratorRequest(
            request_id="req-windows-unsafe",
            spec_id=spec_id,
            branch="spec/my-feature",
            action="run",
        )
        assert any("spec_id" in error for error in req.validate())

    def test_invalid_branch(self):
        req = orch.OrchestratorRequest(
            request_id="req-003",
            spec_id="my-feature",
            branch="random/branch",
            action="run",
        )
        errors = req.validate()
        assert len(errors) == 1
        assert "branch" in errors[0]

    def test_invalid_action(self):
        req = orch.OrchestratorRequest(
            request_id="req-004",
            spec_id="my-feature",
            branch="spec/my-feature",
            action="destroy",
        )
        errors = req.validate()
        assert len(errors) == 1
        assert "action" in errors[0]

    def test_fix_branch_valid(self):
        req = orch.OrchestratorRequest(
            request_id="req-005",
            spec_id="my-feature",
            branch="fix/my-feature",
            action="run",
        )
        assert req.validate() == []

    def test_task_branch_valid(self):
        req = orch.OrchestratorRequest(
            request_id="req-006",
            spec_id="task-docs-20260101010101",
            branch="task/docs-20260101010101",
            action="task",
        )
        assert req.validate() == []


