class TestRunState:
    def test_new_and_save_load(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        run.save(repo)

        loaded = orch.RunState.load(repo, "my-feature-20260101T000000")
        assert loaded.spec_id == "my-feature"
        assert loaded.phase == "bootstrap"
        assert loaded.status == "pending"
        assert loaded.run_mode == "spec"
        assert loaded.generated_spec_path == ""

    def test_find_latest(self, repo: Path):
        # Create two runs
        r1 = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        r1.save(repo)
        r2 = orch.RunState(
            run_id="my-feature-20260102T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        r2.save(repo)

        latest = orch.RunState.find_latest(repo, "my-feature")
        assert latest is not None
        assert latest.run_id == "my-feature-20260102T000000"

    def test_find_latest_uses_run_metadata_for_task_slugged_runs(self, repo: Path):
        older = orch.RunState(
            run_id="task-zzzz-20260101T000000",
            spec_id="my-fix",
            branch="task/my-fix--older",
            run_mode="task",
            created_at="2026-01-01T00:00:00+00:00",
            updated_at="2026-01-01T00:00:01+00:00",
        )
        older.save(repo)
        newer = orch.RunState(
            run_id="task-aaaa-20260102T000000",
            spec_id="my-fix",
            branch="task/my-fix--newer",
            run_mode="task",
            created_at="2026-01-02T00:00:00+00:00",
            updated_at="2026-01-02T00:00:01+00:00",
        )
        newer.save(repo)

        latest = orch.RunState.find_latest(repo, "my-fix")
        assert latest is not None
        assert latest.run_id == "task-aaaa-20260102T000000"

    def test_find_latest_returns_none(self, repo: Path):
        result = orch.RunState.find_latest(repo, "nonexistent")
        assert result is None

    def test_normalize_spec_path_accepts_canonical_repo_paths(self):
        assert orch._normalize_spec_path("./specs/my-feature.md") == "specs/my-feature.md"

    @pytest.mark.parametrize(
        "spec_path",
        [
            "../specs/my-feature.md",
            "/tmp/specs/my-feature.md",
            r"..\\specs\\my-feature.md",
            "docs/my-feature.md",
            "specs/my-feature.txt",
        ],
    )
    def test_normalize_spec_path_rejects_invalid_paths(self, spec_path: str):
        with pytest.raises(ValueError, match="Invalid spec path"):
            orch._normalize_spec_path(spec_path)

    def test_spec_path_for_run_id_prefers_pinned_snapshot(self, repo: Path):
        worktree = repo / ".worktrees" / "code-my-feature--token123"
        worktree.mkdir(parents=True, exist_ok=True)
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            worktree_path=str(worktree),
            spec_path="specs/my-feature.md",
            spec_revision=orch._spec_revision_for_text("pinned spec\n"),
        )
        run.save(repo)

        snapshot_path = orch._run_spec_snapshot_path(repo, run.run_id)
        snapshot_path.parent.mkdir(parents=True, exist_ok=True)
        snapshot_path.write_text("pinned spec\n")

        worktree_spec = worktree / "specs" / "my-feature.md"
        worktree_spec.parent.mkdir(parents=True, exist_ok=True)
        worktree_spec.write_text("mutated worktree copy\n")

        assert orch._spec_path_for_run_id(repo, run, run.spec_id) == snapshot_path

    def test_ensure_run_spec_binding_prefers_legacy_current_spec_for_unpinned_runs(
        self,
        repo: Path,
    ):
        worktree = repo / ".worktrees" / "code-my-feature--token123"
        worktree.mkdir(parents=True, exist_ok=True)
        legacy_text = "legacy current spec\n"
        run = orch.RunState(
            run_id="my-feature-20260101T000003",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            worktree_path=str(worktree),
            generated_spec_path="CURRENT_SPEC.md",
        )
        run.save(repo)

        (repo / "specs" / "my-feature.md").write_text("edited repo spec\n")
        legacy_spec = worktree / "CURRENT_SPEC.md"
        legacy_spec.write_text(legacy_text)

        assert orch._existing_spec_source_path(repo, run) == legacy_spec

        rebound = orch._ensure_run_spec_binding(run, repo)
        assert rebound.spec_path == "specs/my-feature.md"
        assert rebound.spec_revision == orch._spec_revision_for_text(legacy_text)
        assert orch._run_spec_snapshot_path(repo, run.run_id).read_text() == legacy_text

    def test_ensure_run_spec_binding_prefers_matching_source_over_drifted_repo_spec(
        self,
        repo: Path,
    ):
        worktree = repo / ".worktrees" / "code-my-feature--token123"
        worktree.mkdir(parents=True, exist_ok=True)
        pinned_text = "pinned spec\n"
        run = orch.RunState(
            run_id="my-feature-20260101T000001",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            worktree_path=str(worktree),
            spec_path="specs/my-feature.md",
            spec_revision=orch._spec_revision_for_text(pinned_text),
        )
        run.save(repo)

        (repo / "specs" / "my-feature.md").write_text("new repo spec\n")
        worktree_spec = worktree / "specs" / "my-feature.md"
        worktree_spec.parent.mkdir(parents=True, exist_ok=True)
        worktree_spec.write_text(pinned_text)

        assert orch._existing_spec_source_path(repo, run) == worktree_spec

        rebound = orch._ensure_run_spec_binding(run, repo)
        assert rebound.spec_revision == orch._spec_revision_for_text(pinned_text)
        assert orch._run_spec_snapshot_path(repo, run.run_id).read_text() == pinned_text

    def test_ensure_run_spec_binding_fails_closed_when_pinned_revision_is_missing(
        self,
        repo: Path,
    ):
        run = orch.RunState(
            run_id="my-feature-20260101T000002",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            spec_path="specs/my-feature.md",
            spec_revision=orch._spec_revision_for_text("pinned spec\n"),
        )
        run.save(repo)

        (repo / "specs" / "my-feature.md").write_text("drifted repo spec\n")

        rebound = orch._ensure_run_spec_binding(run, repo)
        assert rebound.spec_revision == orch._spec_revision_for_text("pinned spec\n")
        assert orch._existing_spec_source_path(repo, rebound) is None
        assert not orch._run_spec_snapshot_path(repo, run.run_id).exists()

    def test_active_spec_path_fails_closed_when_pinned_revision_is_missing(
        self,
        repo: Path,
    ):
        worktree = repo / ".worktrees" / "code-my-feature--token123"
        worktree.mkdir(parents=True, exist_ok=True)
        run = orch.RunState(
            run_id="my-feature-20260101T000004",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            worktree_path=str(worktree),
            spec_path="specs/my-feature.md",
            spec_revision=orch._spec_revision_for_text("pinned spec\n"),
        )
        run.save(repo)

        (repo / "specs" / "my-feature.md").write_text("drifted repo spec\n")
        worktree_spec = worktree / "specs" / "my-feature.md"
        worktree_spec.parent.mkdir(parents=True, exist_ok=True)
        worktree_spec.write_text("drifted worktree spec\n")

        assert orch._active_spec_path(repo, run, prefer_worktree=True) is None


