class TestSpecLock:
    def test_acquire_and_release(self, repo: Path):
        with orch.SpecLock(repo, "my-feature"):
            # Lock is held, we're inside
            lock_file = repo / ".spec-state" / "locks" / "my-feature.lock"
            assert lock_file.exists()

    def test_contention_raises_runtime_error(self, repo: Path):
        with orch.SpecLock(repo, "my-feature"):
            with pytest.raises(RuntimeError, match="Lock contention"):
                with orch.SpecLock(repo, "my-feature"):
                    pass  # pragma: no cover


