class TestImplementContext:
    def test_save_and_load(self, repo: Path):
        ctx = orch.ImplementContext(
            implement_reason="initial",
            objective="Build feature X",
            run_id="my-feature-20260101T000000",
            attempt_number=2,
            run_state_dir=".spec-state/runs/my-feature-20260101T000000/",
            acceptance_checklist=["- [ ] First criterion"],
            verification_expectations=["- run `make test` during implement"],
            recent_commits=["abc1234 Initial commit"],
            failing_commands=[],
            failure_summary="",
            review_feedback_active=True,
            review_findings_count=2,
            mergeability_issue="not mergeable",
        )
        ctx.save(repo, "my-feature-20260101T000000")

        loaded = orch.ImplementContext.load(repo, "my-feature-20260101T000000")
        assert loaded is not None
        assert loaded.objective == "Build feature X"
        assert loaded.implement_reason == "initial"
        assert loaded.run_id == "my-feature-20260101T000000"
        assert loaded.attempt_number == 2
        assert loaded.run_state_dir == ".spec-state/runs/my-feature-20260101T000000/"
        assert loaded.acceptance_checklist == ["- [ ] First criterion"]
        assert loaded.verification_expectations == ["- run `make test` during implement"]
        assert loaded.review_feedback_active is True
        assert loaded.review_findings_count == 2
        assert loaded.mergeability_issue == "not mergeable"
        assert (
            repo
            / ".spec-state"
            / "runs"
            / "my-feature-20260101T000000"
            / "implement-context.attempt-2.json"
        ).is_file()

    def test_load_attempt_does_not_fall_back_to_latest_artifact(self, repo: Path):
        run_id = "my-feature-20260101T000000"
        orch.ImplementContext(
            objective="Build feature X",
            run_id=run_id,
            attempt_number=1,
        ).save(repo, run_id)

        assert orch.ImplementContext.load_attempt(repo, run_id, 2) is None
        assert orch.ImplementContext.attempt_path(
            repo,
            run_id,
            2,
        ) == (
            repo
            / ".spec-state"
            / "runs"
            / run_id
            / "implement-context.attempt-2.json"
        )


class TestImplementResult:
    def test_save_and_load(self, repo: Path):
        result = orch.ImplementResult(
            status="passed",
            summary="All done",
            commits=["abc1234 Add feature"],
            attempt=2,
        )
        result.save(repo, "my-feature-20260101T000000")

        loaded = orch.ImplementResult.load(repo, "my-feature-20260101T000000")
        assert loaded is not None
        assert loaded.status == "passed"
        assert loaded.summary == "All done"
        assert len(loaded.commits) == 1
        assert loaded.attempt == 2
        assert (
            repo
            / ".spec-state"
            / "runs"
            / "my-feature-20260101T000000"
            / "implement-result.attempt-3.json"
        ).is_file()

    def test_save_and_load_from_explicit_state_root(self, repo: Path):
        result = orch.ImplementResult(
            status="passed",
            summary="Saved to explicit root",
            commits=["abc1234 Add feature"],
            attempt=3,
        )
        state_root = repo / "custom-state"
