class _FakeMergeClock:
    """Deterministic clock: sleep() advances time(), so deadline loops no
    longer drift with runner speed (repeated CI flakes came from mixing
    mocked sleep with real time.time deadlines).

    Drive ``sleep`` from ``orch._poll_sleep``, never from ``orch.time.sleep``:
    the latter is process-global and also collects the busy-wait inside
    ``subprocess.Popen.wait(timeout=...)``."""

    def __init__(self, start: float = 1_000_000.0):
        self.now = start

    def time(self) -> float:
        return self.now

    def sleep(self, seconds: float) -> None:
        self.now += max(0.0, float(seconds))


def _make_fake_popen(
    returncode: int = 0,
    captured_env: dict | None = None,
    captured_proc: dict | None = None,
    stdout_lines: list[str] | None = None,
    poll_sequence: list[int | None] | None = None,
):
    """Return a class that mimics subprocess.Popen for implement-phase tests."""

    class FakePopen:
        def __init__(self, cmd, cwd=None, env=None, **kwargs):
            if captured_env is not None:
                captured_env.update(env or {})
            if captured_proc is not None:
                captured_proc["proc"] = self
            self.cmd = cmd
            self.args = cmd
            self.stdout = iter(stdout_lines or [])
            self.stderr = ""
            self.returncode = None
            self.pid = 43210
            self.terminated = False
            self.killed = False
            if poll_sequence is None:
                self._poll_values = [returncode]
            else:
                self._poll_values = list(poll_sequence)

        def __enter__(self):
            return self

        def __exit__(self, exc_type, exc, tb):
            return False

        def poll(self):
            if len(self._poll_values) > 1:
                value = self._poll_values.pop(0)
            else:
                value = self._poll_values[0]
            if value is not None:
                self.returncode = value
            return value

        def wait(self, timeout=None):
            if self.returncode is None:
                polled = self.poll()
                if polled is None:
                    raise subprocess.TimeoutExpired(self.cmd, timeout)
            return self.returncode

        def communicate(self, input=None, timeout=None):
            if self.returncode is None:
                polled = self.poll()
                if polled is None:
                    raise subprocess.TimeoutExpired(self.cmd, timeout)
            return ("", self.stderr)

        def terminate(self):
            self.terminated = True
            self.returncode = -15
            self._poll_values = [-15]

        def kill(self):
            self.killed = True
            self.returncode = -9
            self._poll_values = [-9]

    return FakePopen


class TestPhaseImplementHandshake:
    @pytest.fixture(autouse=True)
    def _materialize_legacy_result_fixtures_after_prelaunch_clear(
        self,
        monkeypatch: pytest.MonkeyPatch,
    ):
        """Treat prebuilt launch-zero fixtures as reports from the fake agent.

        Most tests in this class predate launch identities and stage the
        handshake before calling ``phase_implement``. Production now correctly
        clears that mutable alias before every launch, so move only those
        legacy test fixtures across the boundary and stamp the launch that the
        phase is about to reserve. Dedicated stale-handshake tests exercise the
        real clearing behavior without this class-local compatibility shim.
        """
        original = orch._discard_prelaunch_completion_artifacts

        def discard_then_materialize(
            repo_root: Path,
            worktree_path: Path,
            run_id: str,
        ) -> None:
            staged: list[tuple[orch.ImplementResult, Path]] = []
            for state_root in (
                orch._state_root(repo_root),
                orch._worktree_state_root(worktree_path),
            ):
                result = orch.ImplementResult.load_from_state_root(state_root, run_id)
                if result is not None and result.launch_number == 0:
                    staged.append((result, state_root))
            original(repo_root, worktree_path, run_id)
            for result, state_root in staged:
                result.launch_number = 1
                result.save_to_state_root(state_root, run_id)

        monkeypatch.setattr(
            orch,
            "_discard_prelaunch_completion_artifacts",
            discard_then_materialize,
        )

    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
            agent="claude",
        )

    def test_requires_completion_handshake(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_build_agent_command", return_value=["/bin/sh", "-c", "exit 0"]),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "failed"
        assert "no_handshake" in run.last_error
        assert "spec report" in run.last_error

    def test_passes_when_agent_reports_passed(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        orch.ImplementResult(status="passed", summary="done", attempt=0).save(repo, run.run_id)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_build_agent_command", return_value=["/bin/sh", "-c", "exit 0"]),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"

    def test_review_retry_blocks_when_pinned_review_artifact_does_not_match_head(self, repo: Path):
        run = self._make_run()
        run.attempts = 1
        run.review_decision_status = "request_changes"
