    def test_build_implement_attempt_context_keeps_guided_retry_pending_until_launch(self, repo: Path):
        run = self._make_run()
        run.attempts = 1
        run.pending_block_debugger_signature = "sig-123"
        run.last_error = "Required checks failing: ci (https://example.com/checks/7)"
        run.save(repo)
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        orch.BlockDiagnosis(
            summary="The current branch is still blocked on the same CI failure.",
            root_cause="The retry never changed the code path covered by CI.",
            confidence=0.91,
            category="gate-failure",
            evidence=["gate-status.json"],
            next_best_action="Change the failing code path before retrying.",
            requires_human_attention=False,
            needs_new_commit=True,
            blocker_signature="sig-123",
        ).save(repo, run.run_id)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_head_sha", return_value="abc123"),
        ):
            bundle = orch._build_implement_attempt_context(run, repo)

        assert bundle.reason == "retry"
        assert bundle.pending_guided_retry_signature == "sig-123"
        assert run.pending_block_debugger_signature == "sig-123"
        assert bundle.context.current_head_sha == "abc123"
        assert bundle.context.failure_summary == "Required checks failing: ci (https://example.com/checks/7)"
        assert bundle.context.debugger_summary == "The current branch is still blocked on the same CI failure."
        assert bundle.context.debugger_next_best_action == "Change the failing code path before retrying."

    def test_build_implement_attempt_context_attaches_resolved_operator_request(self, repo: Path):
        run = self._make_run()
        run.status = "passed"
        run.phase = "implement"
        run.attempts = 1
        run.save(repo)
        request = orch.OperatorRequest(
            kind="debugger_guidance",
            prompt="Choose the retry strategy.",
            suggested_action="Retry with the minimal fix.",
            status="resolved",
            response="Retry with the minimal lint fix.",
            response_source="spec input",
            request_attempt_number=1,
        )
        request.save(repo, run.run_id)

        bundle = orch._build_implement_attempt_context(run, repo)

        assert bundle.context.operator_request_kind == "debugger_guidance"
        assert bundle.context.operator_request_prompt == "Choose the retry strategy."
        assert bundle.context.operator_request_response == "Retry with the minimal lint fix."
        saved = orch.OperatorRequest.load(repo, run.run_id)
        assert saved is not None
        assert saved.status == "consumed"
        assert saved.continuation == orch.OPERATOR_CONTINUATION_CONTINUE_WORKFLOW
        assert saved.response_consumed_attempt_number == 2
        original_attempt = orch.OperatorRequest.load_attempt(repo, run.run_id, 1)
        consumed_attempt = orch.OperatorRequest.load_attempt(repo, run.run_id, 2)
        assert original_attempt is not None
        assert original_attempt.status == "resolved"
        assert original_attempt.response_consumed_attempt_number is None
        assert consumed_attempt is not None
        assert consumed_attempt.status == "consumed"
        assert consumed_attempt.continuation == orch.OPERATOR_CONTINUATION_CONTINUE_WORKFLOW
        assert consumed_attempt.response_consumed_attempt_number == 2

