    def test_phase_implement_keeps_mid_flight_replacement_steering_for_next_attempt(self, repo: Path):
        run = self._make_run()
        run.status = "passed"
        run.phase = "implement"
        run.attempts = 1
        run.save(repo)
        worktree = repo / ".worktrees" / run.spec_id
