        orch.OperatorSteering(
            message="Prefer the smallest retry that fixes lint.",
            provided_by="alice",
            provided_at="2026-01-02T03:04:05Z",
            source="spec steer",
        ).save(repo, run.run_id)

        def _launch_and_replace_steering(
            _run: orch.RunState,
            _repo_root: Path,
            _worktree_path: Path,
            _launch_plan: orch.ImplementLaunchPlan,
        ) -> int:
            orch._record_operator_steering(
                repo,
                run,
                "Actually, fix the schema retry first.",
                source="spec steer",
                provided_by="alice",
            )
            return 0

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_build_agent_command", return_value=["/bin/sh", "-c", "exit 0"]),
            patch.object(orch, "_launch_implement_attempt", side_effect=_launch_and_replace_steering),
            patch.object(orch, "_head_sha", side_effect=["abc123", "abc123", "abc123"]),
            patch.object(orch, "_worktree_dirty_files", return_value=[]),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        saved = orch.OperatorSteering.load(repo, run.run_id)
        history = orch.OperatorSteering.list_events(repo, run.run_id)
        assert saved is not None
        assert saved.message == "Actually, fix the schema retry first."
        assert saved.status == "active"
        assert saved.influenced_attempt_number is None
        assert len(history) == 2
        assert history[1].status == "superseded"
        assert history[1].message == "Prefer the smallest retry that fixes lint."
        assert history[1].influenced_attempt_number is None

