    def test_phase_implement_fails_before_agent_launch_when_setup_fails(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(
                orch,
                "_run_implement_setup_command",
                side_effect=RuntimeError("Implement setup command failed: boom"),
            ),
            patch.object(orch, "_run_implement_teardown_command") as teardown_command,
            patch.object(orch, "_build_agent_command") as build_cmd,
            patch.object(orch, "_claude_supports_stream_json", return_value=False),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=["git", "log"],
                    returncode=0,
                    stdout="abc123 fake commit\n",
                    stderr="",
                ),
            ),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "failed"
        build_cmd.assert_not_called()
        teardown_command.assert_called_once_with(run, worktree)
