    def test_phase_implement_does_not_consume_guided_retry_on_prelaunch_failure(self, repo: Path):
        """F2: guided retry must not be consumed if agent never actually launches."""
        run = self._make_run()
        run.attempts = 1
        run.pending_block_debugger_signature = "sig-abc"
        run.last_error = "Gate 'lint' failed"
        run.save(repo)
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        orch.ImplementResult(status="passed", summary="done", attempt=1).save(repo, run.run_id)
        orch.BlockDiagnosis(
            summary="Diagnosis",
            root_cause="Root cause",
            confidence=0.9,
            category="gate-failure",
            evidence=["gate-status.json"],
            next_best_action="Fix lint",
            requires_human_attention=False,
            needs_new_commit=True,
            blocker_signature="sig-abc",
        ).save(repo, run.run_id)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(
                orch,
                "_run_implement_setup_command",
                side_effect=RuntimeError("Setup failed"),
            ),
            patch.object(orch, "_run_implement_teardown_command"),
            patch.object(orch, "_claude_supports_stream_json", return_value=False),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=["git", "log"],
                    returncode=0,
                    stdout="abc123 fake commit\n",
                    stderr="",
                ),
            ),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "failed"
        # The guided retry must NOT have been consumed since the agent never ran.
        assert run.pending_block_debugger_signature == "sig-abc"
        assert run.last_block_debugger_guided_retry_signature == ""

    def test_phase_implement_retry_clears_stale_context_before_prelaunch_failure(self, repo: Path):
        run = self._make_run()
        run.agent = "codex"
        run.attempts = 1
        run.last_error = "Required checks failing: ci (https://example.com/checks/7)"
        run.save(repo)
        orch.ImplementContext(
            implement_reason="retry",
            objective=f"Implement spec {run.spec_id}",
            run_id=run.run_id,
            attempt_number=run.attempts,
            run_state_dir=f".spec-state/runs/{run.run_id}/",
            spec_path="specs/my-feature.md",
            spec_revision=run.spec_revision,
            visual_feedback_available=False,
        ).save(repo, run.run_id)
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        def fake_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            del cwd, env, timeout
            if cmd[:2] == ["git", "log"]:
                return subprocess.CompletedProcess(
                    args=cmd,
                    returncode=0,
                    stdout="abc123 fake commit\n",
                    stderr="",
                )
            raise AssertionError(f"Unexpected command: {cmd}")

        def fake_validate_codex_exec(current_run: orch.RunState) -> bool:
            current_run.last_error = "Codex CLI does not support 'exec' subcommand."
            return False

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_validate_codex_exec", side_effect=fake_validate_codex_exec),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(orch, "run_subprocess", side_effect=fake_run_subprocess),
        ):
            status = orch.run_single_phase(run, "implement", repo)

        assert status == "failed"
        assert run.last_error == "Codex CLI does not support 'exec' subcommand."

        saved_run = orch.RunState.load(repo, run.run_id)
        assert saved_run.last_error == "Codex CLI does not support 'exec' subcommand."
        assert orch.ImplementContext.load(repo, run.run_id) is None

