    def test_dirty_worktree_preserves_worktree_local_handshake_until_after_interpretation(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
