    def test_implement_context_includes_intake_answers(self, repo: Path):
        run = self._make_run()
        run.run_id = "interactive-feature-20260101T000000"
        run.spec_id = "interactive-feature"
        run.branch = "spec/interactive-feature"
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        intake_spec = orch.parse_intake_spec(repo / "specs" / "interactive-feature.md")
        orch.IntakeResult(
            version=orch.INTAKE_FILE_VERSION,
            spec_id=run.spec_id,
            run_id=run.run_id,
            schema_version=intake_spec.schema_version,
            schema_hash=intake_spec.schema_hash(),
            questions=[question.to_schema_payload() for question in intake_spec.questions],
            answers={"rollout_mode": "canary", "migration_window": 9},
        ).save(repo, run.run_id)
        orch.ImplementResult(status="passed", summary="done", attempt=0).save(repo, run.run_id)
        captured_kwargs: dict[str, object] = {}

        def fake_build_agent_command(
            _agent: str,
            _worktree_path: Path,
            **kwargs: object,
        ) -> list[str]:
            captured_kwargs.update(kwargs)
            return ["/bin/sh", "-c", "exit 0"]

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_build_agent_command", side_effect=fake_build_agent_command),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        context = orch.ImplementContext.load(repo, run.run_id)
        assert context is not None
