        gate_file.write_text(
            json.dumps(
                {
                    "spec_id": run.spec_id,
                    "gates": {
                        "test": {
                            "attempts": 5,
                            "last_status": "failed",
                            "last_command": "make test",
                            "last_run_at": "2026-03-11T00:00:00Z",
                            "last_stdout": ("FAILED tests/test_api.py::test_alpha - AssertionError: expected 1"),
                            "last_stderr": "make[1]: *** [test] Error 1",
                            "last_diagnostic": (
                                "__________________________________ test_alpha __________________________________\n"
                                "tests/test_api.py:10: in test_alpha\n"
                                "    assert value == 1\n"
                                "E   AssertionError: expected 1\n\n"
                                "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1\n"
                                "3 failed, 42 passed in 0.45s"
                            ),
                            "history": [
                                {
                                    "attempt": 1,
                                    "status": "failed",
                                    "passed_count": 37,
                                    "failed_count": 8,
                                    "error_count": 0,
                                    "failed_tests": ["tests/test_api.py::test_alpha"],
                                    "timestamp": "2026-03-11T00:00:00Z",
                                },
                                {
                                    "attempt": 5,
                                    "status": "failed",
                                    "passed_count": 42,
                                    "failed_count": 3,
                                    "error_count": 0,
                                    "failed_tests": ["tests/test_api.py::test_alpha"],
                                    "timestamp": "2026-03-11T00:05:00Z",
                                },
                            ],
                        }
                    },
                },
                indent=2,
            )
            + "\n"
        )
        orch.ImplementResult(
            status="passed",
            summary="done",
            attempt=run.attempts,
        ).save(repo, run.run_id)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_build_agent_command", return_value=["/bin/sh", "-c", "exit 0"]),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        context = orch.ImplementContext.load(repo, run.run_id)
        assert context is not None
        assert context.failing_commands == ["make test"]
        assert context.failure_summary == "test: failed (attempt 5: 3 failed, 42 passed; was 8 failed on attempt 1)"
        assert context.gate_output == (
            "--- test (diagnostic) ---\n"
            "__________________________________ test_alpha __________________________________\n"
            "tests/test_api.py:10: in test_alpha\n"
            "    assert value == 1\n"
            "E   AssertionError: expected 1\n\n"
            "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1\n"
            "3 failed, 42 passed in 0.45s\n"
            "--- test (stderr) ---\n"
            "make[1]: *** [test] Error 1"
        )

