    def test_no_handshake_with_uncommitted_changes_triggers_one_recovery_attempt(
        self,
        repo: Path,
    ):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        build_calls: list[dict[str, object]] = []
        call_order: list[str] = []
        manifest = orch.ImplementSetupManifest(
            prompt="App ready at http://127.0.0.1:43123/app/.",
            mcp_prompt="Use Playwright MCP to inspect the UI.",
            mcp_servers={
                "playwright": {
                    "command": "node",
                    "args": ["/tmp/playwright-mcp.js"],
                }
            },
        )

        def fake_build_agent_command(
            _agent: str,
            _worktree_path: Path,
            **kwargs: object,
        ) -> list[str]:
            build_calls.append(kwargs)
            call_order.append("recovery-build" if kwargs.get("retry_context") is not None else "initial-build")
            return ["agent"]

        def fake_popen(cmd, cwd=None, env=None, **kwargs):
            del cwd, env, kwargs
            if len(build_calls) >= 2:
                orch.ImplementResult(
                    status="passed",
                    summary="Recovered and reported completion",
                    attempt=run.attempts,
                    launch_number=run.implement_launches,
                ).save(repo, run.run_id)
            return _make_fake_popen(returncode=0)(cmd)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(
                orch,
                "_run_implement_setup_command",
                side_effect=lambda *_args, **_kwargs: (
                    call_order.append("setup"),
                    manifest,
                )[-1],
            ),
            patch.object(
                orch,
                "_run_implement_teardown_command",
                side_effect=lambda *_args, **_kwargs: call_order.append("teardown"),
            ),
            patch.object(orch, "_write_sandbox_config") as write_sandbox_config,
            patch.object(orch, "_build_agent_command", side_effect=fake_build_agent_command),
            patch.object(orch, "_head_sha", side_effect=["abc123", "abc123"]),
            patch.object(orch, "_worktree_dirty_files", return_value=[" M file.py"]),
            patch.object(orch.subprocess, "Popen", side_effect=fake_popen),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        assert build_calls[0]["retry_context"] is None
        assert build_calls[1]["retry_context"] is not None
        assert build_calls[1]["retry_context"].implement_reason == "recovery"
        assert build_calls[0]["setup_prompt"] == manifest.prompt
        assert build_calls[0]["setup_mcp_prompt"] == manifest.mcp_prompt
        assert build_calls[1]["setup_prompt"] == manifest.prompt
        assert build_calls[1]["setup_mcp_prompt"] == manifest.mcp_prompt
        assert call_order == [
            "setup",
            "initial-build",
            "teardown",
            "setup",
            "recovery-build",
            "teardown",
        ]
        assert write_sandbox_config.call_count == 2
        assert write_sandbox_config.call_args_list[0].kwargs["extra_mcp_servers"] == manifest.mcp_servers
        assert write_sandbox_config.call_args_list[1].kwargs["extra_mcp_servers"] == manifest.mcp_servers

    def test_no_handshake_recovery_routes_through_execution_backend(self, repo: Path):
        run = self._make_run()
        run.attempts = 1
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        ctx = orch.ImplementContext(
            implement_reason="retry",
            objective="Implement spec",
            run_id=run.run_id,
            attempt_number=run.attempts,
            run_state_dir=".spec-state/runs/my-feature-20260101T000000/",
            spec_path=f"specs/{run.spec_id}.md",
            spec_revision="sha256:test",
        )
        captured: dict[str, object] = {}

        class RecordingBackend:
            def launch_agent(
                self,
                request: eb.AgentRequest,
                *,
                monitor: eb.AgentMonitor | None = None,
            ) -> eb.AgentResult:
                captured["request"] = request
                captured["monitor_provided"] = monitor is not None
                orch.ImplementResult(
                    status="passed",
                    summary="Recovered through backend",
                    attempt=run.attempts,
                    launch_number=run.implement_launches,
                ).save(repo, run.run_id)
                return eb.AgentResult(returncode=0)

        orch.set_execution_backend(RecordingBackend())  # type: ignore[arg-type]
        try:
            with (
                patch.object(orch, "_run_implement_setup_command", return_value=orch.ImplementSetupManifest()),
                patch.object(orch, "_run_implement_teardown_command"),
                patch.object(orch, "_write_sandbox_config"),
                patch.object(orch, "_build_agent_command", return_value=["agent", "recover"]),
                patch.object(
                    orch.subprocess,
                    "Popen",
                    side_effect=AssertionError("recovery bypassed execution backend"),
                ),
            ):
                status = orch._attempt_no_handshake_recovery(
                    run,
                    repo_root=repo,
                    worktree_path=worktree,
                    ctx=ctx,
                    use_stream_json=False,
                )
        finally:
            orch.set_execution_backend(None)

        assert status == "passed"
        assert captured["monitor_provided"] is True
        request = captured["request"]
        assert isinstance(request, eb.AgentRequest)
        assert request.argv == ["agent", "recover"]
        assert request.cwd == worktree

