    def test_no_handshake_recovery_tears_down_before_rerunning_setup(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        calls: list[str] = []

        def fake_build_agent_command(
            _agent: str,
            _worktree_path: Path,
            **kwargs: object,
        ) -> list[str]:
            calls.append("recovery-build" if kwargs.get("retry_context") is not None else "initial-build")
            return ["agent"]

        def fake_popen(cmd, cwd=None, env=None, **kwargs):
            del cwd, env, kwargs
            if calls.count("recovery-build") == 1:
                orch.ImplementResult(
                    status="passed",
                    summary="Recovered and reported completion",
                    attempt=run.attempts,
                    launch_number=run.implement_launches,
                ).save(repo, run.run_id)
            return _make_fake_popen(returncode=0)(cmd)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(
                orch,
                "_run_implement_setup_command",
                side_effect=lambda *_args, **_kwargs: (calls.append("setup"), orch.ImplementSetupManifest())[-1],
            ),
            patch.object(
                orch,
                "_run_implement_teardown_command",
                side_effect=lambda *_args, **_kwargs: calls.append("teardown"),
            ),
            patch.object(orch, "_write_sandbox_config"),
            patch.object(orch, "_build_agent_command", side_effect=fake_build_agent_command),
            patch.object(orch, "_head_sha", side_effect=["abc123", "abc123"]),
            patch.object(orch, "_worktree_dirty_files", return_value=[" M file.py"]),
            patch.object(orch.subprocess, "Popen", side_effect=fake_popen),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        assert calls == [
            "setup",
            "initial-build",
            "teardown",
            "setup",
            "recovery-build",
            "teardown",
        ]

    def test_no_handshake_recovery_rebuilds_env_before_second_setup(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        popen_envs: list[dict[str, str]] = []
        setup_calls = 0

        def fake_run_setup_command(*_args, **_kwargs):
            nonlocal setup_calls
            setup_calls += 1
            if setup_calls == 1:
                return orch.ImplementSetupManifest(
                    env={"DATABASE_URL": "postgresql://stale-db"},
                )
            return orch.ImplementSetupManifest()

        def fake_popen(cmd, cwd=None, env=None, **kwargs):
            del cmd, cwd, kwargs
            launch_env = dict(env or {})
            popen_envs.append(launch_env)
            agent_launches = [recorded_env for recorded_env in popen_envs if recorded_env.get("SPEC_ID") == run.spec_id]
            if len(agent_launches) == 2:
                orch.ImplementResult(
                    status="passed",
                    summary="Recovered and reported completion",
                    attempt=run.attempts,
                    launch_number=run.implement_launches,
                ).save(repo, run.run_id)
            return _make_fake_popen(returncode=0)(["agent"])

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_run_implement_setup_command", side_effect=fake_run_setup_command),
            patch.object(orch, "_run_implement_teardown_command"),
            patch.object(orch, "_write_sandbox_config"),
            patch.object(orch, "_build_agent_command", return_value=["agent"]),
            patch.object(orch, "_head_sha", side_effect=["abc123", "abc123"]),
            patch.object(orch, "_worktree_dirty_files", return_value=[" M file.py"]),
            patch.object(orch.subprocess, "Popen", side_effect=fake_popen),
            patch.dict(orch.os.environ, {"BASE_ENV": "present"}, clear=True),
        ):
            status = orch.phase_implement(run, repo)

        agent_envs = [env for env in popen_envs if env.get("SPEC_ID") == run.spec_id]
        assert status == "passed"
        assert len(agent_envs) == 2
        assert agent_envs[0]["DATABASE_URL"] == "postgresql://stale-db"
        assert "DATABASE_URL" not in agent_envs[1]
        assert agent_envs[1]["BASE_ENV"] == "present"
        assert agent_envs[1]["SPEC_ID"] == run.spec_id
        assert agent_envs[1]["SPEC_RUN_ID"] == run.run_id
        assert agent_envs[1]["SPEC_PATH"] == f"specs/{run.spec_id}.md"

