    def test_no_handshake_recovery_propagates_setup_failure_diagnostics(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        setup_calls = 0
        captured_kwargs: list[dict[str, object]] = []
        captured_envs: list[dict[str, str]] = []

        def fake_run_setup_command(*_args, **_kwargs):
            nonlocal setup_calls
            setup_calls += 1
            if setup_calls == 1:
                return orch.ImplementSetupManifest()
            return orch.ImplementSetupManifest(
                env={
                    "SPEC_ID": "other-spec",
                    "SPEC_RUN_ID": "stale-run",
                    "SPEC_PATH": "specs/other-spec.md",
                    "SPEC_ATTEMPT": "999",
                    "SPEC_IMPLEMENT_LAUNCH": "999",
                },
                failure=orch.ImplementSetupFailure(
                    command="scripts/implement-setup.sh",
                    exit_code=3,
                    stdout_tail="",
                    stderr_tail="recovery setup blew up",
                    message="recovery setup blew up",
                    launch_error=False,
                ),
            )

        recovery_call_index: list[int] = []

        def fake_build_agent_command(_agent, _worktree_path, **kwargs):
            captured_kwargs.append(kwargs)
            if kwargs.get("retry_context") is not None:
                recovery_call_index.append(len(captured_kwargs) - 1)
            return ["agent"]

        def fake_popen(cmd, cwd=None, env=None, **kwargs):
            del cwd, kwargs
            captured_envs.append(dict(env or {}))
            if recovery_call_index:
                orch.ImplementResult(
                    status="passed",
                    summary="Recovered and reported completion",
                    attempt=run.attempts,
                    launch_number=run.implement_launches,
                ).save(repo, run.run_id)
            return _make_fake_popen(returncode=0)(cmd)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_run_implement_setup_command", side_effect=fake_run_setup_command),
            patch.object(orch, "_run_implement_teardown_command"),
            patch.object(orch, "_write_sandbox_config"),
            patch.object(orch, "_build_agent_command", side_effect=fake_build_agent_command),
            patch.object(orch, "_head_sha", side_effect=["abc123", "abc123"]),
            patch.object(orch, "_worktree_dirty_files", return_value=[" M file.py"]),
            patch.object(orch.subprocess, "Popen", side_effect=fake_popen),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "passed"
        assert recovery_call_index, "recovery agent should have been built"
        recovery_kwargs = captured_kwargs[recovery_call_index[0]]
        recovery_setup_prompt = recovery_kwargs.get("setup_prompt") or ""
        assert "prepare step failed" in recovery_setup_prompt
        assert "recovery setup blew up" in recovery_setup_prompt
        recovery_env = captured_envs[-1]
        assert recovery_env["SPEC_ID"] == run.spec_id
        assert recovery_env["SPEC_RUN_ID"] == run.run_id
        assert recovery_env["SPEC_PATH"] == f"specs/{run.spec_id}.md"
        assert recovery_env["SPEC_ATTEMPT"] == str(run.attempts)
        assert recovery_env["SPEC_IMPLEMENT_LAUNCH"] == str(run.implement_launches)
        assert any(
            warning.get("failure_type") == "setup"
            and warning.get("failure_subtype") == "prepare_failed"
            for warning in run.nonfatal_warnings
        )

