class TestRedactSensitive:
    def test_redacts_github_token(self):
        text = "token=ghp_abcdefghijklmnopqrstuvwxyz1234567890 done"
        result = orch.redact_sensitive(text)
        assert "ghp_" not in result
        assert "<REDACTED>" in result

    def test_redacts_bearer(self):
        text = "Authorization: Bearer eyJhbGciOi..."
        result = orch.redact_sensitive(text)
        assert "eyJhbG" not in result

    def test_passthrough_clean_text(self):
        text = "All tests passed successfully"
        assert orch.redact_sensitive(text) == text


class TestClaudeProgressRedaction:
    def test_redacts_sensitive_tool_input_and_text(self, capsys):
        event = json.dumps(
            {
                "type": "assistant",
                "message": {
                    "content": [
                        {
                            "type": "tool_use",
                            "name": "Bash",
                            "input": {
                                "command": ("export TOKEN=ghp_abcdefghijklmnopqrstuvwxyz1234567890AB"),
                            },
                        },
                        {
                            "type": "text",
                            "text": "Authorization: Bearer super-secret-value",
                        },
                    ],
                },
            },
        )

        orch._handle_claude_stream_line(event)

        captured = capsys.readouterr()
        assert "<REDACTED>" in captured.err
        assert "ghp_" not in captured.err
        assert "Bearer super-secret-value" not in captured.err


class TestClaudeInflightToolWatchdog:
    """Claude stream-json is silent while a tool executes."""

    @staticmethod
    def _feed(tracker: orch.AgentProgressTracker, event: object) -> None:
        orch._handle_claude_stream_line(json.dumps(event), tracker)

    @staticmethod
    def _tool_use(tool_id: str, *, name: str = "Bash") -> dict[str, object]:
        return {
            "type": "assistant",
            "message": {
                "role": "assistant",
                "content": [
                    {
                        "type": "tool_use",
                        "id": tool_id,
                        "name": name,
                        "input": {"command": "make test"},
                    }
                ],
            },
        }

    @staticmethod
    def _tool_result(tool_id: str, *, output: str = "tests passed") -> dict[str, object]:
        return {
            "type": "user",
            "message": {
                "role": "user",
                "content": [
                    {
                        "type": "tool_result",
                        "tool_use_id": tool_id,
                        "content": output,
                        "is_error": False,
                    }
                ],
            },
        }

    def test_tool_use_raises_idle_ceiling_until_matching_result(self):
        tracker = orch.AgentProgressTracker(agent="claude")

        self._feed(tracker, self._tool_use("toolu_01RecordedBash"))

        assert tracker.has_inflight_command() is True
        assert (
            orch._agent_idle_timeout("claude", tracker, has_progress_thread=True)
            == orch.AGENT_COMMAND_IDLE_TIMEOUT_SECONDS
        )

        tracker.last_progress_at = 0.0
        self._feed(tracker, self._tool_result("toolu_01RecordedBash"))

        assert tracker.has_inflight_command() is False
        assert tracker.last_progress_at > 0.0
        assert (
            orch._agent_idle_timeout("claude", tracker, has_progress_thread=True)
            == orch.CLAUDE_IDLE_TIMEOUT_SECONDS
        )

    def test_overlapping_and_forwarded_tool_ids_finish_independently(self):
        tracker = orch.AgentProgressTracker(agent="claude")
        outer = self._tool_use("toolu_outer", name="Task")
        nested = self._tool_use("toolu_nested")
        nested["parent_tool_use_id"] = "toolu_outer"

        self._feed(tracker, outer)
        self._feed(tracker, nested)
        self._feed(tracker, self._tool_result("toolu_outer"))

        assert tracker.has_inflight_command() is True

        # An unrelated or duplicated result must not clear another active ID.
        self._feed(tracker, self._tool_result("toolu_unknown"))
        assert tracker.has_inflight_command() is True

        self._feed(tracker, self._tool_result("toolu_nested"))
        assert tracker.has_inflight_command() is False

    def test_forwarded_tool_activity_refreshes_heartbeat_without_finishing_parent(self):
        tracker = orch.AgentProgressTracker(agent="claude")
        self._feed(tracker, self._tool_use("toolu_parent", name="Task"))
        tracker.last_progress_at = 0.0

        self._feed(
            tracker,
            {
                "type": "assistant",
                "parent_tool_use_id": "toolu_parent",
                "message": {
                    "role": "assistant",
                    "content": [{"type": "text", "text": "Subagent is still checking tests."}],
                },
            },
        )

        assert tracker.last_progress_at > 0.0
        assert tracker.has_inflight_command() is True

    def test_terminal_result_repairs_missing_tool_completion(self):
        tracker = orch.AgentProgressTracker(agent="claude")
        self._feed(tracker, self._tool_use("toolu_missing_result"))

        self._feed(tracker, {"type": "result", "subtype": "success"})

        assert tracker.has_inflight_command() is False

    @pytest.mark.parametrize(
        "event",
        [
            None,
            [],
            {"type": "assistant", "message": "not-an-object"},
            {"type": "assistant", "message": {"content": "not-a-list"}},
            {"type": "assistant", "message": {"content": ["not-an-object"]}},
            {"type": "assistant", "message": {"content": [{"type": "tool_use"}]}},
            {"type": "user", "message": {"content": [{"type": "tool_result"}]}},
        ],
    )
    def test_malformed_events_refresh_activity_without_corrupting_tool_state(self, event: object):
        tracker = orch.AgentProgressTracker(agent="claude")
        self._feed(tracker, self._tool_use("toolu_valid"))
        tracker.last_progress_at = 0.0

        self._feed(tracker, event)

        assert tracker.last_progress_at > 0.0
        assert tracker.has_inflight_command() is True

    def test_malformed_json_refreshes_activity_without_corrupting_tool_state(self):
        tracker = orch.AgentProgressTracker(agent="claude")
        self._feed(tracker, self._tool_use("toolu_valid"))
        tracker.last_progress_at = 0.0

        orch._handle_claude_stream_line("{not-json", tracker)

        assert tracker.last_progress_at > 0.0
        assert tracker.has_inflight_command() is True

    def test_genuinely_silent_tool_is_terminated_at_command_ceiling(self, repo: Path):
        worktree = repo / ".worktrees" / "claude-watchdog"
        worktree.mkdir(parents=True)
        tracker = orch.AgentProgressTracker(agent="claude")
        self._feed(tracker, self._tool_use("toolu_hung"))
        tracker.last_progress_at = 0.0
        proc = _make_fake_popen(poll_sequence=[None, None])(["claude"])
        progress_thread = MagicMock()

        with (
            patch.object(orch, "CLAUDE_IDLE_TIMEOUT_SECONDS", 0.01),
            patch.object(orch, "AGENT_COMMAND_IDLE_TIMEOUT_SECONDS", 0.02),
            patch.object(orch, "_poll_sleep"),
        ):
            returncode = orch._wait_for_agent_exit(
                proc=proc,
                agent="claude",
                repo_root=repo,
                worktree_path=worktree,
                run_id="claude-watchdog-20260101T000000",
                attempt=0,
                progress_thread=progress_thread,
                progress_tracker=tracker,
                spec_id="claude-watchdog",
            )

        assert returncode == -15
        assert proc.terminated is True
        assert "inactive" in tracker.timeout_message
        progress_thread.join.assert_called_once_with(timeout=1.0)


class TestCodexProgressHandling:
    def test_redacts_sensitive_codex_progress_output(self, capsys):
        tracker = orch.AgentProgressTracker(agent="codex")

        orch._handle_codex_stream_line(
            json.dumps(
                {
                    "type": "item.completed",
                    "item": {
                        "type": "command_execution",
                        "command": "export TOKEN=ghp_abcdefghijklmnopqrstuvwxyz1234567890AB",
                    },
                },
            ),
            tracker,
        )
        orch._handle_codex_stream_line(
            json.dumps(
                {
                    "type": "item.completed",
                    "item": {
                        "type": "agent_message",
                        "text": "Authorization: Bearer super-secret-value",
                    },
                },
            ),
            tracker,
        )

        captured = capsys.readouterr()
        assert "<REDACTED>" in captured.err
        assert "ghp_" not in captured.err
        assert "super-secret-value" not in captured.err

    def test_suppressed_codex_events_refresh_heartbeat_without_logging(self, capsys):
        tracker = orch.AgentProgressTracker(agent="codex")
        tracker.last_progress_at = 0.0
        tracker.last_event_summary = "prior visible progress"

        orch._handle_codex_stream_line(
            json.dumps(
                {
                    "type": "item.updated",
                    "item": {
                        "type": "reasoning",
                    },
                },
            ),
            tracker,
        )

        captured = capsys.readouterr()
        assert captured.err == ""
        assert tracker.last_progress_at > 0.0
        assert tracker.last_event_summary == "prior visible progress"


class TestCodexInflightCommandWatchdog:
    """Codex is silent for a command's whole duration (issue: long gates killed)."""

    @staticmethod
    def _feed(tracker, event):
        orch._handle_codex_stream_line(json.dumps(event), tracker)

    def _started(self, tracker, item_id="item_1", item_type="command_execution"):
        self._feed(
            tracker,
            {
                "type": "item.started",
                "item": {"id": item_id, "type": item_type, "command": "make test"},
            },
        )

    def test_long_running_command_raises_idle_ceiling(self):
        tracker = orch.AgentProgressTracker(agent="codex")
        assert (
            orch._agent_idle_timeout("codex", tracker, has_progress_thread=True)
            == orch.CODEX_IDLE_TIMEOUT_SECONDS
        )

        self._started(tracker)

        assert tracker.has_inflight_command() is True
        assert (
            orch._agent_idle_timeout("codex", tracker, has_progress_thread=True)
            == orch.AGENT_COMMAND_IDLE_TIMEOUT_SECONDS
        )

    def test_completed_command_restores_idle_timeout(self):
        tracker = orch.AgentProgressTracker(agent="codex")
        self._started(tracker)

        self._feed(
            tracker,
            {
                "type": "item.completed",
                "item": {"id": "item_1", "type": "command_execution", "command": "make test"},
            },
        )

        assert tracker.has_inflight_command() is False
        assert (
            orch._agent_idle_timeout("codex", tracker, has_progress_thread=True)
            == orch.CODEX_IDLE_TIMEOUT_SECONDS
        )

    def test_mcp_tool_calls_also_count_as_inflight(self):
        tracker = orch.AgentProgressTracker(agent="codex")
        self._started(tracker, item_id="mcp_1", item_type="mcp_tool_call")

        assert tracker.has_inflight_command() is True

    def test_reasoning_items_do_not_count_as_inflight(self):
        tracker = orch.AgentProgressTracker(agent="codex")
        self._started(tracker, item_id="r1", item_type="reasoning")

        assert tracker.has_inflight_command() is False

    def test_turn_completed_clears_missed_completions(self):
        tracker = orch.AgentProgressTracker(agent="codex")
        self._started(tracker)

        # A completion event that never arrives (or arrives re-keyed) must not
        # pin the watchdog to the command ceiling for the rest of the session.
        self._feed(tracker, {"type": "turn.completed"})

        assert tracker.has_inflight_command() is False

    def test_inflight_command_still_bounded_by_command_ceiling(self):
        """A hung command is still killed — just at the higher ceiling, not never."""
        tracker = orch.AgentProgressTracker(agent="codex")
        self._started(tracker)

        with (
            patch.object(orch, "CODEX_IDLE_TIMEOUT_SECONDS", 0.5),
            patch.object(orch, "AGENT_COMMAND_IDLE_TIMEOUT_SECONDS", 5.0),
        ):
            assert orch._agent_idle_timeout("codex", tracker, has_progress_thread=True) == 5.0

    def test_claude_without_stream_thread_stays_unbounded(self):
        tracker = orch.AgentProgressTracker(agent="claude")
        tracker.command_started("item_1")

        assert orch._agent_idle_timeout("claude", tracker, has_progress_thread=False) is None


