class TestPytestGateParsing:
    def test_parses_summary_counts_and_failed_tests(self):
        text = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            FAILED tests/test_api.py::test_beta - ValueError: bad
            2 failed, 41 passed in 0.45s
        """)

        counts = orch._parse_pytest_summary_counts(text)

        assert counts == {"passed_count": 41, "failed_count": 2, "error_count": 0}
        assert orch._parse_pytest_failed_tests(text, failed_count=2) == [
            "tests/test_api.py::test_alpha",
            "tests/test_api.py::test_beta",
        ]

    def test_returns_none_for_failed_tests_when_summary_has_failures_but_no_nodes(self):
        text = "2 failed, 41 passed in 0.45s"
        counts = orch._parse_pytest_summary_counts(text)
        assert counts == {"passed_count": 41, "failed_count": 2, "error_count": 0}
        assert orch._parse_pytest_failed_tests(text, failed_count=2) is None

    def test_parses_error_node_ids_for_failed_tests_retry_context(self):
        text = textwrap.dedent("""\
            ERROR tests/test_api.py::test_alpha - ValueError: bad
            FAILED tests/test_api.py::test_beta - AssertionError: expected 1
            1 failed, 1 error, 41 passed in 0.45s
        """)

        counts = orch._parse_pytest_summary_counts(text)

        assert counts == {"passed_count": 41, "failed_count": 1, "error_count": 1}
        assert orch._parse_pytest_failed_tests(
            text,
            failed_count=1,
            error_count=1,
        ) == [
            "tests/test_api.py::test_alpha",
            "tests/test_api.py::test_beta",
        ]

    def test_stored_test_diagnostic_preserves_first_traceback_and_node_id(self):
        text = textwrap.dedent("""\
            ..FF                                                                     [100%]
            =================================== FAILURES ===================================
            _________________________________ test_alpha __________________________________
            tests/test_api.py:10: in test_alpha
                assert value == 1
            E   AssertionError: expected 1
            _________________________________ test_beta ___________________________________
            tests/test_api.py:20: in test_beta
                raise ValueError("bad")
            E   ValueError: bad
            =========================== short test summary info ============================
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            FAILED tests/test_api.py::test_beta - ValueError: bad
            2 failed, 41 passed in 0.45s
        """)

        stored = orch._stored_test_diagnostic(text)

        assert "_________________________________ test_alpha __________________________________" in stored
        assert "tests/test_api.py:10: in test_alpha" in stored
        assert "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in stored
        assert "2 failed, 41 passed in 0.45s" in stored
        assert "[1 additional failing test omitted from diagnostic excerpt]" in stored
        assert "FAILED tests/test_api.py::test_beta - ValueError: bad" not in stored

    def test_stored_test_diagnostic_preserves_first_error_traceback_and_node_id(self):
        text = textwrap.dedent("""\
            ..E                                                                      [100%]
            ==================================== ERRORS ====================================
            ___________________ ERROR at setup of test_alpha ___________________
            tests/test_api.py:10: in test_alpha
                raise ValueError("bad")
            E   ValueError: bad
            =========================== short test summary info ============================
            ERROR tests/test_api.py::test_alpha - ValueError: bad
            1 error, 41 passed in 0.45s
        """)

        stored = orch._stored_test_diagnostic(text)

        assert "ERROR at setup of test_alpha" in stored
        assert "tests/test_api.py:10: in test_alpha" in stored
        assert "ERROR tests/test_api.py::test_alpha - ValueError: bad" in stored
        assert "1 error, 41 passed in 0.45s" in stored


