class TestCheckDependencies:
    def test_all_merged(self, repo: Path):
        # my-feature has no dependencies.
        blockers = orch.check_dependencies_merged(repo, "my-feature")
        assert blockers == []

    def test_unmet_dependency(self, repo: Path):
        blockers = orch.check_dependencies_merged(repo, "depends-on-both")
        assert len(blockers) == 1
        assert "dep-b" in blockers[0]
        assert "not-started" in blockers[0]

    def test_missing_dependency_file(self, repo: Path):
        # Create a spec that depends on a nonexistent spec
        (repo / "specs" / "bad-dep.md").write_text(
            textwrap.dedent("""\
            ---
            id: bad-dep
            status: not-started
            depends_on: [nonexistent-spec]
            description: Bad dep
            ---
        """)
        )
        blockers = orch.check_dependencies_merged(repo, "bad-dep")
        assert len(blockers) == 1
        assert "missing spec file" in blockers[0]

    def test_tag_override(self, repo: Path):
        """A merged tag unblocks a dependency regardless of frontmatter."""
        _run_git("tag", "spec/merged/dep-b", cwd=repo)
        blockers = orch.check_dependencies_merged(repo, "depends-on-both")
        assert blockers == []

    def test_superseded_dependency(self, repo: Path):
        blockers = orch.check_dependencies_merged(repo, "depends-on-superseded")
        assert len(blockers) == 1
        assert blockers[0] == "old-spec (superseded by new-spec)"

    def test_task_spec_dependency_is_merged_via_tag(self, repo: Path):
        """A dependency whose spec lives at specs/tasks/<id>.md is satisfied by a merge tag.

        The spec file only needs to exist on disk for the resolver to find it; the
        merge-tag ancestry check is independent. We tag the existing HEAD (which is
        already on origin/master from the fixture) so the dependency reads as merged.
        """
        task_dir = repo / "specs" / "tasks"
        task_dir.mkdir(parents=True, exist_ok=True)
        (task_dir / "dep-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: dep-task
            ---
        """)
        )
        (repo / "specs" / "depends-on-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: depends-on-task
            status: not-started
            depends_on: [dep-task]
            description: Depends on a task spec
            ---
        """)
        )
        _create_annotated_merge_tag(cwd=repo, spec_id="dep-task")

        assert orch.check_dependencies_merged(repo, "depends-on-task") == []

    def test_task_spec_dependency_blocks_when_not_merged(self, repo: Path):
        """A task-spec dependency without a merge tag yields a non-merged blocker (not 'missing spec file')."""
        task_dir = repo / "specs" / "tasks"
        task_dir.mkdir(parents=True, exist_ok=True)
        (task_dir / "dep-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: dep-task
            ---
        """)
        )
        (repo / "specs" / "depends-on-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: depends-on-task
            status: not-started
            depends_on: [dep-task]
            description: Depends on a task spec
            ---
        """)
        )

        blockers = orch.check_dependencies_merged(repo, "depends-on-task")
        assert len(blockers) == 1
        assert "dep-task" in blockers[0]
        assert "missing spec file" not in blockers[0]
        assert blockers[0] != "dep-task (merged)"

    def test_task_spec_dependency_superseded(self, repo: Path):
        """A task-spec dependency with superseded_by frontmatter is reported exactly."""
        task_dir = repo / "specs" / "tasks"
        task_dir.mkdir(parents=True, exist_ok=True)
        (task_dir / "old-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: old-task
            superseded_by: new-task
            ---
        """)
        )
        (repo / "specs" / "depends-on-old-task.md").write_text(
            textwrap.dedent("""\
            ---
            id: depends-on-old-task
            status: not-started
            depends_on: [old-task]
            description: Depends on a superseded task spec
            ---
        """)
        )

        blockers = orch.check_dependencies_merged(repo, "depends-on-old-task")
        assert len(blockers) == 1
        assert blockers[0] == "old-task (superseded by new-task)"


class TestBootstrapGuards:
    def test_superseded_spec_is_blocked(self, repo: Path):
        run = orch.RunState(
            run_id="old-spec-20260101T000000",
            spec_id="old-spec",
            branch="spec/old-spec",
            agent="codex",
        )
        status = orch.phase_bootstrap(run, repo)
        assert status == "blocked"
        assert "superseded by 'new-spec'" in run.last_error

    def test_unrelated_worktree_prefix_does_not_block_bootstrap(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000000",
            agent="codex",
        )
        worktree = repo / ".worktrees" / "my-feature"
        unrelated_worktree = repo / ".worktrees" / "my-feature-extra"

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    (f"worktree {unrelated_worktree}\nHEAD deadbeef\nbranch refs/heads/code/my-feature-extra\n"),
                    "",
                )
            if cmd == [
                "git",
                "show-ref",
                "--verify",
                "--quiet",
                f"refs/heads/{run.branch}",
            ]:
                return subprocess.CompletedProcess(cmd, 1, "", "")
            if cmd == [
                "git",
                "rev-parse",
                "--verify",
                "--quiet",
                "origin/master^{commit}",
            ]:
                return subprocess.CompletedProcess(cmd, 0, "deadbeef\n", "")
            if cmd == [
                "git",
                "worktree",
                "add",
                "--no-track",
                str(worktree),
                "-b",
                run.branch,
                "origin/master",
            ]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "status", "--porcelain", "--", "specs/my-feature.md"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["make", "install"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_write_sandbox_config"),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "passed"
        assert run.last_error == ""
        assert run.worktree_path == str(worktree)

    def test_bootstrap_install_command_failure_fails_bootstrap(self, repo: Path, monkeypatch):
        """When bootstrap.install_command is configured and fails, bootstrap fails."""
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000000",
            agent="codex",
        )
        worktree = repo / ".worktrees" / "my-feature"

        # Configure an install command
        monkeypatch.setattr(
            orch,
            "SPEC_RUNTIME_CONFIG",
            orch.SPEC_RUNTIME_CONFIG.__class__(
                **{
                    **{
                        f.name: getattr(orch.SPEC_RUNTIME_CONFIG, f.name)
                        for f in orch.SPEC_RUNTIME_CONFIG.__dataclass_fields__.values()
                    },
                    "bootstrap_install_command": "pip install -e .",
                },
            ),
        )

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    (f"worktree {worktree}\nHEAD deadbeef\nbranch refs/heads/{run.branch}\n"),
                    "",
                )
            if cmd == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, run.branch + "\n", "")
            if cmd == ["git", "status", "--porcelain", "--", "specs/my-feature.md"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["sh", "-c", "pip install -e ."]:
                return subprocess.CompletedProcess(cmd, 1, "", "install failed")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_write_sandbox_config"),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "failed"

    def test_existing_worktree_on_wrong_branch_fails_fast(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
            agent="codex",
        )
        worktree = repo / ".worktrees" / run.spec_id
        worktree.parent.mkdir(parents=True, exist_ok=True)
        worktree.mkdir()

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(
                    cmd, 0, f"worktree {worktree}\nHEAD deadbeef\nbranch refs/heads/my-feature\n", ""
                )
            if cmd[:3] == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, "my-feature\n", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "failed"
        assert "is on branch 'my-feature'" in run.last_error
        assert "expected 'spec/my-feature'" in run.last_error

    def test_spec_bootstrap_materializes_pinned_spec_when_base_branch_lacks_file(self, repo: Path):
        run = orch._create_spec_run(
            repo,
            "my-feature",
            agent="codex",
            review_agent="claude",
            base_ref="origin/master",
            requested_by="test-user",
        )
        worktree = repo / ".worktrees" / "my-feature"
        source_spec = (repo / "specs" / "my-feature.md").read_text()
        git_calls: list[list[str]] = []

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            git_calls.append(cmd)
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == [
                "git",
                "show-ref",
                "--verify",
                "--quiet",
                f"refs/heads/{run.branch}",
            ]:
                return subprocess.CompletedProcess(cmd, 1, "", "")
            if cmd == [
                "git",
                "rev-parse",
                "--verify",
                "--quiet",
                "origin/master^{commit}",
            ]:
                return subprocess.CompletedProcess(cmd, 0, "deadbeef\n", "")
            if cmd == [
                "git",
                "worktree",
                "add",
                "--no-track",
                str(worktree),
                "-b",
                run.branch,
                "origin/master",
            ]:
                worktree.mkdir(parents=True, exist_ok=True)
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "status", "--porcelain", "--", "specs/my-feature.md"]:
                return subprocess.CompletedProcess(cmd, 0, "A  specs/my-feature.md\n", "")
            if cmd == ["git", "add", "specs/my-feature.md"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "commit", "-m", "Pin spec contract for my-feature"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["make", "install"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_write_sandbox_config"),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "passed"
        assert (worktree / "specs" / "my-feature.md").read_text() == source_spec
        assert ["git", "add", "specs/my-feature.md"] in git_calls
        assert ["git", "commit", "-m", "Pin spec contract for my-feature"] in git_calls

    def test_clone_backend_bootstrap_uses_full_checkout_workspace(self, repo: Path):
        run = orch._create_spec_run(
            repo,
            "my-feature",
            agent="codex",
            review_agent="claude",
            base_ref="origin/master",
            requested_by="test-user",
        )
        backend = eb.CloneExecutionBackend(
            eb.ExecutionConfig(
                backend="clone",
                workspace_root=".spec-workspaces",
                backend_explicit=True,
            )
        )
        fallback_worktree = repo / ".worktrees" / "code-my-feature--unused"

        try:
            orch.set_execution_backend(backend)
            with (
                patch.object(orch, "resolve_worktree_path", return_value=fallback_worktree),
                patch.object(orch, "_write_sandbox_config"),
            ):
                status = orch.phase_bootstrap(run, repo)
        finally:
            orch.set_execution_backend(None)

        clone_source = repo / ".spec-workspaces" / run.run_id / "source"
        assert status == "passed", run.last_error
        assert run.worktree_path == str(clone_source)
        assert clone_source.is_dir()
        assert (clone_source / ".git").is_dir()
        clone_run = orch.RunState.load(clone_source, run.run_id)
        assert clone_run.run_id == run.run_id
        assert clone_run.worktree_path == str(clone_source)
        assert not fallback_worktree.exists()
        assert _run_git_stdout(
            "status",
            "--porcelain",
            "--untracked-files=no",
            cwd=repo,
        ).strip() == ""

    def test_task_bootstrap_deletes_inherited_placeholder_spec_for_fresh_worktree(self, repo: Path):
        """Fresh task-mode worktree removes an inherited placeholder task spec."""
        run = orch.RunState(
            run_id="task-abc-20260101T000000",
            spec_id="task-abc",
            branch="task/task-abc--token",
            run_mode="task",
            agent="claude",
        )
        worktree = repo / ".worktrees" / "task-task-abc--token"

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == [
                "git",
                "show-ref",
                "--verify",
                "--quiet",
                f"refs/heads/{run.branch}",
            ]:
                return subprocess.CompletedProcess(cmd, 1, "", "")
            if cmd == [
                "git",
                "rev-parse",
                "--verify",
                "--quiet",
                "origin/master^{commit}",
            ]:
                return subprocess.CompletedProcess(cmd, 0, "deadbeef\n", "")
            if cmd[:3] == ["git", "worktree", "add"]:
                worktree.mkdir(parents=True, exist_ok=True)
                inherited_spec = worktree / "specs" / "tasks" / "task-abc.md"
                inherited_spec.parent.mkdir(parents=True, exist_ok=True)
                inherited_spec.write_text("inherited task spec\n")
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["make", "install"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_write_sandbox_config"),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "passed"
        assert not (worktree / "specs" / "tasks" / "task-abc.md").exists()

    def test_task_bootstrap_preserves_task_spec_on_resume(self, repo: Path):
        """Resumed task-mode worktree keeps the existing canonical task spec."""
        run = orch.RunState(
            run_id="task-abc-20260101T000000",
            spec_id="task-abc",
            branch="task/task-abc--token",
            run_mode="task",
            agent="claude",
        )
        worktree = repo / ".worktrees" / "task-task-abc--token"
        worktree.mkdir(parents=True, exist_ok=True)
        spec_path = worktree / "specs" / "tasks" / "task-abc.md"
        spec_path.parent.mkdir(parents=True, exist_ok=True)
        spec_path.write_text(
            textwrap.dedent("""\
            ---
            id: task-abc
            status: task
            depends_on: []
            description: scoped spec from prior run
            ---
        """)
        )

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    f"worktree {worktree}\nHEAD deadbeef\nbranch refs/heads/{run.branch}\n",
                    "",
                )
            if cmd[:3] == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, f"{run.branch}\n", "")
            if cmd == ["make", "install"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_write_sandbox_config"),
        ):
            status = orch.phase_bootstrap(run, repo)

        assert status == "passed"
        assert spec_path.exists()
        assert "scoped spec from prior run" in spec_path.read_text()


class TestReviewWorktreeBootstrap:
    """Bootstrap of the local review worktree before launching the reviewer."""

    @staticmethod
    def _config_with_install(command: str):
        return replace(orch.SPEC_RUNTIME_CONFIG, bootstrap_install_command=command)

    def test_runs_trusted_bootstrap_command_with_stripped_env(self, tmp_path: Path):
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"
        marker = worktree / "env-dump.txt"

        with (
            patch.object(
                orch,
                "SPEC_RUNTIME_CONFIG",
                self._config_with_install(f"env > {marker}"),
            ),
            patch.dict(
                os.environ,
                {
                    "GITHUB_TOKEN": "secret",
                    "GH_TOKEN": "secret",
                    "ANTHROPIC_API_KEY": "sk-secret",
                    "CLAUDE_CODE_OAUTH_TOKEN": "oauth-secret",
                    "PATH": "/usr/bin",
                },
                clear=False,
            ),
        ):
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )

        assert warning == ""
        assert not warning_path.exists()
        # Confirms the command actually ran in the review worktree's cwd.
        assert marker.is_file()
        dumped_env = marker.read_text()
        # Review-scoped credentials must be stripped from the bootstrap env.
        assert "GITHUB_TOKEN" not in dumped_env
        assert "GH_TOKEN" not in dumped_env
        # The bootstrap runs the PR head's untrusted build hooks, so agent auth
        # must not leak into it.
        assert "ANTHROPIC_API_KEY" not in dumped_env
        assert "CLAUDE_CODE_OAUTH_TOKEN" not in dumped_env

    def test_legacy_posix_bootstrap_preserves_login_shell_launch(self, tmp_path: Path):
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        captured: dict[str, object] = {}

        class Process:
            returncode = 0

            def communicate(self, timeout: float):
                return "", ""

        def popen(argv, **kwargs):
            captured["argv"] = argv
            return Process()

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", self._config_with_install("echo ok")),
            patch.object(orch.subprocess, "Popen", side_effect=popen),
        ):
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=tmp_path / "warning.json"
            )

        assert warning == ""
        assert captured["argv"] == ["sh", "-lc", "echo ok"]

    def test_bootstrap_cannot_read_real_home_credentials(self, tmp_path: Path):
        """Stripping named credential env vars is not enough on its own: build
        hooks run as the same OS user and can read credential files straight
        off disk (``~/.ssh``, ``~/.codex/auth.json``, ...) regardless of which
        env vars are set. The bootstrap subprocess must get an isolated,
        empty ``HOME`` so PR-head build hooks can't reach the operator's real
        credential store.
        """
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"

        real_home = tmp_path / "real-home"
        secret = real_home / ".codex" / "auth.json"
        secret.parent.mkdir(parents=True)
        secret.write_text("super-secret-codex-token")

        found_marker = worktree / "found-secret.txt"
        observed_home = worktree / "observed-home.txt"
        install_cmd = (
            f'echo "$HOME" > {observed_home}; '
            f'[ -f "$HOME/.codex/auth.json" ] && cp "$HOME/.codex/auth.json" {found_marker} || true'
        )

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", self._config_with_install(install_cmd)),
            patch.dict(
                os.environ,
                {"HOME": str(real_home), "CODEX_HOME": str(real_home / ".codex")},
                clear=False,
            ),
        ):
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )

        assert warning == ""
        assert not found_marker.exists(), "bootstrap subprocess read a credential file from the real HOME"
        observed = observed_home.read_text().strip()
        assert observed != str(real_home)
        # The isolated HOME is a temp dir removed once bootstrap finishes.
        assert not Path(observed).exists()

    def test_records_warning_when_bootstrap_fails(self, tmp_path: Path):
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"

        with patch.object(
            orch,
            "SPEC_RUNTIME_CONFIG",
            self._config_with_install("echo 'boom: build hook failed' >&2; exit 1"),
        ):
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )

        assert warning
        assert warning_path.is_file()
        payload = json.loads(warning_path.read_text())
        assert payload["command"] == "echo 'boom: build hook failed' >&2; exit 1"
        assert "boom: build hook failed" in payload["detail"]

    def test_records_warning_on_timeout(self, tmp_path: Path):
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", self._config_with_install("sleep 30")),
            patch.object(orch, "REVIEW_BOOTSTRAP_TIMEOUT_SECONDS", 0.2),
        ):
            started = time.monotonic()
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )
            elapsed = time.monotonic() - started

        assert warning
        assert "timed out" in warning
        assert warning_path.is_file()
        # Must not wait out the full untrusted command; the timeout is enforced.
        assert elapsed < 15

    def test_timeout_kills_whole_process_group_not_just_the_shell(self, tmp_path: Path):
        """A regression test for a hang: the untrusted install command can fork
        a background child that outlives the shell and keeps stdout/stderr
        open. Killing only the ``sh`` process (as a plain
        ``subprocess.run(..., timeout=...)`` would) leaves that child running
        and can block the caller waiting for the pipes to close. The bootstrap
        must run the command in its own process group and kill the whole
        group on timeout so it reliably falls back to diff-only review.
        """
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"
        marker = worktree / "child-alive"
        # The backgrounded child inherits stdout/stderr (kept open) and, absent
        # a group kill, would keep running/writing long past the timeout.
        install_cmd = f"(sleep 5; touch {marker}) & sleep 30"

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", self._config_with_install(install_cmd)),
            patch.object(orch, "REVIEW_BOOTSTRAP_TIMEOUT_SECONDS", 0.2),
        ):
            started = time.monotonic()
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )
            elapsed = time.monotonic() - started

        assert warning
        assert "timed out" in warning
        assert elapsed < 15
        # Give the backgrounded child a chance to run if it survived the kill.
        time.sleep(6)
        assert not marker.exists(), "background child survived the timeout kill"

    def test_no_configured_command_skips_bootstrap(self, tmp_path: Path):
        worktree = tmp_path / "review-worktree"
        worktree.mkdir()
        warning_path = tmp_path / "warning.json"

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", self._config_with_install("")),
            patch.object(orch.subprocess, "Popen", side_effect=AssertionError("should not run")),
        ):
            warning = orch._bootstrap_review_worktree(
                tmp_path / "repo", worktree, warning_path=warning_path
            )

        assert warning == ""
        assert not warning_path.exists()


