    def test_render_specs_table_uses_repo_base_ref_not_module_global(self, repo: Path):
        (repo / ".spec.toml").write_text(
            textwrap.dedent("""\
            base_ref = "origin/main"

            [paths]
            specs_dir = "plans"
        """)
        )
