    @pytest.mark.parametrize("workflow_result", ["blocked", "waiting-for-input"])
    def test_manual_terminal_wait_states_release_then_reacquire_on_resume(self, repo: Path, workflow_result: str):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000000",
            phase="implement",
            status="failed",
            agent="codex",
        )
        run.save(repo)
        events: list[tuple[str, dict[str, object]]] = []

        class FakeClient:
            def acquire_lease(self, payload):
                events.append(("acquire", dict(payload)))
                return {"lease_id": f"lease-{len(events)}"}

            def release_lease(self, lease_id, payload):
                events.append(("release", {"lease_id": lease_id, **dict(payload)}))
                return {"lease_id": lease_id, "status": "released"}

        def fake_workflow(active_run, root, *, retry_cap):
            active_run.status = workflow_result
            active_run.phase = "implement"
            active_run.save(root)
            return workflow_result

        with patch.object(orch, "SPEC_RUNTIME_CONFIG", self._coord_config()), patch.object(
            orch, "resolve_repo_root", return_value=repo
        ), patch.object(orch, "build_coordinator_client", return_value=FakeClient()), patch.object(
            orch, "run_full_workflow", side_effect=fake_workflow
        ):
            first_rc = orch.cmd_run(self._run_args(run=run.run_id))
            second_rc = orch.cmd_run(self._run_args(run=run.run_id))

        assert first_rc == 2
        assert second_rc == 2
        assert [event for event, _payload in events] == ["acquire", "release", "acquire", "release"]
        assert events[0][1]["run_id"] == run.run_id
        assert events[2][1]["run_id"] == run.run_id
        assert events[1][1]["final_state"] == workflow_result
        assert events[3][1]["final_state"] == workflow_result

