    def test_manual_heartbeat_failure_records_error_and_releases_lease(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000000",
            phase="verify",
            status="running",
            agent="codex",
        )
        run.save(repo)
        events: list[tuple[str, dict[str, object]]] = []

        class FakeClient:
            def acquire_lease(self, payload):
                events.append(("acquire", dict(payload)))
                return {"lease_id": "77"}

            def release_lease(self, lease_id, payload):
                events.append(("release", {"lease_id": lease_id, **dict(payload)}))
                return {"lease_id": lease_id, "status": "released"}

        def fail_workflow(_run, _root, *, retry_cap):
            raise RuntimeError("Coordinator lease heartbeat failed closed: timeout")

        with patch.object(orch, "SPEC_RUNTIME_CONFIG", self._coord_config()), patch.object(
            orch, "resolve_repo_root", return_value=repo
        ), patch.object(orch, "build_coordinator_client", return_value=FakeClient()), patch.object(
            orch, "run_full_workflow", side_effect=fail_workflow
        ):
            rc = orch.cmd_run(self._run_args(run=run.run_id))

        saved = orch.RunState.load(repo, run.run_id)
        assert rc == 1
        assert saved.status == "failed"
        assert "Coordinator lease heartbeat failed closed" in saved.last_error
        assert [event for event, _payload in events] == ["acquire", "release"]
        assert events[-1][1]["final_state"] == "failed"

