    def test_background_heartbeat_failure_interrupts_active_phase_subprocess(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        run = orch.RunState(
            run_id="my-feature-20260101T000001",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000001",
            phase="verify",
            status="running",
            agent="codex",
        )
        run.save(repo)
        orch._ACTIVE_COORDINATOR_LEASE = orch.ActiveCoordinatorLease(
            lease_id="99",
            run_id=run.run_id,
            spec_id=run.spec_id,
            agent="codex",
            payload={},
        )
        monkeypatch.setattr(orch, "LEASE_HEARTBEAT_INTERVAL_SECONDS", 0.05)
        heartbeat_calls = 0

        class FakeClient:
            def heartbeat_lease(self, lease_id, payload):
                nonlocal heartbeat_calls
                heartbeat_calls += 1
                if heartbeat_calls > 1:
                    raise CoordinatorLeaseConflictError(
                        "lost",
                        lease={"machine_id": "machine-b", "run_id": run.run_id},
                    )
                return {"lease_id": lease_id, "status": "renewed"}

        def long_phase(_run: orch.RunState, _repo_root: Path) -> str:
            orch.run_subprocess(
                [sys.executable, "-c", "import time; time.sleep(30)"],
                cwd=repo,
            )
            return "passed"

        started_at = time.monotonic()
        try:
            with patch.object(orch, "SPEC_RUNTIME_CONFIG", self._coord_config()), patch.object(
                orch, "build_coordinator_client", return_value=FakeClient()
            ), patch.dict(orch.PHASE_HANDLERS, {"verify": long_phase}):
                result = orch.run_single_phase(run, "verify", repo)
        finally:
            orch._ACTIVE_COORDINATOR_LEASE = None

        assert result == "failed"
        assert time.monotonic() - started_at < 5
        assert heartbeat_calls >= 2
        assert "owner=machine-b" in run.last_error

