    def test_classify_completion_recognizes_skip_conditions(self):
        assert autopilot.classify_completion(["Error: Lock contention: another process holds the lock"]) == "skip"
        assert autopilot.classify_completion(["Spec 'my-feature' is already merged on origin/master"]) == "skip"
        assert autopilot.classify_completion(["unexpected failure"]) == "failure"
        assert (
            autopilot.classify_completion(
                [],
                run_record={"status": "passed", "phase": "merge", "run_id": "r1"},
                expected_run_id="r1",
            )
            == "success"
        )
        assert (
            autopilot.classify_completion(
                [],
                run_record={"status": "passed", "phase": "cleanup"},
            )
            == "success"
        )
        assert (
            autopilot.classify_completion(
                [],
                run_record={"status": "passed", "phase": "review"},
            )
            == "failure"
        )

