    def test_run_loop_attempts_acquire_when_lease_inspection_is_unavailable(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str],
    ):
        candidate = autopilot.DispatchCandidate(
            spec_id="worker-feature",
            agent="codex",
            area="backend",
            priority=10,
            unlock_count=0,
            status="not-started",
            lease_state="coordinator-unavailable",
            lease_message="forbidden",
        )
        acquired: list[str] = []
        launched: list[tuple[str, str]] = []
        captured_handlers: dict[int, object] = {}

        args = argparse.Namespace(
            repo_root=str(repo),
            concurrency=1,
            poll_interval=0,
            notify=[],
            notify_backends=[],
            notify_success=False,
            dry_run=False,
            agent="",
        )

        def fake_signal(sig, handler):  # noqa: ANN001
            captured_handlers[sig] = handler
            return None

        def fake_sleep(_seconds):  # noqa: ANN001
            handler = captured_handlers.get(signal.SIGINT)
            assert handler is not None
            handler(signal.SIGINT, None)

        def fake_acquire(_repo_root: Path, item: autopilot.DispatchCandidate):
            acquired.append(item.spec_id)
            return "worker-feature-run", {"lease_id": "lease-1"}

        def fake_start(
            _repo_root: Path,
            item: autopilot.DispatchCandidate,
            *,
            preallocated_run_id: str = "",
        ) -> autopilot.ActiveRunProcess:
            launched.append((item.spec_id, preallocated_run_id))
            return autopilot.ActiveRunProcess(
                spec_id=item.spec_id,
                agent=item.agent,
                pid=4321,
                started_at="2026-01-01T00:00:00+00:00",
                started_monotonic=autopilot.time.monotonic(),
                log_path=str(repo / "worker-feature.log"),
                run_id=preallocated_run_id,
                process_started_at="Mon Mar 17 12:00:00 2026",
            )

        monkeypatch.setattr(autopilot, "ensure_pid_file", lambda _repo_root: None)
        monkeypatch.setattr(autopilot, "remove_pid_file", lambda _repo_root: None)
        monkeypatch.setattr(autopilot, "adopt_active_processes", lambda _repo_root: {})
        monkeypatch.setattr(autopilot, "write_active_state", lambda *a, **k: None)
        monkeypatch.setattr(autopilot, "refresh_runtime_git_refs", lambda _repo_root: (True, ""))
        monkeypatch.setattr(autopilot, "collect_git_spec_state", lambda _repo_root: object())
        monkeypatch.setattr(autopilot, "load_run_record_index", lambda _repo_root: autopilot.RunRecordIndex())
        monkeypatch.setattr(
            autopilot,
            "build_dispatch_queue",
            lambda *_args, **_kwargs: [] if launched else [candidate],
        )
        monkeypatch.setattr(autopilot, "available_memory_bytes", lambda: 8 * 1024 * 1024 * 1024)
        monkeypatch.setattr(autopilot, "acquire_candidate_lease", fake_acquire)
        monkeypatch.setattr(autopilot, "start_candidate", fake_start)
        monkeypatch.setattr(autopilot, "is_pid_alive", lambda *a, **k: False)
        monkeypatch.setattr(autopilot, "read_latest_run_phase", lambda *a, **k: "merge")
        monkeypatch.setattr(autopilot, "read_log_tail", lambda _path: [])
        monkeypatch.setattr(
            autopilot,
            "read_latest_run_record",
            lambda *_args, **_kwargs: {"run_id": "worker-feature-run", "status": "passed", "phase": "merge"},
        )
        monkeypatch.setattr(autopilot.signal, "signal", fake_signal)
        monkeypatch.setattr(autopilot.time, "sleep", fake_sleep)

        assert autopilot.run_loop(args) == 0

        captured = capsys.readouterr()
        assert acquired == ["worker-feature"]
        assert launched == [("worker-feature", "worker-feature-run")]
        assert "lease inspection unavailable; attempting acquire: forbidden" in captured.out
        assert "spec coord doctor" in captured.out

