    def test_run_loop_forces_shutdown_on_second_signal(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        from spec_runtime.control_plane import ShutdownPhase
        from spec_runtime.control_plane.shutdown import shutdown_state_path

        captured: dict[str, object] = {}

        def fake_signal(sig, handler):  # noqa: ANN001
            if sig == signal.SIGINT:
                captured["sigint"] = handler
            return None

        existing_proc = autopilot.ActiveRunProcess(
            spec_id="stuck-spec",
            agent="codex",
            pid=999_999,
            started_at="2026-01-01T00:00:00+00:00",
            started_monotonic=0.0,
            log_path=str(repo / "stuck.log"),
            run_id="stuck-run",
            phase="implement",
            process_started_at="never",
        )

        sleep_calls = {"count": 0}

        def fake_sleep(_seconds):  # noqa: ANN001
            sleep_calls["count"] += 1
            handler = captured.get("sigint")
            assert handler is not None
            handler(signal.SIGINT, None)
            if sleep_calls["count"] >= 3:
                raise AssertionError("loop should have broken after second interrupt")

        args = argparse.Namespace(
            repo_root=str(repo),
            concurrency=1,
            poll_interval=0,
            notify=[],
            notify_backends=[],
            notify_success=False,
            dry_run=False,
            agent="",
        )

        monkeypatch.setattr(autopilot, "ensure_pid_file", lambda _repo_root: None)
        monkeypatch.setattr(autopilot, "remove_pid_file", lambda _repo_root: None)
        monkeypatch.setattr(
            autopilot,
            "adopt_active_processes",
            lambda _repo_root: {"stuck-spec": existing_proc},
        )
        monkeypatch.setattr(autopilot, "write_active_state", lambda *a, **k: None)
        monkeypatch.setattr(autopilot, "read_latest_run_phase", lambda *a, **k: "implement")
        monkeypatch.setattr(autopilot, "is_pid_alive", lambda *a, **k: True)
        monkeypatch.setattr(autopilot.signal, "signal", fake_signal)
        monkeypatch.setattr(autopilot.time, "sleep", fake_sleep)

        assert autopilot.run_loop(args) == 0

        state_path = shutdown_state_path(autopilot.autopilot_state_root(repo))
