    def test_collect_run_rows_sorts_terminal_newest_first(self, repo: Path):
        runs_dir = repo / ".spec-state" / "runs"
        runs_dir.mkdir(parents=True, exist_ok=True)

        # Create three terminal runs with different timestamps
        for i, (spec, status, ts) in enumerate(
            [
                ("old-fail", "failed", "2026-03-15T10:00:00+00:00"),
                ("mid-fail", "failed", "2026-03-16T10:00:00+00:00"),
                ("new-fail", "failed", "2026-03-17T10:00:00+00:00"),
            ]
        ):
            (runs_dir / f"run-{i}.json").write_text(
                json.dumps(
                    {
                        "spec_id": spec,
                        "status": status,
                        "agent": "claude",
                        "created_at": ts,
                    }
                )
            )

        rows = autopilot._collect_run_rows(repo, {})
        spec_ids = [r["spec_id"] for r in rows]
        assert spec_ids == ["new-fail", "mid-fail", "old-fail"]

