    def test_watch_command_non_tty_prints_once(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        """watch_command prints a single screen and exits in non-TTY mode."""
        from datetime import UTC, datetime

        (repo / "specs" / "obsolete-feature.md").write_text(
            textwrap.dedent("""\
            ---
            id: obsolete-feature
            status: obsolete
            depends_on: []
            area: backend
            description: Hidden from legacy watch output
            ---
        """)
        )
        runs_dir = repo / ".spec-state" / "runs"
        runs_dir.mkdir(parents=True, exist_ok=True)
        now_iso = datetime.now(UTC).isoformat()
        (runs_dir / "my-feature-run.json").write_text(
            json.dumps(
                {
                    "spec_id": "my-feature",
                    "status": "running",
                    "phase": "implement",
                    "agent": "claude",
                    "created_at": now_iso,
                    "heartbeat_at": now_iso,
                }
            )
        )
        (runs_dir / "obsolete-feature-run.json").write_text(
            json.dumps(
                {
                    "spec_id": "obsolete-feature",
                    "status": "running",
                    "phase": "implement",
                    "agent": "codex",
                    "created_at": now_iso,
                    "heartbeat_at": now_iso,
                }
            )
        )

        monkeypatch.setattr(autopilot, "resolve_repo_root", lambda _p: repo)
        monkeypatch.setattr(
            autopilot,
            "refresh_runtime_git_refs",
            lambda _r: (True, ""),
        )

        # Wrap load_run_record_index with a counter to verify single call per render
        load_index_call_count = 0
        _original_load = autopilot.load_run_record_index

        def _counting_load(r):
            nonlocal load_index_call_count
            load_index_call_count += 1
            return _original_load(r)

        monkeypatch.setattr(autopilot, "load_run_record_index", _counting_load)

        args = argparse.Namespace(
            repo_root=str(repo),
            interval=5,
            agent=None,
        )

        captured: list[str] = []

        class FakeStdout:
            def isatty(self):
                return False

            def write(self, s):
                captured.append(s)

            def flush(self):
                pass

        fake_out = FakeStdout()
        monkeypatch.setattr(sys, "stdout", fake_out)
        # stdin also non-TTY
        monkeypatch.setattr(sys, "stdin", io.StringIO(""))

        result = autopilot.watch_command(args)

        assert result == 0
        output = "".join(captured)
        assert "Spec Runs" in output
        assert "my-feature" in output
        assert "obsolete-feature" not in output
        # load_run_record_index should be called exactly once per render cycle
        assert load_index_call_count == 1

