    def test_windows_v2_pid_record_uses_targeted_generation_without_argv(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        record = autopilot.PidFileRecord(
            pid=4242,
            started_at="2026-09-01T03:00:00+00:00",
            command=r"C:\old-venv\Scripts\spec.exe auto run",
            instance_id="dispatcher-generation",
            nonce="secret-nonce",
        )
        tracker = autopilot.ShutdownTracker(
            autopilot.autopilot_state_root(repo),
            instance_id=record.instance_id,
            pid=record.pid,
            process_started_at=record.started_at,
            nonce=record.nonce,
        )
        tracker.initialize()
        executable_only = autopilot.ProcessIdentity(
            pid=record.pid,
            started_at=record.started_at,
            command=r"C:\Python\python.exe",
        )
        assert autopilot._pid_record_has_live_dispatcher_generation(repo, record)
        tracker.mark_complete()
        assert not autopilot._pid_record_has_live_dispatcher_generation(repo, record)
        tracker.initialize()

        monkeypatch.setattr(
            autopilot,
            "_pid_record_has_live_dispatcher_generation",
            lambda _repo, _record: True,
        )
        monkeypatch.setattr(autopilot.os, "name", "nt")

        assert autopilot._pid_record_matches_process(
            record,
            executable_only,
            repo_root=repo,
        )

    def test_stop_command_refuses_to_signal_stale_recycled_pid(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str],
    ):
        pid_path = autopilot.autopilot_pid_path(repo)
        pid_path.parent.mkdir(parents=True, exist_ok=True)
        pid_path.write_text(
            json.dumps(
                {
                    "pid": 4242,
                    "started_at": "Tue Mar 17 12:00:00 2026",
                    "command": "python scripts/spec_autopilot.py run",
                }
            )
            + "\n"
        )
        kill_mock = MagicMock(side_effect=AssertionError("should not signal stale pid"))

        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: (
                autopilot.ProcessIdentity(
                    pid=4242,
                    started_at="Tue Mar 17 12:12:00 2026",
                    command="python some_other_script.py",
                )
                if pid == 4242
                else None
            ),
        )
        monkeypatch.setattr(autopilot.os, "kill", kill_mock)

        code = autopilot.stop_command(argparse.Namespace(repo_root=str(repo)))

        captured = capsys.readouterr()
        assert code == 1
        # The pid is live but belongs to something else: refuse to signal it, and
        # say which fields disagree rather than printing the bare word "stale".
        assert "not an autopilot process" in captured.err
        assert "some_other_script.py" in captured.err
        kill_mock.assert_not_called()
        # The pid file must survive. Deleting it on a
        # rejected record is what left a repo with a live, unstoppable daemon and
        # no handle to it. A leftover record blocks nothing — ensure_pid_file
        # rewrites records it does not recognise.
        assert pid_path.exists()

    def test_stop_command_signals_autopilot_whose_recorded_identity_drifted(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str],
    ):
        """A daemon that outlives a spec upgrade must stay stoppable.

        The pid file is written once at launch; `spec auto stop` runs whatever
        version is installed today. Requiring exact equality on started_at and
        the full command string turned a live dispatcher into a permanently
        "stale" record that could never be signalled.
        """
        pid_path = autopilot.autopilot_pid_path(repo)
        pid_path.parent.mkdir(parents=True, exist_ok=True)
        pid_path.write_text(
            json.dumps(
                {
                    "pid": 4242,
                    "started_at": "Fri Aug  7 09:00:00 2026",
                    "command": "/old/venv/bin/python /old/bin/spec auto run --concurrency 2",
                }
            )
            + "\n"
        )
        kill_mock = MagicMock()
        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: (
                autopilot.ProcessIdentity(
                    pid=4242,
                    started_at="Fri Aug 07 09:00:00 2026",
                    command="/new/venv/bin/python /new/bin/spec auto run --concurrency 4",
                )
                if pid == 4242
                else None
            ),
        )
        # Drift is only forgiven once the process is confirmed to be running in
        # this repo.
        monkeypatch.setattr(autopilot, "read_process_cwd", lambda pid: repo.resolve())
        monkeypatch.setattr(autopilot.os, "kill", kill_mock)

        code = autopilot.stop_command(argparse.Namespace(repo_root=str(repo)))

        captured = capsys.readouterr()
        assert code == 0
        kill_mock.assert_called_once_with(4242, signal.SIGTERM)
        assert pid_path.exists()
        # The drift is reported, not silently swallowed.
        assert "started_at" in captured.err
        assert "Fri Aug  7 09:00:00 2026" in captured.err

    def test_stop_command_refuses_recycled_pid_owned_by_another_repo(
        self,
        repo: Path,
        tmp_path: Path,
        monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str],
    ):
        """The pid-file path must not signal a sibling repo's dispatcher.

        Forgiving identity drift also drops the pid-reuse guard, and "the live
        command looks like `spec auto run`" is not ownership on a host that runs
        one autopilot per repo. A stale pid file whose pid has been recycled by
        another repo's daemon must not get that daemon killed.
        """
        other_repo = tmp_path / "other-repo"
        other_repo.mkdir()
        pid_path = autopilot.autopilot_pid_path(repo)
        pid_path.parent.mkdir(parents=True, exist_ok=True)
        pid_path.write_text(
            json.dumps(
                {
                    "pid": 4242,
                    "started_at": "Fri Aug  7 09:00:00 2026",
                    "command": "/venv/bin/python /bin/spec auto run --concurrency 4",
                }
            )
            + "\n"
        )
        kill_mock = MagicMock(side_effect=AssertionError("must not signal another repo's autopilot"))
        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: (
                autopilot.ProcessIdentity(
                    pid=4242,
                    started_at="Wed Aug 12 11:00:00 2026",
                    command="/venv/bin/python /bin/spec auto run --concurrency 2",
                )
                if pid == 4242
                else None
            ),
        )
        monkeypatch.setattr(autopilot, "read_process_cwd", lambda pid: other_repo.resolve())
        monkeypatch.setattr(autopilot, "find_autopilot_processes_for_repo", lambda root: [])
        monkeypatch.setattr(autopilot.os, "kill", kill_mock)

        code = autopilot.stop_command(argparse.Namespace(repo_root=str(repo)))

        captured = capsys.readouterr()
        assert code == 1
        kill_mock.assert_not_called()
        assert "different repository" in captured.err
        assert str(other_repo.resolve()) in captured.err
        # Never hand the operator a command that kills someone else's dispatcher.
        assert "kill -TERM 4242" not in captured.err

    def test_stop_command_refuses_drifted_pid_whose_cwd_is_unreadable(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
        capsys: pytest.CaptureFixture[str],
    ):
        """Unreadable cwd is not a soft yes: refuse, and hand over the fallback."""
        pid_path = autopilot.autopilot_pid_path(repo)
        pid_path.parent.mkdir(parents=True, exist_ok=True)
        pid_path.write_text(
            json.dumps(
                {
                    "pid": 4242,
                    "started_at": "Fri Aug  7 09:00:00 2026",
                    "command": "/old/bin/spec auto run",
                }
            )
            + "\n"
        )
        kill_mock = MagicMock(side_effect=AssertionError("must not signal an unconfirmed process"))
        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: (
                autopilot.ProcessIdentity(
                    pid=4242,
                    started_at="Wed Aug 12 11:00:00 2026",
                    command="/new/bin/spec auto run",
                )
                if pid == 4242
                else None
            ),
        )
        monkeypatch.setattr(autopilot, "read_process_cwd", lambda pid: None)
        monkeypatch.setattr(autopilot.os, "kill", kill_mock)

        code = autopilot.stop_command(argparse.Namespace(repo_root=str(repo)))

        captured = capsys.readouterr()
        assert code == 1
        kill_mock.assert_not_called()
        assert "could not be read" in captured.err
        assert "kill -TERM 4242" in captured.err
        assert pid_path.exists()

    def test_stop_command_exact_identity_match_does_not_consult_cwd(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        """An exact identity match is ownership proof on its own.

        `spec auto run --repo-root X` legitimately runs with a cwd outside the
        repo, so requiring a cwd match on this path would reintroduce the
        unstoppable-daemon bug.
        """
        pid_path = autopilot.autopilot_pid_path(repo)
        pid_path.parent.mkdir(parents=True, exist_ok=True)
        identity = autopilot.ProcessIdentity(
            pid=4242,
            started_at="Fri Aug  7 09:00:00 2026",
            command="/venv/bin/python /bin/spec auto run --concurrency 4",
        )
        pid_path.write_text(
            json.dumps(
                {
                    "pid": identity.pid,
                    "started_at": identity.started_at,
                    "command": identity.command,
                }
            )
            + "\n"
        )
        kill_mock = MagicMock()
        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: identity if pid == 4242 else None,
        )
        monkeypatch.setattr(
            autopilot,
            "read_process_cwd",
            MagicMock(side_effect=AssertionError("cwd must not be consulted on an exact match")),
        )
        monkeypatch.setattr(autopilot.os, "kill", kill_mock)

        code = autopilot.stop_command(argparse.Namespace(repo_root=str(repo)))

        assert code == 0
        kill_mock.assert_called_once_with(4242, signal.SIGTERM)

    def test_cwd_belongs_to_repo_accepts_linked_worktree_of_same_repo(
        self,
        repo: Path,
        tmp_path: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        """A worktree and its main checkout share one pid file, so both count.

        Without this, stopping from a worktree would refuse to signal a daemon
        running in the main checkout.
        """
        worktree = tmp_path / "wt"
        worktree.mkdir()
        other_repo = tmp_path / "other-repo"
        other_repo.mkdir()
        common_roots = {
            worktree.resolve(): repo.resolve(),
            repo.resolve(): repo.resolve(),
            other_repo.resolve(): other_repo.resolve(),
        }
        monkeypatch.setattr(
            autopilot,
            "resolve_common_root",
            lambda path: common_roots.get(Path(path).resolve(), Path(path).resolve()),
        )

        assert autopilot._cwd_belongs_to_repo(worktree.resolve(), repo.resolve())
        assert not autopilot._cwd_belongs_to_repo(other_repo.resolve(), repo.resolve())

    def test_stop_command_recognises_console_script_autopilot_command(self):
        """`spec auto run` is the form pipx/pip installs produce.

        Only the legacy `scripts/spec_autopilot.py run` spelling was recognised,
        so every console-script daemon read as a recycled pid.
        """
        assert autopilot._is_autopilot_run_command(
            "/home/u/.local/share/pipx/venvs/specbutler/bin/python "
            "/home/u/.local/bin/spec auto run --concurrency 4"
        )
        assert autopilot._is_autopilot_run_command("spec auto run")
        assert autopilot._is_autopilot_run_command("python -m spec_runtime.autopilot run")
        # Legacy form still recognised.
        assert autopilot._is_autopilot_run_command("python scripts/spec_autopilot.py run")
        # Non-autopilot commands must not be swept up — the repo scan signals what
        # this predicate accepts, so a false positive is a killed bystander.
        assert not autopilot._is_autopilot_run_command("spec implement --spec run-thing")
        assert not autopilot._is_autopilot_run_command("spec auto stop")
        assert not autopilot._is_autopilot_run_command("python some_other_script.py")
        assert not autopilot._is_autopilot_run_command("grep spec auto run")
        assert not autopilot._is_autopilot_run_command("tail -f log spec auto run")
        assert not autopilot._is_autopilot_run_command("spec auto")

