        monkeypatch.setattr(autopilot, "is_pid_alive", lambda pid, started_at: pid == 9100)
        monkeypatch.setattr(
            autopilot,
            "read_process_identity",
            lambda pid: orch.ProcessIdentity(
                pid=pid, started_at="Mon Mar 17 12:00:00 2026", command="spec"
            )
            if pid == 9100
            else None,
        )
