        active_path.write_text(
            json.dumps(
                {
                    "no-identity": {
                        "pid": 7777,
                        "agent": "codex",
                        "started_at": "2026-03-17T12:00:00+00:00",
                        "phase": "implement",
                        "run_id": "",
                        "log_path": "/tmp/test.log",
                        "process_started_at": "",
                    },
                }
            )
        )
        # is_pid_alive should never be called since blank identity is rejected first
        monkeypatch.setattr(
            autopilot,
            "is_pid_alive",
            lambda pid, started_at: (_ for _ in ()).throw(AssertionError("should not be called")),
        )
        adopted = autopilot.adopt_active_processes(repo)
        assert adopted == {}
        captured = capsys.readouterr()
        assert "missing process identity" in captured.out

