    def test_is_stale_run_ignores_a_run_with_a_live_lease(self, tmp_path: Path):
        # run.heartbeat_at is not refreshed while a
        # phase executes, so a merge waiting on CI looks 20 minutes idle while its
        # lease is seconds old. gc --apply would have marked it failed.
        from datetime import UTC, datetime, timedelta

        from spec_runtime.control_plane.lease import build_lease, save_run_lease

        run_id = "my-feature-20260101T000000"
        save_run_lease(
            tmp_path,
            build_lease(
                run_id=run_id,
                spec_id="my-feature",
                phase="merge",
                now=datetime.now(UTC),
            ),
        )
        data = {
            "status": "running",
            "run_id": run_id,
            "heartbeat_at": (datetime.now(UTC) - timedelta(minutes=20)).isoformat(),
            "worktree_path": "/nonexistent/path",
        }
        assert autopilot._is_stale_run(data, tmp_path) is False

    def test_is_stale_run_still_flags_a_genuinely_dead_run(self, tmp_path: Path):
        from datetime import UTC, datetime, timedelta

        from spec_runtime.control_plane.lease import build_lease, save_run_lease

        run_id = "dead-20260811T000000"
        save_run_lease(
            tmp_path,
            build_lease(
                run_id=run_id,
                spec_id="dead",
                phase="verify",
                now=datetime.now(UTC) - timedelta(hours=3),
            ),
        )
        data = {
            "status": "running",
            "run_id": run_id,
            "heartbeat_at": (datetime.now(UTC) - timedelta(minutes=20)).isoformat(),
            "worktree_path": "/nonexistent/path",
        }
        assert autopilot._is_stale_run(data, tmp_path) is True

