    def test_collect_run_rows_uses_canonical_projection_for_lease_states(
        self, repo: Path
    ):
        """spec watch must derive lease/process state from the canonical
        projection so it agrees with spec status/list/dispatch."""
        from datetime import UTC, datetime, timedelta

        from spec_runtime.control_plane import RunLease, save_run_lease

        runs_dir = repo / ".spec-state" / "runs"
        runs_dir.mkdir(parents=True, exist_ok=True)
        recent_heartbeat = datetime.now(UTC).replace(microsecond=0).isoformat()
        long_ago = (datetime.now(UTC) - timedelta(hours=2)).replace(microsecond=0).isoformat()

        # Run with an expired lease: legacy heartbeat says fresh but the lease
        # timeout has elapsed, so canonical projection must classify as stale.
        expired_run_id = "expired-feat-20260101T0000"
        (runs_dir / f"{expired_run_id}.json").write_text(
            json.dumps(
                {
                    "spec_id": "expired-feat",
                    "run_id": expired_run_id,
                    "status": "running",
                    "agent": "claude",
                    "created_at": "2026-01-01T00:00:00+00:00",
                    "heartbeat_at": recent_heartbeat,
                }
            )
        )
        save_run_lease(
            runs_dir,
            RunLease(
                run_id=expired_run_id,
                spec_id="expired-feat",
                phase="implement",
                backend="worktree",
                worker_id="worker-1",
                owner_host="host-1",
                started_at=long_ago,
                heartbeat_at=long_ago,
                timeout_seconds=60.0,
            ),
        )

        # Run with status "running" but an active lease — canonical must keep
        # it as active (not flagged stale by legacy heartbeat heuristics).
        active_run_id = "active-feat-20260101T0000"
        (runs_dir / f"{active_run_id}.json").write_text(
            json.dumps(
                {
                    "spec_id": "active-feat",
                    "run_id": active_run_id,
                    "status": "running",
                    "agent": "codex",
                    "created_at": "2026-01-01T00:00:00+00:00",
                    "heartbeat_at": recent_heartbeat,
                }
            )
        )
        save_run_lease(
            runs_dir,
            RunLease(
                run_id=active_run_id,
                spec_id="active-feat",
                phase="implement",
                backend="worktree",
                worker_id="worker-2",
                owner_host="host-2",
                started_at=recent_heartbeat,
                heartbeat_at=recent_heartbeat,
                timeout_seconds=600.0,
            ),
        )

        # Run with status "blocked" — canonical projection classifies BLOCKED.
        blocked_run_id = "blocked-feat-20260101T0000"
        (runs_dir / f"{blocked_run_id}.json").write_text(
            json.dumps(
                {
                    "spec_id": "blocked-feat",
                    "run_id": blocked_run_id,
                    "status": "blocked",
                    "agent": "claude",
                    "created_at": "2026-01-01T00:00:00+00:00",
                }
            )
        )

        rows = autopilot._collect_run_rows(repo, {})
        rows_by_spec = {r["spec_id"]: r for r in rows}

        assert rows_by_spec["expired-feat"]["status"] == "stale"
        assert "[stale]" in rows_by_spec["expired-feat"]["tag"]
        assert rows_by_spec["active-feat"]["status"] == "running"
        assert rows_by_spec["active-feat"]["tag"] == ""
        assert rows_by_spec["blocked-feat"]["status"] == "blocked"
        assert "[blocked]" in rows_by_spec["blocked-feat"]["tag"]

