    def test_gc_command_flips_canonical_stale_run_with_fresh_heartbeat(
        self,
        repo: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        """Verify can die after gates pass, leaving status=running with a
        heartbeat too fresh for the heuristic; the canonical projection
        (leases + gate records) must drive the on-disk flip too."""
        from datetime import UTC, datetime
        from types import SimpleNamespace

        from spec_runtime.control_plane import CanonicalRunStatus

        runs_dir = repo / ".spec-state" / "runs"
        runs_dir.mkdir(parents=True, exist_ok=True)
        fresh = datetime.now(UTC).isoformat()
        run_file = runs_dir / "run-gc-canonical-stale.json"
        run_file.write_text(
            json.dumps(
                {
                    "spec_id": "wedged-spec",
                    "status": "running",
                    "phase": "verify",
                    "run_id": "wedged-run-1",
                    "heartbeat_at": fresh,
                    "worktree_path": "/nonexistent/wedged/path",
                    "created_at": fresh,
                }
            )
        )
        monkeypatch.setattr(autopilot, "resolve_repo_root", lambda _p: repo)
        monkeypatch.setattr(
            autopilot,
            "project_run_record_status",
            lambda _runs_dir, data, **kw: (
                SimpleNamespace(status=CanonicalRunStatus.STALE)
                if data.get("run_id") == "wedged-run-1" and kw.get("require_lease") is True
                else None
            ),
        )
        args = argparse.Namespace(repo_root=str(repo), apply=True)
        assert autopilot.gc_command(args) == 0
        data = json.loads(run_file.read_text())
        assert data["status"] == "failed"
        assert data["gc_reason"] == "canonical stale projection"

