    def test_audit_and_backfill(self, repo: Path):
        (repo / "specs" / "legacy-merged.md").write_text(
            textwrap.dedent("""\
            ---
            id: legacy-merged
            status: merged
            depends_on: []
            description: Needs merge tag
            ---
        """)
        )
        (repo / "legacy-merged.txt").write_text("legacy\n")
        _run_git("add", "legacy-merged.txt", cwd=repo)
        _run_git("commit", "-m", "merge legacy-merged", cwd=repo)
        _run_git("push", "origin", "HEAD:refs/heads/master", cwd=repo)

        assert spec_backfill.main(["audit", "--repo-root", str(repo)]) == 1

        assert spec_backfill.main(["backfill", "--repo-root", str(repo), "--dry-run"]) == 0
        assert _run_git_expect_fail(
            "rev-parse",
            "--verify",
            "--quiet",
            "refs/tags/spec/merged/legacy-merged",
            cwd=repo,
        )

        assert spec_backfill.main(["backfill", "--repo-root", str(repo)]) == 0
        assert (
            _run_git_stdout(
                "cat-file",
                "-t",
                "refs/tags/spec/merged/legacy-merged",
                cwd=repo,
            ).strip()
            == "tag"
        )
        target_sha = _run_git_stdout(
            "rev-parse",
            "refs/tags/spec/merged/legacy-merged^{commit}",
            cwd=repo,
        ).strip()
        assert target_sha

        assert spec_backfill.main(["audit", "--repo-root", str(repo)]) == 0
        assert spec_backfill.main(["backfill", "--repo-root", str(repo)]) == 0
        assert (
            _run_git_stdout(
                "rev-parse",
                "refs/tags/spec/merged/legacy-merged^{commit}",
                cwd=repo,
            ).strip()
            == target_sha
        )

