class TestRunOrFail:
    def test_sets_last_error_on_failure(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        failed_result = subprocess.CompletedProcess(
            args=["git", "push"],
            returncode=1,
            stdout="",
            stderr="push rejected",
        )
        with patch.object(orch, "run_subprocess", return_value=failed_result):
            ok = orch.run_or_fail(
                run,
                ["git", "push"],
                cwd=repo,
                action="git push",
            )
        assert ok is False
        assert "git push failed" in run.last_error
        assert "push rejected" in run.last_error

    def test_returns_true_on_success(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        ok_result = subprocess.CompletedProcess(
            args=["git", "push"],
            returncode=0,
            stdout="ok",
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=ok_result):
            ok = orch.run_or_fail(
                run,
                ["git", "push"],
                cwd=repo,
                action="git push",
            )
        assert ok is True


class TestDisablePrAutoMerge:
    def test_disable_pr_auto_merge_swallows_graphql_cant_disable(self, repo: Path):
        result = subprocess.CompletedProcess(
            args=["gh", "pr", "merge", "4", "--disable-auto"],
            returncode=1,
            stdout="",
            stderr="GraphQL: Can't disable auto-merge for this pull request. (disablePullRequestAutoMerge)",
        )
        with patch.object(orch, "run_subprocess", return_value=result):
            assert orch._disable_pr_auto_merge(repo, 4) == ""

    def test_disable_pr_auto_merge_propagates_unrelated_error(self, repo: Path):
        result = subprocess.CompletedProcess(
            args=["gh", "pr", "merge", "4", "--disable-auto"],
            returncode=1,
            stdout="",
            stderr="network unreachable",
        )
        with patch.object(orch, "run_subprocess", return_value=result):
            detail = orch._disable_pr_auto_merge(repo, 4)
        assert detail == "network unreachable"


class TestParseExportedEnv:
    def test_parses_shell_quoted_export_values(self):
        database_url = "postgresql://example:pa'ss@/example?host=/tmp/example-postgres&port=55433"
        output = (
            f"export SIM_DATABASE_URL={shlex.quote(database_url)}\n"
            f"export SIM_TEST_DATABASE_URL={shlex.quote(database_url)}\n"
        )

        parsed = orch._parse_exported_env(output)

        assert parsed == {
            "SIM_DATABASE_URL": database_url,
            "SIM_TEST_DATABASE_URL": database_url,
        }


class TestPublishPhase:
    @staticmethod
    def _prepare_checked_no_diff_branch(repo: Path, branch: str) -> str:
        spec_path = repo / "specs" / "my-feature.md"
        spec_path.write_text(spec_path.read_text().replace("- [ ]", "- [x]"))
        # Production repositories ignore orchestrator-owned run state. The
        # compact fixture keeps that contract explicit so the cleanliness
        # assertion exercises user files rather than phase bookkeeping.
        (repo / ".gitignore").write_text(".spec-state/\n")
        _run_git("add", "specs/my-feature.md", ".gitignore", cwd=repo)
        _run_git("commit", "-m", "record completed retroactive spec", cwd=repo)
        _run_git("push", "origin", "HEAD:refs/heads/master", cwd=repo)
        _run_git("checkout", "-b", branch, cwd=repo)
        return _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip()

    def test_publish_retries_with_verified_no_diff_completion_provenance(self, repo: Path):
        branch = "code/my-feature--token123"
        verified_head = self._prepare_checked_no_diff_branch(repo, branch)
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch=branch,
            worktree_path=str(repo),
            spec_path="specs/my-feature.md",
            verify_passed_once=True,
            verify_head_sha=verified_head,
            agent="codex",
        )
        forge = MagicMock()
        forge.find_pr_for_branch.return_value = None
        forge.push_branch.return_value = orch.PushResult(ok=True)
        forge.create_pr.side_effect = [
            RuntimeError(
                "gh pr create failed: GraphQL: No commits between master and "
                "code/my-feature--token123 (createPullRequest)"
            ),
            MagicMock(),
        ]

        with (
            patch.object(orch, "_forge", return_value=forge),
            patch.object(orch, "_check_forge_auth", return_value=None),
            patch.object(orch, "_reset_local_review_gate_for_head"),
        ):
            result = orch.phase_publish(run, repo)

        marker_head = _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip()
        assert result == "passed"
        assert marker_head != verified_head
        assert _run_git_stdout("diff", "--stat", verified_head, marker_head, cwd=repo) == ""
        assert _run_git_stdout("log", "-1", "--format=%s", cwd=repo).strip() == (
            "Spec: record my-feature completion provenance"
        )
        assert run.verify_head_sha == marker_head
        assert run.readiness_head_sha == marker_head
        assert run.nonfatal_warnings[-1]["failure_subtype"] == "no_diff_completion_provenance"
        assert forge.push_branch.call_count == 2
        assert forge.create_pr.call_count == 2

    def test_no_diff_completion_refuses_unchecked_acceptance_items(self, repo: Path):
        verified_head = _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip()
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--token123",
            worktree_path=str(repo),
            spec_path="specs/my-feature.md",
            verify_passed_once=True,
            verify_head_sha=verified_head,
        )

        result = orch._create_verified_no_diff_completion_commit(
            run,
            repo,
            worktree_path=repo,
            create_error="No commits between master and branch",
        )

        assert result is False
        assert "acceptance checklist is not fully checked" in run.last_error
        assert _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip() == verified_head

    def test_no_diff_completion_refuses_unverified_current_head(self, repo: Path):
        branch = "code/my-feature--token123"
        current_head = self._prepare_checked_no_diff_branch(repo, branch)
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch=branch,
            worktree_path=str(repo),
            spec_path="specs/my-feature.md",
            verify_passed_once=True,
            verify_head_sha="a" * 40,
        )

        result = orch._create_verified_no_diff_completion_commit(
            run,
            repo,
            worktree_path=repo,
            create_error="No commits between master and branch",
        )

        assert result is False
        assert "exact current head has not passed verify" in run.last_error
        assert _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip() == current_head

    def test_no_diff_completion_refuses_untracked_files(self, repo: Path):
        branch = "code/my-feature--token123"
        verified_head = self._prepare_checked_no_diff_branch(repo, branch)
        (repo / "untracked-runtime-input.txt").write_text("not part of verified commit\n")
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch=branch,
            worktree_path=str(repo),
            spec_path="specs/my-feature.md",
            verify_passed_once=True,
            verify_head_sha=verified_head,
        )

        result = orch._create_verified_no_diff_completion_commit(
            run,
            repo,
            worktree_path=repo,
            create_error="No commits between master and branch",
        )

        assert result is False
        assert "worktree is not clean" in run.last_error
        assert _run_git_stdout("rev-parse", "HEAD", cwd=repo).strip() == verified_head

    def test_fails_when_worktree_branch_mismatches_run(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        run.save(repo)

        worktree = repo / ".worktrees" / run.spec_id
        worktree.parent.mkdir(parents=True, exist_ok=True)
        worktree.mkdir()

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, "my-feature\n", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_head_sha", return_value="a" * 40),
            patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
            patch.object(
                orch,
                "_publish_local_review_pending_check_run",
                return_value="https://github.com/acme/repo/runs/123",
            ),
        ):
            result = orch.phase_publish(run, repo)

        assert result == "failed"
        assert "is on branch 'my-feature'" in run.last_error
        assert "expected 'spec/my-feature'" in run.last_error

    def test_reconcile_push_rejection_ignores_non_fast_forward_unrelated_errors(self, tmp_path: Path):
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        result = orch._reconcile_publish_push_rejection(
            run,
            forge=MagicMock(),
            branch="code/s--1",
            worktree_path=tmp_path,
            push_message="remote: permission denied",
        )
        assert result is None

    def _reconcile_subprocess(self, *, remote_head: str, fetch_rc: int = 0):
        calls: list[list[str]] = []

        def fake_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            del cwd, env, timeout
            calls.append(cmd)
            if cmd[:2] == ["git", "fetch"]:
                return subprocess.CompletedProcess(cmd, fetch_rc, "", "")
            if cmd == ["git", "rev-parse", "FETCH_HEAD"]:
                return subprocess.CompletedProcess(cmd, 0, remote_head + "\n", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        return calls, fake_run_subprocess

    def test_reconcile_push_rejection_lease_pushes_over_own_published_head(self, tmp_path: Path):
        run = orch.RunState(
            run_id="r", spec_id="s", branch="code/s--1", readiness_head_sha="b" * 40
        )
        forge = MagicMock()
        forge.push_branch.return_value = orch.PushResult(ok=True)
        calls, fake = self._reconcile_subprocess(remote_head="b" * 40)
        with (
            patch.object(orch, "run_subprocess", side_effect=fake),
            patch.object(orch, "_head_sha", return_value="a" * 40),
        ):
            result = orch._reconcile_publish_push_rejection(
                run,
                forge,
                branch="code/s--1",
                worktree_path=tmp_path,
                push_message="hint: tip of your current branch is behind",
            )
        assert result is not None and result.ok
        forge.push_branch.assert_called_once_with(
            "code/s--1", cwd=tmp_path, force=True, expect_sha="b" * 40
        )

    def test_reconcile_push_rejection_requires_recorded_readiness_head(self, tmp_path: Path):
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        forge = MagicMock()
        with patch.object(orch, "run_subprocess") as run_mock:
            result = orch._reconcile_publish_push_rejection(
                run,
                forge,
                branch="code/s--1",
                worktree_path=tmp_path,
                push_message="! [rejected] ... (fetch first)",
            )
        assert result is None
        run_mock.assert_not_called()
        forge.push_branch.assert_not_called()

    def test_reconcile_push_rejection_keeps_moved_remote_terminal(self, tmp_path: Path):
        """A remote at any head other than our own published one stays terminal —
        including one strictly ahead of local, which could be a third-party push."""
        run = orch.RunState(
            run_id="r", spec_id="s", branch="code/s--1", readiness_head_sha="c" * 40
        )
        forge = MagicMock()
        calls, fake = self._reconcile_subprocess(remote_head="b" * 40)
        with (
            patch.object(orch, "run_subprocess", side_effect=fake),
            patch.object(orch, "_head_sha", return_value="a" * 40),
        ):
            result = orch._reconcile_publish_push_rejection(
                run,
                forge,
                branch="code/s--1",
                worktree_path=tmp_path,
                push_message="! [rejected] ... non-fast-forward",
            )
        assert result is None
        forge.push_branch.assert_not_called()

    def test_reconcile_push_rejection_gives_up_when_fetch_fails(self, tmp_path: Path):
        run = orch.RunState(
            run_id="r", spec_id="s", branch="code/s--1", readiness_head_sha="b" * 40
        )
        forge = MagicMock()
        calls, fake = self._reconcile_subprocess(remote_head="b" * 40, fetch_rc=1)
        with patch.object(orch, "run_subprocess", side_effect=fake):
            result = orch._reconcile_publish_push_rejection(
                run,
                forge,
                branch="code/s--1",
                worktree_path=tmp_path,
                push_message="! [rejected] ... (fetch first)",
            )
        assert result is None
        forge.push_branch.assert_not_called()

    def test_publish_preserves_untracked_current_spec(self, repo: Path):
        """Untracked (gitignored) CURRENT_SPEC.md survives publish for retries."""
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
            agent="codex",
        )
        run.save(repo)

        worktree = repo / ".worktrees" / run.spec_id
        worktree.parent.mkdir(parents=True, exist_ok=True)
        worktree.mkdir()
        spec_path = worktree / "CURRENT_SPEC.md"
        spec_path.write_text("slug: my-feature\n## Spec\nDo stuff\n")
        # Also write the spec file for spec-mode
        (repo / "specs").mkdir(exist_ok=True)
        (repo / "specs" / "my-feature.md").write_text("slug: my-feature\n## Spec\nDo stuff\n")

        commands: list[list[str]] = []

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            commands.append(cmd)
            if cmd[:3] == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, f"{run.branch}\n", "")
            if cmd[:4] == ["git", "ls-files", "--error-unmatch", "CURRENT_SPEC.md"]:
                # File is untracked (gitignored)
                return subprocess.CompletedProcess(cmd, 1, "", "error: pathspec")
            if cmd[:4] == ["git", "status", "--porcelain", "--"]:
                assert cmd[4] == "specs/my-feature.md"
                return subprocess.CompletedProcess(cmd, 0, "?? specs/my-feature.md\n", "")
            if cmd[:3] == ["git", "add", "--"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "commit", "-m"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["git", "push", "-u"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "pr", "view"]:
                return subprocess.CompletedProcess(cmd, 1, "", "no PR found")
            if cmd[:3] == ["gh", "pr", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "pr", "create"]:
                return subprocess.CompletedProcess(cmd, 0, "https://github.com/o/r/pull/1\n", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_head_sha", return_value="a" * 40),
            patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
            patch.object(
                orch,
                "_publish_local_review_pending_check_run",
                return_value="https://github.com/acme/repo/runs/123",
            ),
        ):
            result = orch.phase_publish(run, repo)

        assert result == "passed"
        # CURRENT_SPEC.md must still exist for retry loops
        assert spec_path.exists()
        commit_index = next(idx for idx, cmd in enumerate(commands) if cmd[:3] == ["git", "commit", "-m"])
        push_index = next(idx for idx, cmd in enumerate(commands) if cmd[:3] == ["git", "push", "-u"])
        assert commit_index < push_index

