    def test_publish_marks_task_pr_for_local_review(self, repo: Path):
        run = orch.RunState(
            run_id="task-docs-20260101T000000",
            spec_id="task-docs",
            branch="task/task-docs--token123",
            worktree_path=str(repo / ".worktrees" / "task-task-docs--token123"),
            run_mode="task",
            spec_path="specs/tasks/task-docs.md",
            agent="codex",
        )
        run.save(repo)

        worktree = Path(run.worktree_path)
        worktree.mkdir(parents=True, exist_ok=True)
        task_specs = repo / "specs" / "tasks"
        task_specs.mkdir(parents=True, exist_ok=True)
        (task_specs / "task-docs.md").write_text("## Acceptance Criteria\n- [ ] Write docs\n")

        created_bodies: list[str] = []

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["git", "branch", "--show-current"]:
                return subprocess.CompletedProcess(cmd, 0, f"{run.branch}\n", "")
            if cmd[:4] == ["git", "status", "--porcelain", "--"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["git", "push", "-u"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "pr", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["gh", "pr", "create"]:
                created_bodies.append(cmd[cmd.index("--body") + 1])
                return subprocess.CompletedProcess(cmd, 0, "https://github.com/o/r/pull/2\n", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_head_sha", return_value="b" * 40),
            patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
            patch.object(
                orch,
                "_publish_local_review_pending_check_run",
                return_value="https://github.com/acme/repo/runs/456",
            ),
        ):
            result = orch.phase_publish(run, repo)

        assert result == "passed"
        assert "Review-Owner: local" in created_bodies[0]
        assert "## Summary\nTask: task-docs\n\n" in created_bodies[0]

