class TestRunSubprocess:
    def test_uses_devnull_stdin_when_no_input_text(self, repo: Path):
        captured: dict[str, object] = {}
        expected = subprocess.CompletedProcess(args=["echo", "ok"], returncode=0)

        def fake_run(cmd, **kwargs):  # noqa: ANN001
            captured["cmd"] = cmd
            captured.update(kwargs)
            return expected

        with patch.object(orch.subprocess, "run", side_effect=fake_run):
            result = orch.run_subprocess(["echo", "ok"], cwd=repo, env={"A": "1"}, inherit_env=False)

        assert result is expected
        assert captured["cmd"] == ["echo", "ok"]
        assert captured["cwd"] == repo
        assert captured["env"] == {"A": "1"}
        assert captured["stdin"] == orch.subprocess.DEVNULL
        assert "input" not in captured

    def test_omits_explicit_stdin_when_input_text_is_provided(self, repo: Path):
        captured: dict[str, object] = {}
        expected = subprocess.CompletedProcess(args=["cat"], returncode=0)

        def fake_run(cmd, **kwargs):  # noqa: ANN001
            captured["cmd"] = cmd
            captured.update(kwargs)
            return expected

        with patch.object(orch.subprocess, "run", side_effect=fake_run):
            result = orch.run_subprocess(["cat"], cwd=repo, input_text="hello")

        assert result is expected
        assert captured["cmd"] == ["cat"]
        assert captured["cwd"] == repo
        assert captured["input"] == "hello"
        assert "stdin" not in captured


class TestImplementSetupTeardownHelpers:
    def _run(self) -> orch.RunState:
        return orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_parse_setup_manifest_ignores_prefixed_logs(self):
        manifest = orch._parse_implement_setup_manifest(
            "starting services\n"
            '{"env":{"DATABASE_URL":"postgres://db"},"prompt":"Ready","mcp_prompt":"Use MCP",'
            '"mcp_servers":{"playwright":{"command":"node","args":["cli.js"]}},'
            '"managed_processes":[{"name":"dev-server","kind":"plugin-helper","pid":123,'
            '"started_at":"Wed Mar 25 10:00:00 2026","termination_scope":"pgid","pgid":123}]}\n'
        )

        assert manifest.env == {"DATABASE_URL": "postgres://db"}
        assert manifest.prompt == "Ready"
        assert manifest.mcp_prompt == "Use MCP"
        assert manifest.mcp_servers["playwright"]["command"] == "node"
        assert manifest.managed_processes == (
            orch.ImplementManagedProcess(
                name="dev-server",
                kind="plugin-helper",
                pid=123,
                started_at="Wed Mar 25 10:00:00 2026",
                termination_scope="pgid",
                pgid=123,
            ),
        )

    def test_run_setup_command_passes_required_args_and_parses_manifest(
        self,
        repo: Path,
    ):
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command="scripts/implement-setup.sh --flag",
            ),
        )
        seen: dict[str, object] = {}

        def fake_run_subprocess(cmd, cwd=None, env=None, timeout=None, *, inherit_env=True, input_text=None):
            del timeout, inherit_env, input_text
            seen["cmd"] = cmd
            seen["cwd"] = cwd
            seen["env"] = env
            return subprocess.CompletedProcess(
                args=cmd,
                returncode=0,
                stdout=(
                    "booting\n"
                    '{"env":{"DATABASE_URL":"postgres://db"},"prompt":"App ready","mcp_prompt":"Inspect UI",'
                    '"mcp_servers":{"playwright":{"command":"node","args":["cli.js"]}},'
                    '"managed_processes":[{"name":"dev-server","kind":"plugin-helper","pid":321,'
                    '"started_at":"Wed Mar 25 10:00:00 2026","termination_scope":"pgid","pgid":321}]}'
                ),
                stderr="",
            )

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(orch, "run_subprocess", side_effect=fake_run_subprocess),
        ):
            manifest = orch._run_implement_setup_command(run, repo)

        assert manifest.env == {"DATABASE_URL": "postgres://db"}
        assert manifest.prompt == "App ready"
        assert manifest.mcp_prompt == "Inspect UI"
        assert manifest.managed_processes == (
            orch.ImplementManagedProcess(
                name="dev-server",
                kind="plugin-helper",
                pid=321,
                started_at="Wed Mar 25 10:00:00 2026",
                termination_scope="pgid",
                pgid=321,
            ),
        )
        assert seen["cwd"] == repo
        assert seen["cmd"] == [
            "scripts/implement-setup.sh",
            "--flag",
            "--worktree",
            str(repo),
            "--spec-id",
            "my-feature",
            "--run-id",
            run.run_id,
            "--attempt",
            "1",
        ]
        assert seen["env"]["SPEC_ID"] == "my-feature"
        assert seen["env"]["SPEC_RUN_ID"] == run.run_id
        assert seen["env"]["SPEC_PATH"] == "specs/my-feature.md"
        assert seen["env"]["SPEC_WORKTREE"] == str(repo)
        assert seen["env"]["SPEC_ATTEMPT"] == "1"

