    def test_run_setup_command_scrubs_structured_env_from_stderr(self, repo: Path):
        """Regression (PR163-F1, attempt 19): structured stderr records
        carrying an ``env`` mapping must be scrubbed before ``stderr_tail``
        and ``message`` are rendered. ``redact_sensitive`` does not walk
        JSON, so without this sanitization a setup failure becomes a
        secret-exposure path into the agent prompt and warning log."""
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command="scripts/implement-setup.sh",
            ),
        )

        leaky_stderr = (
            '{"level":"error","env":{"SECRET_TOKEN":"abc123"},'
            '"msg":"boom migration failed"}\n'
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=["scripts/implement-setup.sh"],
                    returncode=3,
                    stdout="",
                    stderr=leaky_stderr,
                ),
            ),
        ):
            manifest = orch._run_implement_setup_command(run, repo)

        assert manifest.failure is not None
        assert "abc123" not in manifest.failure.stderr_tail
        assert "SECRET_TOKEN" not in manifest.failure.stderr_tail
        assert "abc123" not in manifest.failure.message
        assert "SECRET_TOKEN" not in manifest.failure.message
        # Diagnostic text (level/msg) must survive so the agent still sees
        # the actionable failure context.
        assert "boom migration failed" in manifest.failure.stderr_tail

