    def test_redact_argv_scrubs_split_form_compound_sensitive_flags(self, repo: Path):
        """Regression (PR163-F1, attempt-26): ``--access-token tok``,
        ``--refresh_token tok``, ``--client-secret shhh`` and other compound
        credential flag names must be redacted in the split (space-separated)
        form, not just ``--flag=value``. The value is the element that
        follows the bare flag, so the redactor has to recognise the flag
        name itself and scrub the next element.
        """
        cases = [
            (
                ["cmd", "--access-token", "tok123SECRET"],
                ["cmd", "--access-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--access_token", "tok456SECRET"],
                ["cmd", "--access_token", "<REDACTED>"],
            ),
            (
                ["cmd", "--refresh-token", "REFRESHSECRETVAL"],
                ["cmd", "--refresh-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--client-secret", "CLIENTSHHHVAL"],
                ["cmd", "--client-secret", "<REDACTED>"],
            ),
            (
                ["cmd", "--session-token", "SESSIONSECRETVAL"],
                ["cmd", "--session-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--private-key", "PRIVKEYVAL"],
                ["cmd", "--private-key", "<REDACTED>"],
            ),
            (
                ["cmd", "--access-token=tok789SECRET"],
                ["cmd", "--access-token=<REDACTED>"],
            ),
            (
                ["cmd", "--client_secret=CLIENTSHHHEQ"],
                ["cmd", "--client_secret=<REDACTED>"],
            ),
        ]
        for argv, expected in cases:
            assert orch._redact_argv(argv) == expected, argv

    def test_redact_argv_scrubs_short_option_and_env_assignment_forms(
        self, repo: Path
    ):
        """Regression (PR163-F2 attempt-30): ``failure.command`` is echoed
        into the setup-failure prompt and warning logs, so ``_redact_argv``
        must also cover short-option (``cmd -p hunter2``, ``-phunter2``,
        ``-p=hunter2``) and env-assignment (``PGPASSWORD=secret psql``,
        ``DATABASE_PASSWORD=xxx``, ``GITHUB_TOKEN=ghp_…``) forms. These
        were previously passed through verbatim and leaked secrets into the
        agent prompt.
        """
        cases = [
            # Short-option bare form
            (
                ["cmd", "-p", "hunter2"],
                ["cmd", "-p", "<REDACTED>"],
            ),
            # Short-option attached form
            (
                ["cmd", "-phunter2"],
                ["cmd", "-p<REDACTED>"],
            ),
            # Short-option with = separator
            (
                ["cmd", "-p=hunter2"],
                ["cmd", "-p=<REDACTED>"],
            ),
            # Env-assignment prefix (``PGPASSWORD=secret psql``)
            (
                ["PGPASSWORD=secret", "psql"],
                ["PGPASSWORD=<REDACTED>", "psql"],
            ),
            (
                ["DATABASE_PASSWORD=shhhhh", "run.sh"],
                ["DATABASE_PASSWORD=<REDACTED>", "run.sh"],
            ),
            (
                ["GITHUB_TOKEN=ghp_XYZ", "deploy.sh"],
                ["GITHUB_TOKEN=<REDACTED>", "deploy.sh"],
            ),
            (
                ["STRIPE_API_KEY=sk_live_xxx", "setup.sh"],
                ["STRIPE_API_KEY=<REDACTED>", "setup.sh"],
            ),
            # Non-sensitive env assignments must pass through.
            (
                ["PATH=/usr/bin", "run.sh"],
                ["PATH=/usr/bin", "run.sh"],
            ),
        ]
        for argv, expected in cases:
            assert orch._redact_argv(argv) == expected, argv

