    def test_redact_argv_scrubs_split_form_github_and_api_token_flags(
        self, repo: Path
    ):
        """Regression (PR163-F1 attempt-33): ``--github-token``,
        ``--api-token``, ``--auth-token`` and similar suffix-composed long
        options previously matched only through the strict exact-name
        classifier. Because ``githubtoken`` / ``apitoken`` / ``authtoken``
        are not exact names, the split (space-separated) form leaked
        credentials into ``failure.command`` and the setup-failure prompt.
        The long-option path must now use the same suffix-aware matcher as
        structured JSON log fields.
        """
        cases = [
            (
                ["cmd", "--github-token", "ghp_GITHUBSECRETVALUE"],
                ["cmd", "--github-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--api-token", "APITOKENSECRETVAL"],
                ["cmd", "--api-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--auth-token", "AUTHTOKENSECRETVAL"],
                ["cmd", "--auth-token", "<REDACTED>"],
            ),
            (
                ["cmd", "--github_token", "ghp_UNDERSCOREDSECRET"],
                ["cmd", "--github_token", "<REDACTED>"],
            ),
            (
                ["cmd", "--github-token=ghp_EQUALSSECRET"],
                ["cmd", "--github-token=<REDACTED>"],
            ),
            (
                ["cmd", "--api-token=APITOKENEQUALSSECRET"],
                ["cmd", "--api-token=<REDACTED>"],
            ),
            # ``--author-name`` must NOT be redacted: the suffix matcher
            # requires an ``auth`` word-boundary, so ``author-name`` does
            # not qualify.
            (
                ["cmd", "--author-name", "Alice"],
                ["cmd", "--author-name", "Alice"],
            ),
        ]
        for argv, expected in cases:
            assert orch._redact_argv(argv) == expected, argv

    def test_redact_argv_scrubs_separatorless_token_flags(self, repo: Path):
        """Regression (PR163-F2 attempt-37): separator-less long options
        whose name ends in ``token`` (``--authtoken``, ``--apitoken``,
        ``--githubtoken``) previously survived the bare-flag redaction
        path because the short-token suffix matcher required a non-letter
        boundary between ``auth``/``token`` and adjacent letters. The
        matcher must now also recognize the anchored ``*token``/``*auth``
        suffix so these flags are redacted alongside their hyphenated
        variants.
        """
        cases = [
            (
                ["cmd", "--authtoken", "AUTHTOKVAL"],
                ["cmd", "--authtoken", "<REDACTED>"],
            ),
            (
                ["cmd", "--apitoken", "APITOKVAL"],
                ["cmd", "--apitoken", "<REDACTED>"],
            ),
            (
                ["cmd", "--githubtoken", "GITHUBTOKVAL"],
                ["cmd", "--githubtoken", "<REDACTED>"],
            ),
            (
                ["cmd", "--authtoken=AUTHTOKEQVAL"],
                ["cmd", "--authtoken=<REDACTED>"],
            ),
            (
                ["cmd", "--apitoken=APITOKEQVAL"],
                ["cmd", "--apitoken=<REDACTED>"],
            ),
            # ``--tokenize`` must NOT be redacted: the ``token`` is a
            # prefix, not a suffix, so it's not a credential name.
            (
                ["cmd", "--tokenize", "input.txt"],
                ["cmd", "--tokenize", "input.txt"],
            ),
            # ``--author`` must NOT be redacted either — ``auth`` is a
            # prefix within ``author``, not the trailing suffix.
            (
                ["cmd", "--author", "Alice"],
                ["cmd", "--author", "Alice"],
            ),
        ]
        for argv, expected in cases:
            assert orch._redact_argv(argv) == expected, argv

    def test_redact_argv_scrubs_userinfo_auth_flags(self, repo: Path):
        """Regression (PR163-F1 attempt-38): ``curl -u alice:secret`` /
        ``--user alice:secret`` / ``--login-path=prod`` carry a userinfo
        pair that conventionally embeds a password. ``_is_sensitive_log_field``
        does not flag ``user``/``login``/``netrc`` as credentials (to avoid
        over-redacting structured log fields), so ``_redact_argv`` has to
        recognize these argv-specific auth flags itself. Otherwise a
        non-zero setup exit leaks ``alice:secret`` into ``failure.command``
        and the setup-failure prompt.
        """
        cases = [
            # ``curl -u alice:secret …`` (short, split form)
            (
                ["curl", "-u", "alice:supersecret", "https://example.com"],
                ["curl", "-u", "<REDACTED>", "https://example.com"],
            ),
            # Attached short form ``-ualice:supersecret``
            (
                ["curl", "-ualice:supersecret"],
                ["curl", "-u<REDACTED>"],
            ),
            # ``--user alice:secret`` split
            (
                ["curl", "--user", "alice:supersecret"],
                ["curl", "--user", "<REDACTED>"],
            ),
            # ``--user=alice:secret`` equal form
            (
                ["curl", "--user=alice:supersecret"],
                ["curl", "--user=<REDACTED>"],
            ),
            # ``--username prod`` for various DB CLIs
            (
                ["mysql", "--username", "rootpass"],
                ["mysql", "--username", "<REDACTED>"],
            ),
            # ``--login-path=prod`` (mysql_config_editor style)
            (
                ["mysql", "--login-path=prod"],
                ["mysql", "--login-path=<REDACTED>"],
            ),
            # ``--netrc-file`` path often carries credentials indirectly.
            (
                ["curl", "--netrc-file", "/etc/secret.netrc"],
                ["curl", "--netrc-file", "<REDACTED>"],
            ),
            # Uppercase ``-U`` (psql) also carries userinfo conventionally.
            (
                ["psql", "-U", "alice:supersecret"],
                ["psql", "-U", "<REDACTED>"],
            ),
            # ``--author`` is not a credential flag (substring of ``auth``
            # but not ``user``/``login``/``netrc``) — must pass through.
            (
                ["git", "--author", "Alice"],
                ["git", "--author", "Alice"],
            ),
        ]
        for argv, expected in cases:
            assert orch._redact_argv(argv) == expected, argv

