    def test_run_setup_command_redacts_split_form_github_token(self, repo: Path):
        """Regression (PR163-F1 attempt-33): end-to-end check that a
        ``--github-token`` in split form does not leak into
        ``failure.command`` or the setup-failure prompt when the setup
        command exits non-zero.
        """
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command=(
                    "scripts/implement-setup.sh "
                    "--github-token ghp_GITHUBSECRETVALUE123 "
                    "--api-token APITOKENSPLITSECRET456"
                ),
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=["scripts/implement-setup.sh"],
                    returncode=1,
                    stdout="",
                    stderr="boom",
                ),
            ),
        ):
            manifest = orch._run_implement_setup_command(run, repo)

        assert manifest.failure is not None
        prompt = orch._build_setup_failure_prompt(manifest)
        for secret in (
            "ghp_GITHUBSECRETVALUE123",
            "APITOKENSPLITSECRET456",
        ):
            assert secret not in manifest.failure.command
            assert secret not in prompt

    def test_run_setup_command_malformed_quoting_returns_failure(self, repo: Path):
        """Regression (PR163-F2 attempt-33): a setup_command with invalid
        shell quoting (e.g. an unclosed quote) makes ``shlex.split`` raise
        ``ValueError``. The orchestrator must degrade to a best-effort
        ``ImplementSetupFailure`` so ``phase_implement`` still launches the
        agent with diagnostics instead of aborting the whole phase.
        """
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command="scripts/implement-setup.sh '",
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(orch, "run_subprocess") as run_mock,
        ):
            manifest = orch._run_implement_setup_command(run, repo)

        # Parsing failed before subprocess launch, so run_subprocess must
        # not have been called.
        run_mock.assert_not_called()
        assert manifest.failure is not None
        assert manifest.failure.launch_error is True
        assert manifest.failure.exit_code is None
        # The failure message describes the parse failure and is safe to
        # embed in the agent prompt.
        prompt = orch._build_setup_failure_prompt(manifest)
        assert "scripts/implement-setup.sh" in prompt
        assert manifest.failure.message

    def test_run_setup_command_malformed_quoting_redacts_argv_secrets(
        self, repo: Path
    ):
        """Regression (PR163-F1 attempt-34): when the setup_command has
        malformed quoting so ``shlex.split`` raises, the fallback path
        must still scrub argv-shaped secrets (env assignment,
        ``--access-token``, ``-p``) from ``failure.command`` and the
        failure prompt. ``redact_sensitive`` alone only matches string
        patterns and misses these argv forms.
        """
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command=(
                    "PGPASSWORD=pgpwMALFORMEDSECRET "
                    "GITHUB_TOKEN=ghtokMALFORMEDSECRET "
                    "scripts/implement-setup.sh "
                    "--access-token tokMALFORMEDSECRET "
                    "-p shortMALFORMEDSECRET '"
                ),
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(orch, "run_subprocess") as run_mock,
        ):
            manifest = orch._run_implement_setup_command(run, repo)
        run_mock.assert_not_called()
        assert manifest.failure is not None
        assert manifest.failure.launch_error is True
        prompt = orch._build_setup_failure_prompt(manifest)
        for secret in (
            "pgpwMALFORMEDSECRET",
            "ghtokMALFORMEDSECRET",
            "tokMALFORMEDSECRET",
            "shortMALFORMEDSECRET",
        ):
            assert secret not in manifest.failure.command
            assert secret not in manifest.failure.message
            assert secret not in prompt

    def test_run_setup_command_malformed_quoting_redacts_runon_secret_tail(
        self, repo: Path
    ):
        """Regression (PR163-F1 attempt-34): with an unclosed quote
        immediately after ``--access-token``, whitespace-splitting would
        break the secret across multiple tokens. The fallback redactor
        must blank every non-flag token after a sensitive bare flag, so
        no tail of the value leaks into the failure prompt.
        """
        run = self._run()
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command=(
                    'scripts/implement-setup.sh --access-token "TOKHEAD TOKTAIL'
                ),
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(orch, "run_subprocess") as run_mock,
        ):
            manifest = orch._run_implement_setup_command(run, repo)
        run_mock.assert_not_called()
        assert manifest.failure is not None
        prompt = orch._build_setup_failure_prompt(manifest)
        for secret in ("TOKHEAD", "TOKTAIL"):
            assert secret not in manifest.failure.command
            assert secret not in manifest.failure.message
            assert secret not in prompt

    def test_run_setup_command_malformed_quoting_redacts_attached_flag_secret_tail(
        self, repo: Path
    ):
        """Regression (PR163-F1 attempt-41): with an unclosed quote in the
        *attached* form of a sensitive flag (``--password="TOPSECRET TAIL``
        or ``-p"TOPSECRET TAIL``), whitespace-splitting breaks the value
        across tokens. The fallback redactor must detect the unterminated
        quote on the flag token and keep redacting spillover tokens until
        the next flag, so neither the head nor the tail of the secret
        leaks into ``failure.command`` or the setup-failure prompt."""
        run = self._run()
        config_long = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command=(
                    'scripts/implement-setup.sh '
                    '--password="TOPSECRETHEAD TOPSECRETTAIL'
                ),
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config_long),
            patch.object(orch, "run_subprocess") as run_mock,
        ):
            manifest_long = orch._run_implement_setup_command(run, repo)
        run_mock.assert_not_called()
        assert manifest_long.failure is not None
        prompt_long = orch._build_setup_failure_prompt(manifest_long)
        for secret in ("TOPSECRETHEAD", "TOPSECRETTAIL"):
            assert secret not in manifest_long.failure.command
            assert secret not in manifest_long.failure.message
            assert secret not in prompt_long

        config_short = replace(
            orch.SPEC_RUNTIME_CONFIG,
            implement=replace(
                orch.SPEC_RUNTIME_CONFIG.implement,
                setup_command=(
                    'scripts/implement-setup.sh '
                    '-p"SHORTSECRETHEAD SHORTSECRETTAIL'
                ),
            ),
        )
        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config_short),
            patch.object(orch, "run_subprocess") as run_mock,
        ):
            manifest_short = orch._run_implement_setup_command(run, repo)
        run_mock.assert_not_called()
        assert manifest_short.failure is not None
        prompt_short = orch._build_setup_failure_prompt(manifest_short)
        for secret in ("SHORTSECRETHEAD", "SHORTSECRETTAIL"):
            assert secret not in manifest_short.failure.command
            assert secret not in manifest_short.failure.message
            assert secret not in prompt_short

    def test_parse_setup_manifest_error_level_log_with_strong_key_is_fallback(
        self, repo: Path
    ):
        """Regression (PR163-F1 attempt-37): an error-level log record
        that carries a strong manifest key (``managed_processes``,
        ``mcp_servers``, ``prompt``, ``mcp_prompt``) is late partial
        handoff from a setup helper that emitted its final state through
        a warning/error logger before crashing. It must NOT override an
        earlier primary's value for any field the primary already
        populated (an earlier plain ``env`` snapshot wins over a trailing
        error log's own ``env`` context), but fields only the error-level
        record supplies must be merged in — otherwise teardown cannot
        reach children the script already forked, and MCP/prompt state
        emitted alongside the crash is silently dropped.
        """
        stdout = (
            '{"env":{"A":"1"}}\n'
            '{"level":"error","msg":"boom","managed_processes":['
            '{"name":"ghost","kind":"postgres","pid":999,'
            '"started_at":"2026-04-22T00:00:00Z","command":"postgres"}]}\n'
        )
        manifest = orch._parse_implement_setup_manifest(stdout, allow_trailing=True)
        # Primary env wins.
        assert manifest.env == {"A": "1"}
        # managed_processes only appears on the fallback — merge it in.
        assert manifest.managed_processes and (
            manifest.managed_processes[0].name == "ghost"
        )

        stdout_mcp = (
            '{"env":{"A":"1"}}\n'
            '{"level":"error","msg":"boom","mcp_servers":{"ghost":{"command":"x"}}}\n'
        )
        manifest_mcp = orch._parse_implement_setup_manifest(
            stdout_mcp, allow_trailing=True
        )
        assert manifest_mcp.mcp_servers == {"ghost": {"command": "x"}}
        assert manifest_mcp.env == {"A": "1"}

        stdout_prompt = (
            '{"env":{"A":"1"}}\n'
            '{"level":"error","msg":"boom","prompt":"partial prompt"}\n'
        )
        manifest_prompt = orch._parse_implement_setup_manifest(
            stdout_prompt, allow_trailing=True
        )
        assert manifest_prompt.prompt == "partial prompt"
        assert manifest_prompt.env == {"A": "1"}

        # But an error-level record's ``env`` must NOT override an
        # earlier primary's ``env`` (ambiguous with status-log context).
        stdout_env_only = (
            '{"env":{"A":"1"}}\n'
            '{"level":"error","msg":"boom","env":{"A":"99","B":"2"}}\n'
        )
        manifest_env_only = orch._parse_implement_setup_manifest(
            stdout_env_only, allow_trailing=True
        )
        assert manifest_env_only.env == {"A": "1"}
        assert "B" not in manifest_env_only.env

    def test_parse_setup_manifest_strong_fallback_env_cannot_clobber_primary(
        self, repo: Path
    ):
        """Regression (PR163-F2 attempt-41): an error-level fallback that
        carries ``managed_processes`` alongside an ``env`` key whose names
        overlap with a later plain primary's ``env`` must NOT override the
        primary on that overlapping key. Earlier stdout order of the
        fallback is not permission to replace a subsequent real primary
        handoff — the fallback's env is still diagnostic context, only
        consulted as fill for keys the primary never declared."""
        stdout = (
            '{"level":"error","msg":"boom","managed_processes":['
            '{"name":"ghost","kind":"postgres","pid":999,'
            '"started_at":"2026-04-22T00:00:00Z","command":"postgres"}],'
            '"env":{"A":"fallback","ONLY_IN_FALLBACK":"keep"}}\n'
            '{"env":{"A":"primary"}}\n'
        )
        manifest = orch._parse_implement_setup_manifest(
            stdout, allow_trailing=True
        )
        # Primary wins on the overlapping key, regardless of stdout order.
        assert manifest.env["A"] == "primary"
        # Non-overlapping keys from the strong fallback still fill in.
        assert manifest.env.get("ONLY_IN_FALLBACK") == "keep"
        # Strong-only field from the fallback is still merged in.
        assert manifest.managed_processes and (
            manifest.managed_processes[0].name == "ghost"
        )

    def test_parse_setup_manifest_env_only_info_log_does_not_overwrite_plain(
        self, repo: Path
    ):
        """Regression (PR163-F1, attempt-35): a later benign-level log
        record that happens to carry ``env`` as context (``{"level":"info",
        "msg":"starting","env":{"NODE_ENV":"dev"}}``) must not overwrite a
        real plain partial manifest. The logger-wrapped record has no
        strong manifest key to distinguish it from an ordinary status log,
        so it is only consulted as a fallback when no primary exists.
        """
        stdout = (
            '{"env":{"DATABASE_URL":"db"}}\n'
            '{"level":"info","msg":"starting","env":{"NODE_ENV":"dev"}}\n'
        )
        manifest = orch._parse_implement_setup_manifest(
            stdout, allow_trailing=True
        )
        assert manifest.env == {"DATABASE_URL": "db"}
        assert "NODE_ENV" not in manifest.env

        # ``debug``-level status logs are just as ambiguous.
        stdout_debug = (
            '{"env":{"DATABASE_URL":"db"}}\n'
            '{"level":"debug","msg":"starting","env":{"NODE_ENV":"dev"}}\n'
        )
        manifest_debug = orch._parse_implement_setup_manifest(
            stdout_debug, allow_trailing=True
        )
        assert manifest_debug.env == {"DATABASE_URL": "db"}

        # Numeric benign level (Bunyan/Pino style) on the trailing log line
        # must also not override a real plain partial.
        stdout_num = (
            '{"env":{"DATABASE_URL":"db"}}\n'
            '{"level":30,"msg":"starting","env":{"NODE_ENV":"dev"}}\n'
        )
        manifest_num = orch._parse_implement_setup_manifest(
            stdout_num, allow_trailing=True
        )
        assert manifest_num.env == {"DATABASE_URL": "db"}

    def test_parse_setup_manifest_msg_only_with_strong_key_still_primary(
        self, repo: Path
    ):
        """Regression (PR163-F2, attempt-35): a manifest that also carries
        a top-level ``msg``/``message`` string but no ``level`` / ``event`` /
        ``error`` markers must still parse. ``{"env":{"DATABASE_URL":"db"},
        "msg":"ready"}`` is a valid env-only manifest annotated with a
        status message; ``{"prompt":"Ready","message":"bootstrapped"}``
        likewise. Dropping these silently strips real fields.
        """
        stdout = '{"env":{"DATABASE_URL":"db"},"msg":"ready"}\n'
        manifest = orch._parse_implement_setup_manifest(
            stdout, allow_trailing=True
        )
        assert manifest.env == {"DATABASE_URL": "db"}

        stdout_prompt = '{"prompt":"Ready","message":"bootstrapped"}\n'
        manifest_prompt = orch._parse_implement_setup_manifest(
            stdout_prompt, allow_trailing=True
        )
        assert manifest_prompt.prompt == "Ready"

        # A later msg-annotated strong partial must also update the earlier
        # one field-by-field, just like any other strong primary.
        stdout_seq = (
            '{"env":{"A":"1"}}\n'
            '{"env":{"A":"2"},"managed_processes":[{"name":"pg",'
            '"kind":"postgres","pid":7,"started_at":"2026-04-22T00:00:00Z",'
            '"command":"postgres"}],"msg":"ready"}\n'
        )
        manifest_seq = orch._parse_implement_setup_manifest(
            stdout_seq, allow_trailing=True
        )
        assert manifest_seq.env == {"A": "2"}
        assert (
            manifest_seq.managed_processes
            and manifest_seq.managed_processes[0].name == "pg"
        )

