class TestResumeSandboxConfigRewrite:
    """Verify _write_sandbox_config runs when resuming past bootstrap."""

    def _make_run(self, repo: Path, phase: str = "implement") -> orch.RunState:
        run = orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
            agent="claude",
        )
        run.phase = phase
        run.save(repo)
        return run

    def test_resume_rewrites_sandbox_config(self, repo: Path):
        run = self._make_run(repo, phase="implement")

        worktree_path = orch.resolve_worktree_path(run, repo)
        worktree_path.mkdir(parents=True, exist_ok=True)

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_write_sandbox_config") as mock_config,
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "passed"
        mock_config.assert_called_once_with("claude", worktree_path)

    def test_resume_at_bootstrap_skips_rewrite(self, repo: Path):
        run = self._make_run(repo, phase="bootstrap")

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_write_sandbox_config") as mock_config,
        ):
            orch.run_full_workflow(run, repo)

        mock_config.assert_not_called()

    def test_resume_config_write_failure_returns_failed(self, repo: Path):
        run = self._make_run(repo, phase="implement")

        worktree_path = orch.resolve_worktree_path(run, repo)
        worktree_path.mkdir(parents=True, exist_ok=True)

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_write_sandbox_config",
                side_effect=OSError("permission denied"),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "failed"
        assert "permission denied" in run.last_error


# ---------------------------------------------------------------------------
# Shared memory preflight
# ---------------------------------------------------------------------------


class TestSharedMemoryPreflight:
    @staticmethod
    def _ipcs_output(segment_count: int) -> str:
        rows = [f"m {1000 + idx} 0x00000000 --rw------- test staff" for idx in range(segment_count)]
        return "\n".join(
            [
                "IPC status from <running system>",
                "T     ID     KEY        MODE       OWNER    GROUP",
                "Shared Memory:",
                *rows,
            ]
        )

    @staticmethod
    def _ipcs_output_linux(segment_count: int) -> str:
        rows = [f"0x00000000 {1000 + idx} test 600 56 0" for idx in range(segment_count)]
        return "\n".join(
            [
                "------ Shared Memory Segments --------",
                "key        shmid      owner      perms      bytes      nattch     status",
                *rows,
            ]
        )

    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_count_sysv_shm_segments_parses_macos_and_linux_formats(self):
        mac_result = subprocess.CompletedProcess(
            args=["ipcs", "-m"],
            returncode=0,
            stdout=self._ipcs_output(3),
            stderr="",
        )
        linux_result = subprocess.CompletedProcess(
            args=["ipcs", "-m"],
            returncode=0,
            stdout=self._ipcs_output_linux(4),
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=mac_result):
            assert orch._count_sysv_shm_segments() == 3
        with patch.object(orch, "run_subprocess", return_value=linux_result):
            assert orch._count_sysv_shm_segments() == 4

    def test_verify_preflight_skips_when_usage_is_low(self, repo: Path):
        run = self._make_run()
        low_count = max(0, orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD - 1)
        ipcs_result = subprocess.CompletedProcess(
            args=["ipcs", "-m"],
            returncode=0,
            stdout=self._ipcs_output(low_count),
            stderr="",
        )

        with patch.object(orch, "run_subprocess", return_value=ipcs_result) as mock_run:
            assert orch._verify_preflight_shared_memory(run, repo) is True

        assert run.last_error == ""
        assert mock_run.call_count == 1

    def test_verify_preflight_runs_cleanup_when_usage_is_high(self, repo: Path):
        run = self._make_run()
        cleanup_script = repo / "scripts" / "cleanup_local_postgres.sh"
        cleanup_script.parent.mkdir(parents=True, exist_ok=True)
        cleanup_script.write_text("#!/usr/bin/env bash\n")

        before_count = orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD + 2
        after_count = max(0, orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD - 2)
        run_results = [
            subprocess.CompletedProcess(
                args=["ipcs", "-m"],
                returncode=0,
                stdout=self._ipcs_output(before_count),
                stderr="",
            ),
            subprocess.CompletedProcess(
                args=[str(cleanup_script), "--orphans-only"],
                returncode=0,
                stdout="removed_orphan_segments=3",
                stderr="",
            ),
            subprocess.CompletedProcess(
                args=["ipcs", "-m"],
                returncode=0,
                stdout=self._ipcs_output(after_count),
                stderr="",
            ),
        ]

        with patch.object(orch, "run_subprocess", side_effect=run_results) as mock_run:
            assert orch._verify_preflight_shared_memory(run, repo) is True

        cleanup_call = mock_run.call_args_list[1]
        assert cleanup_call.args[0] == [str(cleanup_script), "--orphans-only"]
        assert cleanup_call.kwargs["cwd"] == repo
        assert run.last_error == ""

    def test_verify_preflight_continues_when_cleanup_fails(self, repo: Path):
        run = self._make_run()
        cleanup_script = repo / "scripts" / "cleanup_local_postgres.sh"
        cleanup_script.parent.mkdir(parents=True, exist_ok=True)
        cleanup_script.write_text("#!/usr/bin/env bash\n")

        run_results = [
            subprocess.CompletedProcess(
                args=["ipcs", "-m"],
                returncode=0,
                stdout=self._ipcs_output(orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD + 1),
                stderr="",
            ),
            subprocess.CompletedProcess(
                args=[str(cleanup_script), "--orphans-only"],
                returncode=1,
                stdout="",
                stderr="permission denied",
            ),
        ]

        with patch.object(orch, "run_subprocess", side_effect=run_results):
            assert orch._verify_preflight_shared_memory(run, repo) is True

        assert run.last_error == ""

    def test_verify_preflight_continues_when_usage_stays_high(self, repo: Path):
        run = self._make_run()
        cleanup_script = repo / "scripts" / "cleanup_local_postgres.sh"
        cleanup_script.parent.mkdir(parents=True, exist_ok=True)
        cleanup_script.write_text("#!/usr/bin/env bash\n")

        run_results = [
            subprocess.CompletedProcess(
                args=["ipcs", "-m"],
                returncode=0,
                stdout=self._ipcs_output(orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD + 3),
                stderr="",
            ),
            subprocess.CompletedProcess(
                args=[str(cleanup_script), "--orphans-only"],
                returncode=0,
                stdout="removed_orphan_segments=0",
                stderr="",
            ),
            subprocess.CompletedProcess(
                args=["ipcs", "-m"],
                returncode=0,
                stdout=self._ipcs_output(orch.SHM_PREFLIGHT_CLEANUP_THRESHOLD + 1),
                stderr="",
            ),
        ]

        with patch.object(orch, "run_subprocess", side_effect=run_results):
            assert orch._verify_preflight_shared_memory(run, repo) is True

        assert run.last_error == ""


class TestMergeOriginMaster:
    def test_noop_when_already_up_to_date(self, repo: Path):
        worktree = repo / ".worktrees" / "my-feature"
        worktree.mkdir(parents=True, exist_ok=True)
        calls: list[list[str]] = []

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            calls.append(cmd)
            if cmd == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "merge-base", "--is-ancestor", "origin/master", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            result = orch._merge_origin_master(worktree)

        assert result.status == "noop"
        assert result.stderr == ""
        assert calls == [
            ["git", "fetch", "origin", "master"],
            ["git", "merge-base", "--is-ancestor", "origin/master", "HEAD"],
        ]

    def test_merges_when_branch_is_behind_origin_master(self, repo: Path):
        worktree = repo / ".worktrees" / "my-feature"
        worktree.mkdir(parents=True, exist_ok=True)

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "merge-base", "--is-ancestor", "origin/master", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 1, "", "")
            if cmd == ["git", "merge", "origin/master", "--no-edit"]:
                return subprocess.CompletedProcess(cmd, 0, "merge commit", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            result = orch._merge_origin_master(worktree)

        assert result.status == "success"
        assert result.stderr == ""

    def test_aborts_and_returns_conflict_on_merge_conflict(self, repo: Path):
        worktree = repo / ".worktrees" / "my-feature"
        worktree.mkdir(parents=True, exist_ok=True)
        calls: list[list[str]] = []

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            calls.append(cmd)
            if cmd == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd == ["git", "merge-base", "--is-ancestor", "origin/master", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 1, "", "")
            if cmd == ["git", "merge", "origin/master", "--no-edit"]:
                return subprocess.CompletedProcess(
                    cmd,
                    1,
                    "",
                    "CONFLICT (content): Merge conflict in scripts/runtime_driver.py",
                )
            if cmd == ["git", "merge", "--abort"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            result = orch._merge_origin_master(worktree)

        assert result.status == "conflict"
        assert "CONFLICT" in result.stderr
        assert ["git", "merge", "--abort"] in calls


class TestVerifyPreflightMerge:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def _mock_verify_test_environment(
        self,
        worktree: Path,
    ) -> tuple[dict[str, str], object]:
        gate_env = {
            "SIM_DATABASE_URL": "postgresql://example/test_db",
            "SIM_TEST_DATABASE_URL": "postgresql://example/test_db",
            "PATH": f"{worktree / '.venv' / 'bin'}:/usr/bin",
            "VIRTUAL_ENV": str(worktree / ".venv"),
        }

        @contextmanager
        def fake_verify_test_environment(
            requested_worktree: Path,
            repo_root: Path | None = None,
        ):
            assert requested_worktree == worktree
            del repo_root
            yield gate_env

        return gate_env, fake_verify_test_environment

    def test_test_gate_diagnostic_command_uses_worktree_venv_python(self, repo: Path):
        worktree = repo / ".worktrees" / "my-feature"
        assert orch._test_gate_diagnostic_command(worktree) == [
            str(worktree / ".venv" / "bin" / "python"),
            *orch.TEST_GATE_DIAGNOSTIC_ARGS,
        ]

    def test_verify_allows_preflight_noop(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        gate_env, fake_verify_test_environment = self._mock_verify_test_environment(worktree)
        gate_ok = subprocess.CompletedProcess(["make", "test"], 0, "", "")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(True, "")),
            patch.object(
                orch,
                "_merge_origin_master",
                return_value=orch.MergeOriginMasterResult(status="noop"),
            ) as merge_mock,
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(
                orch,
                "_with_verify_test_environment",
                fake_verify_test_environment,
            ),
            patch.object(orch, "run_subprocess", return_value=gate_ok) as run_mock,
        ):
            result = orch.phase_verify(run, repo)

        assert result == "passed"
        run_mock.assert_called_once_with(
            ["make", "test"],
            cwd=worktree,
            env=gate_env,
            timeout=int(orch.DEFAULT_VERIFY_GATE_TIMEOUT_SECONDS),
        )
        merge_mock.assert_not_called()
        assert run.last_merged_master_sha == "mastersha"

    def test_verify_prepare_environment_failure_is_classified_for_operator(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        @contextmanager
        def fake_verify_test_environment(_worktree: Path, repo_root: Path | None = None):
            del repo_root
            raise RuntimeError(
                "Could not prepare verify test environment: local_postgres.sh start failed.\n"
                "--- stderr ---\n"
                "error: Postgres binaries not found. Install PostgreSQL 16 and set SIM_LOCAL_PG_BIN if needed."
            )
            yield {}

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(True, "")),
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(orch, "_with_verify_test_environment", fake_verify_test_environment),
        ):
            result = orch.phase_verify(run, repo)

        assert result == "failed"
        assert "Verify environment preparation failed for gate 'test'" in run.last_error
        assert "Postgres binaries not found" in run.last_error
        metadata = orch._classify_phase_result(run, "verify", result)
        assert metadata["failure_subtype"] == "prepare_environment_failed"
        assert metadata["retryable"] is False
        assert orch._workflow_failure_policy(run, "verify") is None

