    def test_verify_auto_resolves_conflict_with_theirs_when_enabled(self, repo: Path):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        gate_env, fake_verify_test_environment = self._mock_verify_test_environment(worktree)
        gate_ok = subprocess.CompletedProcess(["make", "test"], 0, "", "")
        merge_calls: list[tuple[bool, str | None]] = []

        def fake_merge(
            _worktree_path: Path,
            *,
            fetch_origin_master: bool = True,
            strategy_option: str | None = None,
        ) -> orch.MergeOriginMasterResult:
            merge_calls.append((fetch_origin_master, strategy_option))
            if strategy_option is None:
                return orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                )
            return orch.MergeOriginMasterResult(status="success")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(False, "")),
            patch.object(orch, "_merge_origin_master", side_effect=fake_merge),
            patch.object(orch, "_abort_merge_after_conflict", return_value="") as abort_mock,
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(
                orch,
                "_with_verify_test_environment",
                fake_verify_test_environment,
            ),
            patch.object(orch, "run_subprocess", return_value=gate_ok) as run_mock,
            patch.dict(orch.os.environ, {"SIM_SPEC_AUTO_MERGE": "true"}, clear=False),
        ):
            result = orch.phase_verify(run, repo)

        assert result == "passed"
        assert merge_calls == [(False, None), (False, "theirs")]
        abort_mock.assert_called_once_with(worktree)
        run_mock.assert_called_once_with(
            ["make", "test"],
            cwd=worktree,
            env=gate_env,
            timeout=int(orch.DEFAULT_VERIFY_GATE_TIMEOUT_SECONDS),
        )
        assert run.last_merged_master_sha == "mastersha"

    def test_verify_records_diagnostic_and_fingerprint_for_failed_test_gate(
        self,
        repo: Path,
    ):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        gate_env, fake_verify_test_environment = self._mock_verify_test_environment(worktree)
        diagnostic_command = orch._test_gate_diagnostic_command(worktree)
        targeted_alpha_command = orch._test_gate_targeted_diagnostic_command(
            worktree,
            "tests/test_api.py::test_alpha",
        )
        targeted_beta_command = orch._test_gate_targeted_diagnostic_command(
            worktree,
            "tests/test_api.py::test_beta",
        )
        gate_result = subprocess.CompletedProcess(
            args=["make", "test"],
            returncode=2,
            stdout=textwrap.dedent("""\
                ============================= test session starts ==============================
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                FAILED tests/test_api.py::test_beta - ValueError: bad
                2 failed, 41 passed in 0.45s
            """),
            stderr="make[1]: *** [test] Error 1\n",
        )
        diagnostic_result = subprocess.CompletedProcess(
            args=diagnostic_command,
            returncode=1,
            stdout=textwrap.dedent("""\
                ..FF                                                                     [100%]
                =================================== FAILURES ===================================
                _________________________________ test_alpha __________________________________
                tests/test_api.py:10: in test_alpha
                    assert value == 1
                E   AssertionError: expected 1
                _________________________________ test_beta ___________________________________
                tests/test_api.py:20: in test_beta
                    raise ValueError("bad")
                E   ValueError: bad
                =========================== short test summary info ============================
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                FAILED tests/test_api.py::test_beta - ValueError: bad
                2 failed, 41 passed in 0.45s
            """),
            stderr="",
        )
        targeted_alpha_result = subprocess.CompletedProcess(
            args=targeted_alpha_command,
            returncode=1,
            stdout=textwrap.dedent("""\
                =================================== FAILURES ===================================
                _________________________________ test_alpha __________________________________
                tests/test_api.py:10: in test_alpha
                    assert value == 1
                E   AssertionError: expected 1
                =========================== short test summary info ============================
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                1 failed in 0.12s
            """),
            stderr="",
        )
        targeted_beta_result = subprocess.CompletedProcess(
            args=targeted_beta_command,
            returncode=1,
            stdout=textwrap.dedent("""\
                =================================== FAILURES ===================================
                _________________________________ test_beta ___________________________________
                tests/test_api.py:20: in test_beta
                    raise ValueError("bad")
                E   ValueError: bad
                =========================== short test summary info ============================
                FAILED tests/test_api.py::test_beta - ValueError: bad
                1 failed in 0.11s
            """),
            stderr="",
        )
        seen_envs: list[dict[str, str]] = []

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            assert cwd == worktree
            if cmd == ["make", "test"]:
                assert timeout == int(orch.DEFAULT_VERIFY_GATE_TIMEOUT_SECONDS)
                assert env is gate_env
                seen_envs.append(env)
                return gate_result
            if cmd == diagnostic_command:
                assert timeout == orch.TEST_GATE_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                seen_envs.append(env)
                return diagnostic_result
            if cmd == targeted_alpha_command:
                assert timeout == orch.TARGETED_TEST_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                seen_envs.append(env)
                return targeted_alpha_result
            if cmd == targeted_beta_command:
                assert timeout == orch.TARGETED_TEST_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                seen_envs.append(env)
                return targeted_beta_result
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(False, "")),
            patch.object(
                orch,
                "_merge_origin_master",
                return_value=orch.MergeOriginMasterResult(status="noop"),
            ),
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(
                orch,
                "_with_verify_test_environment",
                fake_verify_test_environment,
            ),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
        ):
            result = orch.phase_verify(run, repo)

        assert result == "failed"
        assert seen_envs == [gate_env, gate_env, gate_env, gate_env]
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        data = json.loads(gate_file.read_text())
        gate = data["gates"]["test"]
        assert gate["last_stdout"].endswith("2 failed, 41 passed in 0.45s")
        assert gate["last_stderr"] == "make[1]: *** [test] Error 1"
        assert "tests/test_api.py:10: in test_alpha" in gate["last_diagnostic"]
        assert "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in gate["last_diagnostic"]
        assert "2 failed, 41 passed in 0.45s" in gate["last_diagnostic"]
        assert gate["first_failed_test_nodeid"] == "tests/test_api.py::test_alpha"
        assert gate["first_failed_test_reproducer"] == shlex.join(targeted_alpha_command)
        assert gate["first_targeted_diagnostic"]["nodeid"] == "tests/test_api.py::test_alpha"
        assert gate["final_failure_shape"] == "FAILED tests/test_api.py::test_beta - ValueError: bad"
        assert gate["failure_fingerprint"] == orch._build_test_failure_fingerprint(
            gate_result.stdout,
            diagnostic_result.stdout,
        )
        assert "2 failed, 41 passed in 0.45s" in run.last_error
        assert gate["history"] == [
            {
                "attempt": 1,
                "status": "failed",
                "passed_count": 41,
                "failed_count": 2,
                "error_count": 0,
                "failed_tests": [
                    "tests/test_api.py::test_alpha",
                    "tests/test_api.py::test_beta",
                ],
                "failure_fingerprint": gate["history"][0]["failure_fingerprint"],
                "timestamp": gate["history"][0]["timestamp"],
            }
        ]
        assert gate["history"][0]["failure_fingerprint"] == gate["failure_fingerprint"]

    def test_verify_records_timeout_note_and_falls_back_to_stdout_for_failed_test_gate(
        self,
        repo: Path,
    ):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        gate_env, fake_verify_test_environment = self._mock_verify_test_environment(worktree)
        diagnostic_command = orch._test_gate_diagnostic_command(worktree)
        targeted_command = orch._test_gate_targeted_diagnostic_command(
            worktree,
            "tests/test_api.py::test_alpha",
        )
        gate_result = subprocess.CompletedProcess(
            args=["make", "test"],
            returncode=2,
            stdout=textwrap.dedent("""\
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                1 failed, 41 passed in 0.45s
            """),
            stderr="make[1]: *** [test] Error 1\n",
        )
        targeted_result = subprocess.CompletedProcess(
            args=targeted_command,
            returncode=1,
            stdout=textwrap.dedent("""\
                ..F                                                                      [100%]
                =================================== FAILURES ===================================
                _________________________________ test_alpha __________________________________
                tests/test_api.py:10: in test_alpha
                    assert value == 1
                E   AssertionError: expected 1
                =========================== short test summary info ============================
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                1 failed in 0.12s
            """),
            stderr="",
        )

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            assert cwd == worktree
            if cmd == ["make", "test"]:
                assert timeout == int(orch.DEFAULT_VERIFY_GATE_TIMEOUT_SECONDS)
                assert env is gate_env
                return gate_result
            if cmd == diagnostic_command:
                assert timeout == orch.TEST_GATE_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                raise subprocess.TimeoutExpired(cmd=cmd, timeout=timeout)
            if cmd == targeted_command:
                assert timeout == orch.TARGETED_TEST_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                return targeted_result
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(False, "")),
            patch.object(
                orch,
                "_merge_origin_master",
                return_value=orch.MergeOriginMasterResult(status="noop"),
            ),
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(
                orch,
                "_with_verify_test_environment",
                fake_verify_test_environment,
            ),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
        ):
            result = orch.phase_verify(run, repo)

        assert result == "failed"
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        data = json.loads(gate_file.read_text())
        gate = data["gates"]["test"]
        assert gate["last_diagnostic"].startswith(orch.TEST_GATE_DIAGNOSTIC_UNAVAILABLE_PREFIX)
        assert "timed out after 120s" in gate["last_diagnostic"]
        assert len(gate["last_targeted_diagnostics"]) == 1
        targeted = gate["last_targeted_diagnostics"][0]
        assert targeted["nodeid"] == "tests/test_api.py::test_alpha"
        assert targeted["status"] == "failed"
        assert "tests/test_api.py:10: in test_alpha" in targeted["detail"]
        assert "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in targeted["detail"]
        assert "1 failed in 0.12s" in targeted["detail"]
        assert gate["failure_fingerprint"] == orch._build_test_failure_fingerprint(
            gate_result.stdout,
            gate["last_diagnostic"],
        )
        retry_output = orch._format_gate_retry_output("test", gate)
        assert retry_output.startswith("--- test (live reproducer) ---\n")
        assert "First failing node: tests/test_api.py::test_alpha" in retry_output
        assert "--- test (stdout) ---\nFAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in retry_output
        assert "--- test (targeted diagnostics) ---" in retry_output
        assert "[failed] tests/test_api.py::test_alpha" in retry_output
        assert "tests/test_api.py:10: in test_alpha" in retry_output
        assert "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in retry_output
        assert retry_output.endswith("--- test (stderr) ---\nmake[1]: *** [test] Error 1")

    def test_verify_records_broken_diagnostic_invocation_for_failed_test_gate(
        self,
        repo: Path,
    ):
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        gate_env, fake_verify_test_environment = self._mock_verify_test_environment(worktree)
        diagnostic_command = orch._test_gate_diagnostic_command(worktree)
        targeted_command = orch._test_gate_targeted_diagnostic_command(
            worktree,
            "tests/test_api.py::test_alpha",
        )
        gate_result = subprocess.CompletedProcess(
            args=["make", "test"],
            returncode=2,
            stdout=textwrap.dedent("""\
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                1 failed, 41 passed in 0.45s
            """),
            stderr="make[1]: *** [test] Error 1\n",
        )
        diagnostic_error = subprocess.CompletedProcess(
            args=diagnostic_command,
            returncode=3,
            stdout="INTERNALERROR> crash\n",
            stderr="Traceback (most recent call last): boom\n",
        )
        targeted_result = subprocess.CompletedProcess(
            args=targeted_command,
            returncode=1,
            stdout=textwrap.dedent("""\
                ..F                                                                      [100%]
                =================================== FAILURES ===================================
                _________________________________ test_alpha __________________________________
                tests/test_api.py:10: in test_alpha
                    assert value == 1
                E   AssertionError: expected 1
                =========================== short test summary info ============================
                FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                1 failed in 0.12s
            """),
            stderr="",
        )

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            assert cwd == worktree
            if cmd == ["make", "test"]:
                assert timeout == int(orch.DEFAULT_VERIFY_GATE_TIMEOUT_SECONDS)
                assert env is gate_env
                return gate_result
            if cmd == diagnostic_command:
                assert timeout == orch.TEST_GATE_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                return diagnostic_error
            if cmd == targeted_command:
                assert timeout == orch.TARGETED_TEST_DIAGNOSTIC_TIMEOUT_SECONDS
                assert env is gate_env
                return targeted_result
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_verify_preflight_shared_memory", return_value=True),
            patch.object(orch, "_fetch_origin_master", return_value=""),
            patch.object(orch, "_resolve_git_ref_sha", return_value="mastersha"),
            patch.object(orch, "_branch_contains_ref", return_value=(False, "")),
            patch.object(
                orch,
                "_merge_origin_master",
                return_value=orch.MergeOriginMasterResult(status="noop"),
            ),
            patch.object(orch, "REQUIRED_GATES", ("test",)),
            patch.object(
                orch,
                "_with_verify_test_environment",
                fake_verify_test_environment,
            ),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
        ):
            result = orch.phase_verify(run, repo)

        assert result == "failed"
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        data = json.loads(gate_file.read_text())
        gate = data["gates"]["test"]
        assert gate["last_diagnostic"].startswith(orch.TEST_GATE_DIAGNOSTIC_UNAVAILABLE_PREFIX)
        assert "exited 3 while running" in gate["last_diagnostic"]
        assert "stdout: INTERNALERROR> crash" in gate["last_diagnostic"]
        assert "stderr: Traceback (most recent call last): boom" in gate["last_diagnostic"]
        assert len(gate["last_targeted_diagnostics"]) == 1
        targeted = gate["last_targeted_diagnostics"][0]
        assert targeted["nodeid"] == "tests/test_api.py::test_alpha"
        assert targeted["status"] == "failed"
        assert "tests/test_api.py:10: in test_alpha" in targeted["detail"]
        assert "FAILED tests/test_api.py::test_alpha - AssertionError: expected 1" in targeted["detail"]
        assert "1 failed in 0.12s" in targeted["detail"]
        retry_output = orch._format_gate_retry_output("test", gate)
        assert retry_output.startswith("--- test (live reproducer) ---\n")
        assert "--- test (stdout) ---\n" in retry_output
        assert "--- test (targeted diagnostics) ---" in retry_output

