class TestLocalReviewStatusHelpers:
    def test_publish_local_review_status_creates_commit_status(self, repo: Path):
        review_result = orch.ReviewResult(
            status="approved",
            summary="Looks good.",
            findings=[],
            reviewed_head_sha="a" * 40,
            reviewed_base_sha="b" * 40,
            reviewed_at="2026-01-01T00:00:00Z",
        )

        submitted_payloads: list[dict] = []

        def mock_run_subprocess(
            cmd,
            cwd=None,
            env=None,
            timeout=None,
            inherit_env=True,
            input_text=None,
        ):  # noqa: ARG001
            if cmd == [
                "gh",
                "api",
                "repos/acme/repo/statuses/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                "-X",
                "POST",
                "-H",
                "Accept: application/vnd.github+json",
                "-H",
                "X-GitHub-Api-Version: 2022-11-28",
                "--input",
                "-",
            ]:
                submitted_payloads.append(json.loads(input_text or "{}"))
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    json.dumps({"target_url": "https://github.com/acme/repo/pull/42"}),
                    "",
                )
            raise AssertionError(f"unexpected command: {cmd}")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            check_url = orch._publish_local_review_status(
                repo,
                repo_name="acme/repo",
                expected_head_sha="a" * 40,
                review_result=review_result,
                target_url="https://github.com/acme/repo/pull/42",
            )

        assert check_url == "https://github.com/acme/repo/pull/42"
        assert submitted_payloads == [
            {
                "state": "success",
                "context": "review-decision-gate",
                "description": "Looks good.",
                "target_url": "https://github.com/acme/repo/pull/42",
            }
        ]

    def test_publish_local_review_status_truncates_long_descriptions(self, repo: Path):
        review_result = orch.ReviewResult(
            status="request_changes",
            summary="Needs changes. " + ("details " * 40),
            findings=[],
            reviewed_head_sha="a" * 40,
            reviewed_base_sha="b" * 40,
            reviewed_at="2026-01-01T00:00:00Z",
        )
        submitted_payloads: list[dict] = []

        def mock_run_subprocess(
            cmd,
            cwd=None,
            env=None,
            timeout=None,
            inherit_env=True,
            input_text=None,
        ):  # noqa: ARG001
            if cmd[:4] == ["gh", "api", "repos/acme/repo/statuses/aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", "-X"]:
                submitted_payloads.append(json.loads(input_text or "{}"))
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    json.dumps({"target_url": "https://github.com/acme/repo/pull/42"}),
                    "",
                )
            raise AssertionError(f"unexpected command: {cmd}")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            check_url = orch._publish_local_review_status(
                repo,
                repo_name="acme/repo",
                expected_head_sha="a" * 40,
                review_result=review_result,
                target_url="https://github.com/acme/repo/pull/42",
            )

        assert check_url == "https://github.com/acme/repo/pull/42"
        assert submitted_payloads[0]["state"] == "failure"
        assert len(submitted_payloads[0]["description"]) <= 140


