    def test_run_local_review_subprocess_records_sigterm_diagnostics(
        self,
        repo: Path,
        tmp_path: Path,
        caplog: pytest.LogCaptureFixture,
    ):
        artifact_paths = orch._local_review_artifact_paths(repo, "local-review-20260101T000000")
        worktree = tmp_path / "review"
        worktree.mkdir()

        class FakeProcess:
            pid = 4321
            returncode = -15

            def communicate(self, timeout: int):  # noqa: ARG002
                return ("partial stdout\n", "partial stderr\n")

        fake_proc = FakeProcess()

        with caplog.at_level(logging.INFO, logger=orch.logger.name):
            with (
                patch.object(orch.subprocess, "Popen", return_value=fake_proc),
                patch.object(
                    orch,
                    "read_process_identity",
                    return_value=orch.ProcessIdentity(
                        pid=4321,
                        started_at="Fri Mar 27 11:35:38 2026",
                        command="codex exec ...",
                    ),
                ),
                patch.object(orch.os, "getpgid", return_value=4321),
                patch.object(orch, "_register_worktree_process_from_popen") as register_process,
                patch.object(orch, "_prune_registered_worktree_processes") as prune_processes,
            ):
                result = orch._run_local_review_subprocess(
                    repo,
                    ["codex", "exec", "review prompt"],
                    cwd=worktree,
                    env={},
                    timeout=90,
                    artifact_paths=artifact_paths,
                )

        assert result.returncode == -15
        register_process.assert_called_once()
        prune_processes.assert_called_once_with(repo, worktree)
        payload = json.loads(artifact_paths["process_debug"].read_text())
        assert payload["pid"] == 4321
        assert payload["pgid"] == 4321
        assert payload["process_started_at"] == "Fri Mar 27 11:35:38 2026"
        assert payload["returncode"] == -15
        assert payload["signal"] == "SIGTERM"
        assert payload["timed_out"] is False
        assert payload["stdout_tail"] == "partial stdout"
        assert payload["stderr_tail"] == "partial stderr"
        assert payload["command"][-1] == "<prompt omitted; see prompt.md>"
        assert "Started local review subprocess pid=4321 pgid=4321" in caplog.text
        assert "signal=SIGTERM" in caplog.text

    def test_run_local_review_subprocess_timeout_records_termination_diagnostics(
        self,
        repo: Path,
        tmp_path: Path,
        caplog: pytest.LogCaptureFixture,
    ):
        artifact_paths = orch._local_review_artifact_paths(repo, "local-review-20260101T000001")
        worktree = tmp_path / "review"
        worktree.mkdir()

        class FakeProcess:
            pid = 9876
            returncode = None

            def communicate(self, timeout: int):
                raise subprocess.TimeoutExpired(
                    cmd=["codex", "exec"],
                    timeout=timeout,
                    output="partial stdout\n",
                    stderr="partial stderr\n",
                )

        fake_proc = FakeProcess()

        def mark_terminated(proc: FakeProcess) -> None:
            proc.returncode = -15

        with caplog.at_level(logging.WARNING, logger=orch.logger.name):
            with (
                patch.object(orch.subprocess, "Popen", return_value=fake_proc),
                patch.object(
                    orch,
                    "read_process_identity",
                    return_value=orch.ProcessIdentity(
                        pid=9876,
                        started_at="Fri Mar 27 11:35:38 2026",
                        command="codex exec ...",
                    ),
                ),
                patch.object(orch.os, "getpgid", return_value=9876),
                patch.object(orch, "_register_worktree_process_from_popen"),
                patch.object(orch, "_prune_registered_worktree_processes"),
                patch.object(orch, "_terminate_agent_process", side_effect=mark_terminated) as terminate_process,
            ):
                with pytest.raises(subprocess.TimeoutExpired):
                    orch._run_local_review_subprocess(
                        repo,
                        ["codex", "exec", "review prompt"],
                        cwd=worktree,
                        env={},
                        timeout=45,
                        artifact_paths=artifact_paths,
                    )

        terminate_process.assert_called_once_with(fake_proc)
        payload = json.loads(artifact_paths["process_debug"].read_text())
        assert payload["pid"] == 9876
        assert payload["pgid"] == 9876
        assert payload["timed_out"] is True
        assert payload["timeout_seconds"] == 45
        assert payload["returncode"] == -15
        assert payload["signal"] == "SIGTERM"
        assert payload["stdout_tail"] == "partial stdout"
        assert payload["stderr_tail"] == "partial stderr"
        assert "timed out after 45s; terminating process group" in caplog.text

    def test_local_review_isolation_blocks_push_and_impl_worktree_writes(
        self,
        repo: Path,
        tmp_path: Path,
        monkeypatch: pytest.MonkeyPatch,
    ):
        impl_worktree = tmp_path / "implementation"
        review_worktree = tmp_path / "review"
        _run_git("worktree", "add", "--detach", str(impl_worktree), "HEAD", cwd=repo)
        _run_git("worktree", "add", "--detach", str(review_worktree), "HEAD", cwd=repo)

        protected_dir = impl_worktree / "protected"
        protected_dir.mkdir()
        protected_dir.chmod(0o555)

        remote_path = Path(_run_git_stdout("config", "--get", "remote.origin.url", cwd=repo).strip())
        hook_path = remote_path / "hooks" / "pre-receive"
        hook_path.write_text(
            "#!/bin/sh\n"
            'if [ "$GH_TOKEN" = "allow-review-push" ]; then\n'
            "  exit 0\n"
            "fi\n"
            "echo 'missing GH_TOKEN' >&2\n"
            "exit 1\n"
        )
        hook_path.chmod(0o755)

        monkeypatch.setenv("GH_TOKEN", "allow-review-push")

        schema_path = tmp_path / "schema.json"
        schema_path.write_text("{}\n")
        output_path = tmp_path / "codex-review.json"
        results_path = tmp_path / "reviewer-results.json"

        bin_dir = tmp_path / "bin"
        bin_dir.mkdir()
        fake_codex = bin_dir / "codex"
        fake_codex.write_text(
            "#!/usr/bin/env python3\n"
            "import json\n"
            "import os\n"
            "import subprocess\n"
            "import sys\n"
            "from pathlib import Path\n"
            "\n"
            "args = sys.argv[1:]\n"
            "output_path = Path(args[args.index('-o') + 1])\n"
            "target_dir = Path(os.environ['SIM_TEST_IMPL_WRITE_TARGET'])\n"
            "results_path = Path(os.environ['SIM_TEST_RESULTS_PATH'])\n"
            "write_blocked = False\n"
            "write_error = ''\n"
            "try:\n"
            "    (target_dir / 'probe.txt').write_text('probe')\n"
            "except OSError as exc:\n"
            "    write_blocked = True\n"
            "    write_error = str(exc)\n"
            "remote_url = subprocess.run(\n"
            "    ['git', 'config', '--get', 'remote.origin.url'],\n"
            "    capture_output=True,\n"
            "    text=True,\n"
            "    check=True,\n"
            ").stdout.strip()\n"
            "push = subprocess.run(\n"
            "    ['git', 'push', remote_url, 'HEAD:refs/heads/reviewer-push-attempt'],\n"
            "    capture_output=True,\n"
            "    text=True,\n"
            ")\n"
            "results = {\n"
            "    'cwd': os.getcwd(),\n"
            "    'push_blocked': push.returncode != 0,\n"
            "    'push_stderr': push.stderr,\n"
            "    'saw_read_only': '-s' in args and args[args.index('-s') + 1] == 'read-only',\n"
            "    'write_blocked': write_blocked,\n"
            "    'write_error': write_error,\n"
            "}\n"
            "results_path.write_text(json.dumps(results) + '\\n')\n"
            "output_path.write_text(json.dumps({'decision': 'approved'}) + '\\n')\n"
        )
        fake_codex.chmod(0o755)

        review_env = orch._build_local_review_env()
        review_env["PATH"] = f"{bin_dir}{os.pathsep}{review_env.get('PATH', os.environ.get('PATH', ''))}"
        review_env["SIM_TEST_IMPL_WRITE_TARGET"] = str(protected_dir)
        review_env["SIM_TEST_RESULTS_PATH"] = str(results_path)

        cmd = orch._build_local_review_command(
            prompt="review this change",
            schema_path=schema_path,
            output_path=output_path,
            agent_name="codex",
        )
        result = orch.run_subprocess(
            cmd,
            cwd=review_worktree,
            env=review_env,
            inherit_env=False,
        )

        assert result.returncode == 0
        results = json.loads(results_path.read_text())
        assert Path(results["cwd"]) == review_worktree
        assert results["saw_read_only"] is True
        assert results["write_blocked"] is True
        assert not (protected_dir / "probe.txt").exists()
        assert results["push_blocked"] is True
        assert "missing GH_TOKEN" in results["push_stderr"]

    def test_temporary_review_worktree_cleans_up_on_error(self, repo: Path, tmp_path: Path):
        expected_head_sha = "a" * 40

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):  # noqa: ARG001
            if cmd[:3] == ["git", "cat-file", "-e"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            assert cmd[:4] == ["git", "worktree", "add", "--detach"]
            Path(cmd[4]).mkdir(parents=True, exist_ok=True)
            return subprocess.CompletedProcess(cmd, 0, "", "")

        with (
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", tmp_path),
            patch.object(orch, "_cleanup_stale_review_worktrees"),
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_head_sha", return_value=expected_head_sha),
            patch.object(orch, "_cleanup_worktree_checkout", return_value="") as cleanup,
        ):
            with pytest.raises(RuntimeError):
                with orch._temporary_review_worktree(repo, head_sha=expected_head_sha):
                    raise RuntimeError("boom")

        cleanup.assert_called_once()
        wt_path = str(cleanup.call_args.args[1])
        assert "spec-review-" in wt_path

