    def test_temporary_review_worktree_fetches_missing_head(
        self, repo: Path, tmp_path: Path
    ):
        expected_head_sha = "a" * 40
        branch = "code/my-feature--run123"
        catfile_calls = {"n": 0}

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):  # noqa: ARG001
            if cmd[:3] == ["git", "cat-file", "-e"]:
                catfile_calls["n"] += 1
                # Missing before the fetch, present after.
                rc = 0 if catfile_calls["n"] >= 2 else 1
                return subprocess.CompletedProcess(cmd, rc, "", "")
            assert cmd[:4] == ["git", "worktree", "add", "--detach"]
            Path(cmd[4]).mkdir(parents=True, exist_ok=True)
            return subprocess.CompletedProcess(cmd, 0, "", "")

        fetch_outcome = SimpleNamespace(is_success=True, stderr="", stdout="")

