    def test_cleanup_stale_review_worktrees_skips_registered_and_foreign_worktrees(
        self,
        repo: Path,
        tmp_path: Path,
    ):
        registered = tmp_path / "spec-review-registered"
        foreign = tmp_path / "spec-review-foreign"
        stale = tmp_path / "spec-review-stale"
        registered.mkdir()
        foreign.mkdir()
        stale.mkdir()

        def fake_common_root(path: Path | None = None) -> Path:
            resolved = Path.cwd().resolve() if path is None else path.resolve()
            if resolved in (repo.resolve(), registered.resolve(), stale.resolve()):
                return repo.resolve()
            if resolved == foreign.resolve():
                return tmp_path / "other-repo"
            return resolved

        def fake_registered(_repo_root: Path, worktree_path: Path) -> tuple[bool, str]:
            return (worktree_path == registered, "")

        with (
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", tmp_path),
            patch.object(orch, "resolve_common_root", side_effect=fake_common_root),
            patch.object(orch, "_worktree_is_registered", side_effect=fake_registered),
            patch.object(orch, "_cleanup_worktree_checkout", return_value="") as cleanup,
        ):
            orch._cleanup_stale_review_worktrees(repo)

        cleanup.assert_called_once_with(repo, stale, delete_branch=False)


