class TestReviewPhaseRouting:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="review-routing-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--run123",
        )

    def test_find_pr_for_branch_uses_gh_245_compatible_fields(self, repo: Path):
        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            assert cmd[:3] == ["gh", "pr", "list"]
            fields = cmd[cmd.index("--json") + 1]
            assert "baseRefOid" not in fields
            payload = {
                "number": 42,
                "state": "OPEN",
                "url": "https://github.com/acme/repo/pull/42",
                "body": "",
                "headRefName": "code/my-feature--run123",
                "headRefOid": "a" * 40,
                "mergeStateStatus": "UNKNOWN",
                "isDraft": False,
            }
            return subprocess.CompletedProcess(cmd, 0, json.dumps(payload), "")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            pr = orch._find_pr_for_branch(repo, "code/my-feature--run123")

        assert pr is not None
        assert pr["number"] == 42
        assert pr["headRefOid"] == "a" * 40

    def test_find_pr_for_branch_falls_back_to_rest_after_graphql_failure(
        self,
        repo: Path,
    ):
        branch = "code/my-feature--run123"
        rest_payload = [{
            "number": 42,
            "state": "closed",
            "merged_at": "2026-08-17T17:07:01Z",
            "html_url": "https://github.com/acme/repo/pull/42",
            "body": "Review-Owner: local",
            "head": {"ref": branch, "sha": "a" * 40},
            "draft": False,
            "mergeable_state": None,
        }]

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["gh", "pr", "list"]:
                return subprocess.CompletedProcess(
                    cmd,
                    1,
                    "",
                    "HTTP 503: No server is currently available",
                )
            if cmd[:3] == ["gh", "api", "-X"]:
                endpoint = cmd[-1]
                assert endpoint.startswith("repos/acme/repo/pulls?")
                assert "state=all" in endpoint
                assert "head=acme%3Acode%2Fmy-feature--run123" in endpoint
                assert "base=master" in endpoint
                return subprocess.CompletedProcess(cmd, 0, json.dumps(rest_payload), "")
            raise AssertionError(f"unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
        ):
            pr = orch._find_pr_for_branch(repo, branch, state="all")

        assert pr == {
            "number": 42,
            "state": "MERGED",
            "url": "https://github.com/acme/repo/pull/42",
            "body": "Review-Owner: local",
            "headRefName": branch,
            "headRefOid": "a" * 40,
            "mergeStateStatus": "UNKNOWN",
            "isDraft": False,
        }

    def test_phase_review_resolves_base_sha_when_pr_list_metadata_omits_it(
        self,
        repo: Path,
        tmp_path: Path,
    ):
        run = self._make_run()
        run.save(repo)

