class TestLocalReviewPhase:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="local-review-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--run123",
            review_agent="claude",
        )

    def test_local_mode_runs_codex_review_and_skips_check_polling(
        self,
        repo: Path,
        tmp_path: Path,
        caplog: pytest.LogCaptureFixture,
        capsys: pytest.CaptureFixture[str],
    ):
        run = self._make_run()
        run.save(repo)

        pr = {
            "number": 42,
            "state": "OPEN",
            "url": "https://github.com/acme/repo/pull/42",
            "body": "## Review\nReview-Owner: local\n",
            "headRefOid": "a" * 40,
            "baseRefOid": "b" * 40,
        }
        schema_dir = repo / ".github" / "schemas"
        schema_dir.mkdir(parents=True)
        (schema_dir / "codex-review.schema.json").write_text("{}\n")
        impl_worktree = tmp_path / "implementation"
        impl_worktree.mkdir()
        review_worktree = tmp_path / "review"
        review_worktree.mkdir()

        # The raw review JSON that the claude agent writes to stdout.
        raw_review_json = json.dumps(
            {
                "decision": "approved",
                "summary": "Looks good.",
                "reviewed_head_sha": pr["headRefOid"],
                "reviewed_base_sha": pr["baseRefOid"],
                "findings": [],
            }
        )

        @contextmanager
        def fake_review_worktree(repo_root: Path, *, head_sha: str, branch=None):  # noqa: ARG001
            assert head_sha == pr["headRefOid"]
            yield review_worktree

        def mock_run_subprocess(
            cmd,
            cwd=None,
            env=None,
            timeout=None,
            inherit_env=True,
            input_text=None,
        ):  # noqa: ARG001
            if cmd == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd == ["gh", "pr", "merge", "42", "--disable-auto"]:
                return subprocess.CompletedProcess(cmd, 0, "disabled", "")
            if cmd == [
                "gh",
                "api",
                f"repos/acme/repo/statuses/{pr['headRefOid']}",
                "-X",
                "POST",
                "-H",
                "Accept: application/vnd.github+json",
                "-H",
                "X-GitHub-Api-Version: 2022-11-28",
                "--input",
                "-",
            ]:
                payload = json.loads(input_text or "{}")
                assert payload["state"] == "success"
                assert payload["context"] == orch.REVIEW_GATE_CHECK_NAME
                assert payload["target_url"] == pr["url"]
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    json.dumps({"target_url": pr["url"]}),
                    "",
                )
            if cmd == ["gh", "auth", "token"]:
                return subprocess.CompletedProcess(cmd, 0, "ghs_test_token\n", "")
            if cmd[:2] == ["python3", "scripts/review_gate_sticky_comment.py"]:
                assert env is not None
                assert env["GITHUB_TOKEN"] == "ghs_test_token"
                return subprocess.CompletedProcess(cmd, 0, "updated sticky\n", "")
            raise AssertionError(f"unexpected command: {cmd}")

        def mock_review_exec(
            repo_root: Path,
            cmd: list[str],
            *,
            cwd: Path,
            env: dict[str, str],
            timeout: int,
            artifact_paths: dict[str, Path] | None = None,  # noqa: ARG001
        ) -> subprocess.CompletedProcess:
            assert repo_root == repo
            assert cmd[0] == "claude"
            assert cwd == review_worktree
            assert env["GIT_TERMINAL_PROMPT"] == "0"
            assert timeout == orch.REVIEW_TIMEOUT_SECONDS
            return subprocess.CompletedProcess(cmd, 0, raw_review_json, "")

        with caplog.at_level(logging.INFO, logger=orch.logger.name):
            with (
                patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
                patch.object(orch, "_run_local_review_subprocess", side_effect=mock_review_exec),
                patch.object(orch, "resolve_worktree_path", return_value=impl_worktree),
                patch.object(orch, "_head_sha", return_value=pr["headRefOid"]),
                patch.object(orch.shutil, "which", return_value="/usr/bin/claude"),
                patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
                patch.object(orch, "_render_local_review_prompt", return_value="prompt"),
                patch.object(orch, "_temporary_review_worktree", side_effect=fake_review_worktree),
                patch.object(orch, "_find_pr_for_branch", side_effect=[pr, pr]),
            ):
                result = orch.phase_review(run, repo)

        assert result == "passed"
        assert run.review_decision_status == "approved"
        assert run.review_decision_summary == "Looks good."
        assert run.review_decision_check_url == pr["url"]
        assert (
            "Running local review for code/my-feature--run123 with reasoning effort=high "
            "(review_changes=0)" in caplog.text
        )
        captured = capsys.readouterr()
        assert "[spec] my-feature: review running with claude for PR #42" in captured.err
        assert "[spec] my-feature: review completed with approved" in captured.err
        saved = orch.ReviewResult.load(repo, run.run_id)
        assert saved is not None
        assert saved.status == "approved"

