        timeout_debug_path = repo / ".spec-state" / "runs" / run.run_id / "local-review" / "timeout-debug.json"
        debug_payload = json.loads(timeout_debug_path.read_text())

        assert review_result.status == "failed"
        assert "Local Claude reviewer timed out after 900s." in review_result.summary
        assert "timeout-debug.json" in review_result.summary
        assert debug_payload["stdout_tail"] == "partial stdout"
        assert debug_payload["stderr_tail"] == "partial stderr"

