        schema_dir.mkdir(parents=True)
        (schema_dir / "codex-review.schema.json").write_text("{}\n")
        impl_worktree = tmp_path / "implementation"
        impl_worktree.mkdir()
        review_worktree = tmp_path / "review"
        review_worktree.mkdir()
        status_payloads: list[dict[str, object]] = []

        @contextmanager
        def fake_review_worktree(repo_root: Path, *, head_sha: str, branch=None):  # noqa: ARG001
            assert head_sha == pr["headRefOid"]
            yield review_worktree

        def mock_run_subprocess(
            cmd,
            cwd=None,
            env=None,
            timeout=None,
            inherit_env=True,
            input_text=None,
        ):  # noqa: ARG001
            if cmd == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd == ["gh", "pr", "merge", "42", "--disable-auto"]:
                return subprocess.CompletedProcess(cmd, 0, "disabled", "")
            if cmd == [
                "gh",
                "api",
                f"repos/acme/repo/statuses/{pr['headRefOid']}",
                "-X",
                "POST",
                "-H",
                "Accept: application/vnd.github+json",
                "-H",
                "X-GitHub-Api-Version: 2022-11-28",
                "--input",
                "-",
            ]:
                status_payloads.append(json.loads(input_text or "{}"))
                return subprocess.CompletedProcess(
                    cmd,
                    0,
                    json.dumps({"target_url": pr["url"]}),
                    "",
                )
            raise AssertionError(f"unexpected command: {cmd}")

        def mock_review_exec(
            repo_root: Path,
            cmd: list[str],
            *,
            cwd: Path,
            env: dict[str, str],
            timeout: int,
            artifact_paths: dict[str, Path] | None = None,  # noqa: ARG001
        ) -> subprocess.CompletedProcess:
            assert repo_root == repo
            assert cmd[0] == "claude"
            assert cwd == review_worktree
            raise subprocess.TimeoutExpired(
                cmd=cmd,
                timeout=timeout,
                output="claude stdout\n",
                stderr="claude stderr\n",
            )

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_run_local_review_subprocess", side_effect=mock_review_exec),
            patch.object(orch, "resolve_worktree_path", return_value=impl_worktree),
            patch.object(orch, "_head_sha", return_value=pr["headRefOid"]),
            patch.object(orch.shutil, "which", return_value="/usr/bin/claude"),
            patch.object(orch, "_repo_name_with_owner", return_value="acme/repo"),
            patch.object(orch, "_render_local_review_prompt", return_value="prompt"),
            patch.object(orch, "_temporary_review_worktree", side_effect=fake_review_worktree),
            patch.object(orch, "_find_pr_for_branch", side_effect=[pr, pr]),
        ):
            result = orch.phase_review(run, repo)

        saved = orch.ReviewResult.load(repo, run.run_id)
        assert result == "blocked"
        assert run.review_decision_status == "blocked"
        assert "Local Claude reviewer timed out after 900s." in run.review_decision_summary
        assert "timeout-debug.json" in run.review_decision_summary
        assert run.review_decision_check_url == pr["url"]
        assert len(status_payloads) == 1
        assert status_payloads[0]["state"] == "pending"
        assert status_payloads[0]["context"] == orch.REVIEW_GATE_CHECK_NAME
        assert saved is not None
        assert saved.status == "failed"

