    def test_stale_pr_head_uses_remote_head(self, repo: Path):
        """When PR metadata head is stale and worktree unavailable, use remote head."""
        run = self._make_run()
        run.save(repo)

        auth_ok = subprocess.CompletedProcess(
            args=["gh", "auth", "status"],
            returncode=0,
            stdout="ok",
            stderr="",
        )
        stale_pr = {
            "number": 42,
            "state": "OPEN",
            "headRefOid": "1111111111111111111111111111111111111111",
            "baseRefOid": "base1234sha",
        }
        remote_head = "2222222222222222222222222222222222222222"

        def mock_run_subprocess(cmd, cwd=None, env=None, timeout=None):
            if cmd == ["gh", "auth", "status"]:
                return auth_ok
            if cmd[:3] == ["git", "ls-remote", "origin"]:
                return subprocess.CompletedProcess(
                    args=cmd,
                    returncode=0,
                    stdout=(f"{remote_head}\trefs/heads/{run.branch}\n"),
                    stderr="",
                )
            raise AssertionError(f"unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=stale_pr),
            patch.object(orch, "_head_sha", return_value=None),
            patch.object(orch, "_phase_review_local", return_value="passed") as local_mock,
        ):
            result = orch.phase_review(run, repo)

        assert result == "passed"
        assert run.review_expected_head_sha == remote_head
        local_mock.assert_called_once()
        # Verify the corrected head SHA was passed to _phase_review_local
        call_kwargs = local_mock.call_args
        assert call_kwargs.kwargs["expected_head_sha"] == remote_head

