class TestRequiredChecksGate:
    def test_required_checks_green(self, repo: Path):
        checks_payload = json.dumps(
            [
                {"name": "CI / test", "bucket": "pass", "state": "SUCCESS", "link": ""},
                {
                    "name": "review-decision-gate",
                    "bucket": "pass",
                    "state": "SUCCESS",
                    "link": "",
                },
            ]
        )
        ok_result = subprocess.CompletedProcess(
            args=["gh", "pr", "checks"],
            returncode=0,
            stdout=checks_payload,
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=ok_result):
            ok, msg = orch._required_checks_green(repo, 12)
        assert ok is True
        assert msg == ""

    def test_required_checks_pending(self, repo: Path):
        checks_payload = json.dumps(
            [
                {
                    "name": "review-decision-gate",
                    "bucket": "pending",
                    "state": "IN_PROGRESS",
                    "link": "https://example.com/check",
                }
            ]
        )
        pending_result = subprocess.CompletedProcess(
            args=["gh", "pr", "checks"],
            returncode=0,
            stdout=checks_payload,
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=pending_result):
            ok, msg = orch._required_checks_green(repo, 12)
        assert ok is False
        assert "pending" in msg.lower()

    def test_required_checks_empty_set_is_green(self, repo: Path):
        """An empty check set must not refuse the merge when checks have not
        registered on a fresh head yet, nor wait forever when a repo requires
        no checks). The merge command itself arbitrates; GitHub's 'required
        status check is expected' rejection already routes to the bounded
        merge-race retry."""
        empty_result = subprocess.CompletedProcess(
            args=["gh", "pr", "checks"],
            returncode=0,
            stdout="[]",
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=empty_result):
            ok, msg = orch._required_checks_green(repo, 12)
        assert ok is True
        assert msg == ""

    def test_required_checks_pending_exit_code_with_payload_stays_pending(self, repo: Path):
        """gh pr checks exits 8 for pending checks while still printing JSON;
        the payload, not the exit code, is authoritative (review finding on
        the first cut of this change)."""
        pending_result = subprocess.CompletedProcess(
            args=["gh", "pr", "checks"],
            returncode=8,
            stdout=json.dumps(
                [{"name": "ci", "bucket": "pending", "state": "IN_PROGRESS", "link": ""}]
            ),
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=pending_result):
            ok, msg = orch._required_checks_green(repo, 12)
        assert ok is False
        assert "pending" in msg.lower()
        assert orch._required_checks_still_pending(msg) is True

    def test_required_checks_query_failure_is_pending_not_green(self, repo: Path):
        failed_result = subprocess.CompletedProcess(
            args=["gh", "pr", "checks"],
            returncode=1,
            stdout="",
            stderr="connection reset",
        )
        with patch.object(orch, "run_subprocess", return_value=failed_result):
            ok, msg = orch._required_checks_green(repo, 12)
        assert ok is False
        assert orch._required_checks_still_pending(msg) is True

    def test_merge_race_matcher_covers_unregistered_expected_checks(self):
        """GitHub can reject the merge with
        'required status check ... is expected' until checks register; that
        shape must keep routing to the bounded direct merge retry."""
        assert orch._is_retryable_merge_race_error(
            "Repository rule violations found\n\nrequired status check "
            '"ci" is expected.'
        ) is True


