class TestBuildAgentCommand:
    def _retry_context(self, **overrides) -> orch.ImplementContext:
        ctx = orch.ImplementContext(
            implement_reason="retry",
            run_id="my-feature-20260101T000000",
            attempt_number=2,
            run_state_dir=".spec-state/runs/my-feature-20260101T000000/",
            current_head_sha="abc1234",
        )
        for key, value in overrides.items():
            setattr(ctx, key, value)
        return ctx

    def test_prompt_includes_completion_instruction(self, tmp_path: Path):
        cmd = orch._build_agent_command("claude", tmp_path, spec_id="my-feature")
        prompt = cmd[-1]
        assert "Exit Checklist:" in prompt
        assert "spec report" in prompt
        assert "ok|blocked|error|needs-input" in prompt
        assert "spec report" in prompt
        assert "--spec my-feature" in prompt
        assert "--summary 'plain text summary'" in prompt
        assert "do not include backticks or `$()`" in prompt
        assert '--summary "..."' not in prompt

    def test_recovery_prompt_includes_needs_input(self, tmp_path: Path):
        ctx = self._retry_context(
            recovery_objective=(
                "Do not re-implement the spec. Inspect the current worktree state, "
                "commit any already-completed work, rerun `pytest` and `ruff check .` only if "
                "that is still feasible, and report STATUS=ok|blocked|error|needs-input. If the existing "
                "changes are incomplete or unclear, report blocked/error with a concise reason."
            ),
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert "needs-input" in prompt
        assert "ok|blocked|error|needs-input" in prompt

    def test_initial_prompt_uses_spec_prompt(self, tmp_path: Path):
        cmd = orch._build_agent_command("claude", tmp_path)
        assert orch.SPEC_PROMPT.replace("<spec-revision>", "(unknown)") in cmd[-1]

    def test_spec_prompt_does_not_forbid_spec_report(self):
        assert "Do NOT run" in orch.SPEC_PROMPT
        # spec report must not appear in the "Do NOT run" sentence
        ban_line = [line for line in orch.SPEC_PROMPT.splitlines() if "Do NOT run orchestrator" in line][0]
        # Only check the ban clause, not the clarification that follows
        ban_clause = ban_line.split("The only orchestrator command")[0]
        assert "spec report" not in ban_clause

    def test_prompt_includes_acceptance_and_verification_contract(self, tmp_path: Path):
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            spec_id="my-feature",
            acceptance_checklist=["- [ ] Ship the feature"],
            verification_expectations=["- run `make test` during implement"],
        )
        prompt = cmd[-1]
        assert "Spec Contract:" in prompt
        assert "Acceptance Checklist:" in prompt
        assert "- [ ] Ship the feature" in prompt
        assert "Verification Expectations:" in prompt
        assert "- run `make test` during implement" in prompt

    def test_prompt_includes_resolved_input_context(self, tmp_path: Path):
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            spec_id="my-feature",
            input_question="Choose the rollout window.",
            input_response="Friday night",
        )
        prompt = cmd[-1]
        assert "Resolved implement input:" in prompt
        assert "Choose the rollout window." in prompt
        assert "- Answer: Friday night" in prompt

    def test_initial_prompt_includes_resolved_spec_intake(self, tmp_path: Path):
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            spec_id="my-feature",
            intake={
                "answers": {
                    "future_fx_policy": "caller-supplied-fixed-rate",
                    "foreign_wrapper_policy": (
                        "preserve-wrapper-identity-and-apply-cross-border-rules"
                    ),
                }
            },
        )

        prompt = cmd[-1]
        assert "Resolved spec intake:" in prompt
        assert "These persisted choices are authoritative" in prompt
        assert '- future_fx_policy: "caller-supplied-fixed-rate"' in prompt
        assert (
            '- foreign_wrapper_policy: "preserve-wrapper-identity-and-apply-cross-border-rules"'
            in prompt
        )

    def test_prompt_includes_resolved_operator_intervention_context(self, tmp_path: Path):
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            spec_id="my-feature",
            operator_request=orch.OperatorRequest(
                kind="debugger_guidance",
                prompt="The blocked-run debugger requires a retry strategy.",
                suggested_action="Pick the smallest credible retry plan.",
                options=[
                    {
                        "value": "resume",
                        "label": "Resume",
                        "description": "Retry with the targeted fix.",
                    }
                ],
                status="resolved",
                response="Resume with the targeted lint fix.",
            ),
        )
        prompt = cmd[-1]
        assert "Resolved operator intervention:" in prompt
        assert "debugger_guidance" in prompt
        assert "Resume with the targeted lint fix." in prompt

    def test_prompt_includes_proactive_operator_steering_context(self, tmp_path: Path):
        ctx = self._retry_context(
            operator_steering_message="Retry with the smaller schema adjustment first.",
            operator_steering_provided_by="alice",
            operator_steering_provided_at="2026-01-02T03:04:05Z",
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert "Proactive operator steering:" in prompt
        assert "Retry with the smaller schema adjustment first." in prompt
        assert "Provided by: alice" in prompt

    def test_initial_prompt_includes_prior_attempt_findings_once(self, tmp_path: Path):
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            spec_id="my-feature",
            prior_review_run_id="my-feature-20260101T000000",
            prior_review_summary="Independent review requested changes.",
            prior_review_findings=[
                {
                    "id": "finding-1",
                    "title": "Request payload drift",
                    "severity": "P1",
                    "file": "api/routes.py",
                    "start_line": 12,
                    "end_line": 14,
                    "body": "Align the initial implementation with the persisted schema.",
                    "confidence": 0.93,
                }
            ],
        )
        prompt = cmd[-1]
        assert "Prior attempt findings:" in prompt
        assert "previous abandoned attempt" in prompt
        assert "Address them proactively during your initial implementation" in prompt
        assert ".spec-state/runs/my-feature-20260101T000000/review-result.json" in prompt
        assert "[P1] Request payload drift (api/routes.py:12-14; confidence 0.93)" in prompt
        assert "Align the initial implementation with the persisted schema." in prompt

    def test_retry_prompt_ignores_prior_attempt_findings(self, tmp_path: Path):
        ctx = self._retry_context(
            failing_commands=["make lint"],
            failure_summary="lint: failed (attempt 2)",
        )
        cmd = orch._build_agent_command(
            "claude",
            tmp_path,
            retry_context=ctx,
            prior_review_run_id="my-feature-20260101T000000",
            prior_review_findings=[
                {
                    "id": "finding-1",
                    "title": "Request payload drift",
                    "severity": "P1",
                    "file": "api/routes.py",
                    "start_line": 12,
                    "end_line": 14,
                    "body": "Align the initial implementation with the persisted schema.",
                    "confidence": 0.93,
                }
            ],
        )
        prompt = cmd[-1]
        assert "Retry failure package:" in prompt
        assert "Prior attempt findings:" not in prompt

    def test_retry_prompt_gate_failure_only(self, tmp_path: Path):
        ctx = self._retry_context(
            failing_commands=["make lint", "make test"],
            failure_summary="lint: failed (attempt 2); test: failed (attempt 2)",
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert orch.SPEC_PROMPT not in prompt
        assert "Retry failure package:" in prompt
        assert ".spec-state/runs/my-feature-20260101T000000/" in prompt
        assert "implement-context.json, gate-status.json, and review-result.json if present" in prompt
        assert "Run ID: my-feature-20260101T000000" in prompt
        assert "Attempt: 2" in prompt
        assert "make lint" in prompt
        assert "make test" in prompt
        assert "Before reporting completion, run the failing command yourself" in prompt
        assert "Do NOT re-implement from scratch" in prompt
        assert "Current local head SHA: abc1234" in prompt
        assert "Review findings: none" in prompt
        assert "Merge conflict or PR mergeability issue: no active mergeability issue" in prompt

    def test_retry_prompt_review_findings_only(self, tmp_path: Path):
        ctx = self._retry_context(
            implement_reason="review_feedback",
            review_feedback_active=True,
            review_findings_count=2,
            review_source_check_url="https://example.com/checks/123",
            failure_summary="Independent review requested changes. Fix request payload drift.",
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert "Review findings: unresolved live findings (2 structured findings)" in prompt
        assert "Address the unresolved review findings" in prompt
        assert "https://example.com/checks/123" in prompt
        assert "Active gates/checks: none recorded" in prompt
        # Live findings get the class mandate: fixing only the reported instances
        # is what turns one defect into one review round per instance.
        assert orch.REVIEW_FINDING_CLASS_INSTRUCTION in prompt

    def test_retry_prompt_omits_class_mandate_without_live_findings(self, tmp_path: Path):
        gate_only = orch._build_agent_command(
            "claude",
            tmp_path,
            retry_context=self._retry_context(
                failing_commands=["make test"],
                failure_summary="test: failed (attempt 2)",
            ),
        )[-1]
        assert orch.REVIEW_FINDING_CLASS_INSTRUCTION not in gate_only

        stale_only = orch._build_agent_command(
            "claude",
            tmp_path,
            retry_context=self._retry_context(
                reviewed_head_sha="def5678",
                stale_review_feedback=True,
                review_findings_count=2,
                failure_summary="test: failed (attempt 2); stale review evidence",
            ),
        )[-1]
        assert orch.REVIEW_FINDING_CLASS_INSTRUCTION not in stale_only

    def test_retry_prompt_labels_stale_review_evidence(self, tmp_path: Path):
        ctx = self._retry_context(
            reviewed_head_sha="def5678",
            stale_review_feedback=True,
            review_findings_count=2,
            review_source_check_url="https://example.com/checks/456",
            failure_summary="test: failed (attempt 2); stale review evidence from def5678",
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert "Current local head SHA: abc1234" in prompt
        assert "Latest review head SHA: def5678 (differs from local head)" in prompt
        assert "Review findings: stale review evidence (2 structured findings)" in prompt
        assert "Use it as hints only after you address the current live failures." in prompt

    def test_retry_prompt_prioritizes_live_test_reproducer(self, tmp_path: Path):
        reproducer = orch._render_test_gate_targeted_diagnostic_command(
            tmp_path,
            "tests/test_api.py::test_alpha",
        )
        ctx = self._retry_context(
            failing_commands=["make test", "make lint"],
            first_failed_test_nodeid="tests/test_api.py::test_alpha",
            first_failed_test_reproducer=reproducer,
            first_failed_test_diagnostic="tests/test_api.py:10: in test_alpha\nE   AssertionError: inner assertion",
            reviewed_head_sha="def5678",
            stale_review_feedback=True,
            review_findings_count=2,
            triggering_review_result_path=".spec-state/runs/example/review-result.json",
            failure_summary="test: failed (attempt 2); stale review evidence from def5678",
        )
        cmd = orch._build_agent_command("claude", tmp_path, retry_context=ctx)
        prompt = cmd[-1]
        assert "First failing test node: tests/test_api.py::test_alpha" in prompt
        assert f"Rerun this exact node first on the current head: {reproducer}" in prompt
        assert "Before claiming the branch is fixed, rerun the exact failing node" in prompt
        assert "Use it as hints only after you address the current live failures." in prompt
        assert prompt.index("Current local head SHA: abc1234") < prompt.index(
            "Latest review head SHA: def5678 (differs from local head)"
        )
        assert prompt.index(f"Rerun this exact node first on the current head: {reproducer}") < prompt.index(
            "Latest review head SHA: def5678 (differs from local head)"
        )
        assert prompt.index(f"Rerun this exact node first on the current head: {reproducer}") < prompt.index(
            "Triggering review artifact: .spec-state/runs/example/review-result.json"
        )

