class TestValidateCodexExec:
    def test_passes_when_exec_available(self):
        run = orch.RunState(
            run_id="test-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        ok_result = subprocess.CompletedProcess(
            args=["codex", "exec", "--help"],
            returncode=0,
            stdout=(
                "Run Codex non-interactively\n"
                "      --json\n"
                "          Print events to stdout as JSONL\n"
                "      --output-schema <FILE>\n"
                "          Path to a JSON Schema file\n"
            ),
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=ok_result):
            assert orch._validate_codex_exec(run) is True
        assert run.last_error == ""

    def test_fails_when_exec_lacks_json_support(self):
        run = orch.RunState(
            run_id="test-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        help_result = subprocess.CompletedProcess(
            args=["codex", "exec", "--help"],
            returncode=0,
            stdout="Run Codex non-interactively",
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=help_result):
            assert orch._validate_codex_exec(run) is False
        assert "exec --json" in run.last_error

    def test_fails_when_exec_lacks_output_schema_support_for_local_review(self):
        run = orch.RunState(
            run_id="test-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        help_result = subprocess.CompletedProcess(
            args=["codex", "exec", "--help"],
            returncode=0,
            stdout=("Run Codex non-interactively\n      --json\n          Print events to stdout as JSONL\n"),
            stderr="",
        )
        with patch.object(orch, "run_subprocess", return_value=help_result):
            assert orch._validate_codex_exec(run, require_output_schema=True) is False
        assert "exec --output-schema" in run.last_error

    def test_fails_when_exec_not_supported(self):
        run = orch.RunState(
            run_id="test-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        fail_result = subprocess.CompletedProcess(
            args=["codex", "exec", "--help"],
            returncode=1,
            stdout="",
            stderr="unknown subcommand",
        )
        with patch.object(orch, "run_subprocess", return_value=fail_result):
            assert orch._validate_codex_exec(run) is False
        assert "does not support" in run.last_error
        assert "npm install" in run.last_error


class TestWriteSandboxConfig:
    @pytest.mark.parametrize(("agent", "config_name"), [("claude", ".claude"), ("codex", ".codex")])
    def test_refuses_agent_config_symlink(
        self,
        tmp_path: Path,
        agent: str,
        config_name: str,
    ) -> None:
        worktree = tmp_path / "worktree"
        external = tmp_path / "external"
        worktree.mkdir()
        external.mkdir()
        (worktree / config_name).symlink_to(external, target_is_directory=True)

        with pytest.raises(ValueError, match="non-directory path"):
            orch._write_sandbox_config(agent, worktree)

        assert list(external.iterdir()) == []

    def test_claude_writes_default_playwright_mcp_config(self, tmp_path: Path):
        # Create the Playwright cli.js so _default_claude_mcp_servers includes it
        playwright_cli = tmp_path / "frontend" / "node_modules" / "@playwright" / "mcp" / "cli.js"
        playwright_cli.parent.mkdir(parents=True)
        playwright_cli.write_text("// placeholder")

        orch._write_sandbox_config("claude", tmp_path)

        settings_path = tmp_path / ".claude" / "settings.local.json"
        mcp_path = tmp_path / ".claude" / "mcp-servers.json"

        assert settings_path.exists()
        assert mcp_path.exists()

        settings = json.loads(settings_path.read_text())
        assert settings["sandbox"]["failIfUnavailable"] is True
        assert "api.github.com" in settings["sandbox"]["network"]["allowedDomains"]
        assert "*.blob.core.windows.net" in settings["sandbox"]["network"]["allowedDomains"]
        assert "localhost" in settings["sandbox"]["network"]["allowedDomains"]
        assert "127.0.0.1" in settings["sandbox"]["network"]["allowedDomains"]

        payload = json.loads(mcp_path.read_text())
        playwright = payload["mcpServers"]["playwright"]
        assert playwright["command"] in {"node", shutil.which("node")}
        assert playwright["args"] == [
            str(tmp_path / "frontend" / "node_modules" / "@playwright" / "mcp" / "cli.js"),
            "--headless",
            "--browser",
            "chromium",
        ]

    def test_claude_container_mcp_config_uses_worker_paths(self, tmp_path: Path):
        playwright_cli = tmp_path / "frontend" / "node_modules" / "@playwright" / "mcp" / "cli.js"
        playwright_cli.parent.mkdir(parents=True)
        playwright_cli.write_text("// placeholder")
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            execution=replace(orch.SPEC_RUNTIME_CONFIG.execution, backend="container"),
        )

        with patch.object(orch, "SPEC_RUNTIME_CONFIG", config):
            orch._write_sandbox_config("claude", tmp_path)

        payload = json.loads((tmp_path / ".claude" / "mcp-servers.json").read_text())
        assert payload["mcpServers"]["playwright"]["args"] == [
            "/workspace/source/frontend/node_modules/@playwright/mcp/cli.js",
            "--headless",
            "--browser",
            "chromium",
        ]

    def test_codex_writes_workspace_config_without_playwright_mcp(self, tmp_path: Path):
        # MCP servers for Codex are delivered via `-c mcp_servers.<name>.*` CLI
        # overrides at launch (see CodexAgent.build_implement_command), not via
        # .codex/config.toml — so even with extra_mcp_servers provided, the
        # workspace config must remain MCP-free.
        orch._write_sandbox_config(
            "codex",
            tmp_path,
            extra_mcp_servers={"playwright": {"command": "node", "args": ["cli.js"]}},
        )

        config_text = (tmp_path / ".codex" / "config.toml").read_text()
        assert 'sandbox_mode = "workspace-write"' in config_text
        assert "[mcp_servers.playwright]" not in config_text
        assert "playwright-mcp" not in config_text
        assert "--headless" not in config_text
        assert "mcp_servers" not in config_text

    def test_fails_when_codex_not_installed(self):
        run = orch.RunState(
            run_id="test-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        with patch.object(
            orch,
            "run_subprocess",
            side_effect=FileNotFoundError("codex"),
        ):
            assert orch._validate_codex_exec(run) is False
        assert "not found" in run.last_error
        assert "npm install" in run.last_error


class TestCodexAgentMcpOverrides:
    """CodexAgent injects manifest MCP servers as `-c` CLI overrides."""

    def _agent(self):
        from spec_runtime.agent_adapter import CodexAgent

        return CodexAgent()

    def test_codex_build_implement_command_injects_mcp_overrides(self, tmp_path: Path):
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "playwright": {
                    "command": "node",
                    "args": ["/tmp/cli.js", "--headless"],
                },
            },
        )

        assert cmd[-1] == "do the work"
        expected = [
            "-c",
            'mcp_servers.playwright.command="node"',
            "-c",
            'mcp_servers.playwright.args=["/tmp/cli.js", "--headless"]',
            "-c",
            'mcp_servers.playwright.default_tools_approval_mode="approve"',
        ]
        prompt_idx = cmd.index("do the work")
        argv_before_prompt = cmd[:prompt_idx]
        # Confirm the override block appears as a contiguous group in argv
        for i in range(len(argv_before_prompt) - len(expected) + 1):
            if argv_before_prompt[i : i + len(expected)] == expected:
                break
        else:
            raise AssertionError(
                f"Expected MCP overrides {expected!r} before prompt; got {argv_before_prompt!r}"
            )

    def test_codex_build_implement_command_no_mcp_when_empty(self, tmp_path: Path):
        baseline = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
        )
        with_none = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers=None,
        )
        with_empty = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={},
        )
        assert baseline == with_none == with_empty
        assert not any(arg.startswith("mcp_servers.") for arg in baseline)

    def test_codex_build_implement_command_renders_sse_url_server(self, tmp_path: Path):
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "playwright": {
                    "type": "sse",
                    "url": "http://spec-playwright-mcp:3001/sse",
                },
            },
        )
        prompt_idx = cmd.index("do the work")
        argv_before_prompt = cmd[:prompt_idx]
        # URL field is rendered for non-stdio servers
        assert any(
            arg == 'mcp_servers.playwright.url="http://spec-playwright-mcp:3001/sse"'
            for arg in argv_before_prompt
        )
        # The approval mode override still applies
        assert any(
            arg == 'mcp_servers.playwright.default_tools_approval_mode="approve"'
            for arg in argv_before_prompt
        )
        # Codex's experimental rmcp client must be enabled so HTTP/SSE servers connect
        assert "experimental_use_rmcp_client=true" in argv_before_prompt
        # The non-Codex `type` field must not leak through (Codex's schema rejects it)
        assert not any(
            arg.startswith("mcp_servers.playwright.type=") for arg in argv_before_prompt
        )
        # No spurious command/args overrides for a URL-only server
        assert not any(
            arg.startswith("mcp_servers.playwright.command=") for arg in argv_before_prompt
        )

    def test_codex_build_implement_command_renders_sse_with_bearer_token(
        self, tmp_path: Path
    ):
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "remote": {
                    "url": "https://example.com/mcp",
                    "bearer_token_env_var": "REMOTE_TOKEN",
                },
            },
        )
        assert any(
            arg == 'mcp_servers.remote.bearer_token_env_var="REMOTE_TOKEN"'
            for arg in cmd
        )

    def test_codex_build_implement_command_url_only_skips_rmcp_when_no_url_servers(
        self, tmp_path: Path
    ):
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "playwright": {"command": "node", "args": ["cli.js"]},
            },
        )
        assert "experimental_use_rmcp_client=true" not in cmd

    def test_codex_build_implement_command_skips_server_without_command_or_url(
        self, tmp_path: Path, caplog
    ):
        import logging

        with caplog.at_level(logging.WARNING, logger="spec_runtime.agent_adapter"):
            cmd = self._agent().build_implement_command(
                prompt="do the work",
                worktree_path=tmp_path,
                state_dir=tmp_path / ".state",
                mcp_servers={
                    "broken": {"type": "sse"},
                },
            )
        assert not any(arg.startswith("mcp_servers.broken.") for arg in cmd)
        assert any("broken" in rec.message for rec in caplog.records)

    def test_codex_build_implement_command_escapes_toml_strings(self, tmp_path: Path):
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "tricky": {
                    "command": 'weird\\path"with"quotes',
                },
            },
        )
        command_overrides = [
            cmd[i + 1]
            for i, arg in enumerate(cmd)
            if arg == "-c" and i + 1 < len(cmd) and cmd[i + 1].startswith("mcp_servers.tricky.command=")
        ]
        assert command_overrides == [
            'mcp_servers.tricky.command="weird\\\\path\\"with\\"quotes"'
        ]

    def test_codex_build_implement_command_emits_env_table(self, tmp_path: Path):
        import tomllib

        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "playwright": {
                    "command": "node",
                    "env": {"FOO": "bar", "BAZ_QUX": "hello"},
                },
            },
        )
        env_overrides = [
            cmd[i + 1]
            for i, arg in enumerate(cmd)
            if arg == "-c" and i + 1 < len(cmd) and cmd[i + 1].startswith("mcp_servers.playwright.env=")
        ]
        assert len(env_overrides) == 1
        # The part after the '=' must parse as a TOML inline table
        _, value = env_overrides[0].split("=", 1)
        parsed = tomllib.loads(f"env = {value}")["env"]
        assert parsed == {"FOO": "bar", "BAZ_QUX": "hello"}

    def test_codex_build_implement_command_accepts_hyphenated_server_names(
        self, tmp_path: Path, caplog
    ):
        # Hyphens are valid in TOML bare keys and in Codex's `-c` dotted-key
        # parser, so `foo-bar` must flow through unquoted (quoting segments
        # inside `-c mcp_servers."foo-bar".command=...` causes Codex to
        # register the literal name `"foo-bar"` instead of `foo-bar`).
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_servers={
                "foo-bar": {"command": "node", "args": ["cli.js"]},
            },
        )
        command_overrides = [
            cmd[i + 1]
            for i, arg in enumerate(cmd)
            if arg == "-c"
            and i + 1 < len(cmd)
            and cmd[i + 1].startswith("mcp_servers.")
            and ".command=" in cmd[i + 1]
        ]
        assert command_overrides == ['mcp_servers.foo-bar.command="node"']

    def test_codex_build_implement_command_skips_non_bare_server_names(
        self, tmp_path: Path, caplog
    ):
        # Server names containing characters outside TOML's bare-key charset
        # (dots, whitespace, etc.) cannot be delivered via Codex `-c`
        # overrides — the dotted-key parser does not honor quoted segments.
        # The adapter must skip them with a warning rather than emit a broken
        # override that Codex would register under the wrong name.
        import logging

        with caplog.at_level(logging.WARNING, logger="spec_runtime.agent_adapter"):
            cmd = self._agent().build_implement_command(
                prompt="do the work",
                worktree_path=tmp_path,
                state_dir=tmp_path / ".state",
                mcp_servers={
                    "foo.bar baz": {"command": "node", "args": ["cli.js"]},
                    "playwright": {"command": "node"},
                },
            )
        assert not any(
            arg.startswith("mcp_servers.") and "foo" in arg for arg in cmd
        )
        assert any(
            arg == 'mcp_servers.playwright.command="node"' for arg in cmd
        )
        assert any("foo.bar baz" in rec.message for rec in caplog.records)

    def test_codex_build_implement_command_accepts_mcp_config_path(self, tmp_path: Path):
        # Codex ignores mcp_config_path (it uses `-c` overrides instead), but the
        # AgentAdapter protocol exposes the kwarg for all adapters, so CodexAgent
        # must accept it without raising.
        cmd = self._agent().build_implement_command(
            prompt="do the work",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_config_path=tmp_path / "mcp.json",
        )
        assert "mcp.json" not in " ".join(cmd)
        assert "--mcp-config" not in cmd

    def test_codex_build_authoring_command_accepts_mcp_config_path(self, tmp_path: Path):
        agent = self._agent()
        cmd = agent.build_authoring_command(
            prompt="authoring prompt",
            worktree_path=tmp_path,
            state_dir=tmp_path / ".state",
            mcp_config_path=tmp_path / "mcp.json",
        )
        assert "mcp.json" not in " ".join(cmd)
        assert "--mcp-config" not in cmd

    def test_build_agent_command_forwards_mcp_config_path_to_any_adapter(
        self, tmp_path: Path
    ):
        """Custom adapters receive ``mcp_config_path`` regardless of agent name.

        Regression guard for the removed ``adapter.name == "claude"`` gate in
        ``_build_agent_command``: adapters that conform to the published
        ``AgentAdapter`` protocol are entitled to both ``mcp_config_path`` and
        ``mcp_servers`` kwargs; the orchestrator must not silently drop either
        for non-built-in adapters.
        """
        from spec_runtime.agent_adapter import AgentCapabilities

        captured: dict[str, object] = {}

        class CustomAdapter:
            name = "custom-agent"
            capabilities = AgentCapabilities(
                name="custom-agent",
                supports_mcp=True,
            )

            def build_implement_command(self, **kw):
                captured.update(kw)
                return ["mock"]

        worktree = tmp_path / ".worktrees" / "feature"
        worktree.mkdir(parents=True)

        with patch.object(orch, "get_agent_adapter", return_value=CustomAdapter()):
            orch._build_agent_command(
                "custom-agent",
                worktree,
                spec_id="feature",
                spec_path="specs/feature.md",
                spec_revision="sha256:deadbeef",
                acceptance_checklist=[],
                verification_expectations=[],
                mcp_servers={"playwright": {"command": "node"}},
            )

        assert "mcp_config_path" in captured
        assert isinstance(captured["mcp_config_path"], Path)
        assert captured["mcp_servers"] == {"playwright": {"command": "node"}}

    def test_build_agent_command_tolerates_legacy_adapter_without_mcp_servers(
        self, tmp_path: Path
    ):
        """Legacy out-of-tree adapters that predate the ``mcp_servers`` param still work.

        The ``AgentAdapter`` extension point is documented (see README.md and
        AGENTS.md), so adapters written against the previous signature
        (``prompt/worktree_path/state_dir/stream_json/mcp_config_path``) must
        continue to function. ``_build_agent_command`` introspects the target
        method and omits ``mcp_servers`` for adapters that do not declare it,
        instead of blowing up with ``TypeError: got an unexpected keyword
        argument 'mcp_servers'`` on every implement run.
        """
        from spec_runtime.agent_adapter import AgentCapabilities

        captured: dict[str, object] = {}

        class LegacyAdapter:
            name = "legacy-agent"
            capabilities = AgentCapabilities(
                name="legacy-agent",
                supports_mcp=False,
            )

            def build_implement_command(
                self,
                *,
                prompt: str,
                worktree_path: Path,
                state_dir: Path,
                stream_json: bool = False,
                mcp_config_path: Path | None = None,
            ) -> list[str]:
                captured["prompt"] = prompt
                captured["worktree_path"] = worktree_path
                captured["state_dir"] = state_dir
                captured["stream_json"] = stream_json
                captured["mcp_config_path"] = mcp_config_path
                return ["mock"]

        worktree = tmp_path / ".worktrees" / "feature"
        worktree.mkdir(parents=True)

        with patch.object(orch, "get_agent_adapter", return_value=LegacyAdapter()):
            cmd = orch._build_agent_command(
                "legacy-agent",
                worktree,
                spec_id="feature",
                spec_path="specs/feature.md",
                spec_revision="sha256:deadbeef",
                acceptance_checklist=[],
                verification_expectations=[],
                mcp_servers={"playwright": {"command": "node"}},
            )

        assert cmd == ["mock"]
        assert "mcp_servers" not in captured
        assert isinstance(captured["mcp_config_path"], Path)


class TestAcceptanceChecklist:
    def test_extracts_items(self, repo: Path):
        result = orch._extract_acceptance_checklist(repo / "specs" / "my-feature.md")
        assert "First criterion" in result
        assert "Second criterion" in result

    def test_extracts_acceptance_checklist_items(self, repo: Path):
        items = orch._extract_acceptance_checklist_items(repo / "specs" / "my-feature.md")
        assert items == ["- [ ] First criterion", "- [ ] Second criterion"]

    def test_verification_expectations_fall_back_when_section_missing(self, repo: Path):
        expectations = orch._extract_verification_expectations(repo / "specs" / "my-feature.md")
        assert expectations == [
            "- run `make test` during implement",
            "- run `make lint` during implement",
            "- do not run `make e2e` during implement; orchestrator verify reruns it",
        ]

    def test_extracts_verification_expectations_when_section_present(self, tmp_path: Path):
        spec = tmp_path / "spec.md"
        spec.write_text(
            textwrap.dedent("""\
            ## Acceptance Criteria
            - [ ] First criterion

            ## Verification
            - run `make test`
            - run `make lint`
            1. inspect generated audit metadata
        """)
        )
        expectations = orch._extract_verification_expectations(spec)
        assert expectations == [
            "- run `make test`",
            "- run `make lint`",
            "1. inspect generated audit metadata",
        ]

    def test_acceptance_checklist_items_empty_when_no_checkboxes(self, tmp_path: Path):
        spec = tmp_path / "spec.md"
        spec.write_text("## Acceptance Criteria\nNarrative only.\n")
        assert orch._extract_acceptance_checklist_items(spec) == []

    def test_missing_file(self, tmp_path: Path):
        result = orch._extract_acceptance_checklist(tmp_path / "nope.md")
        assert "No checklist" in result


