class TestRequiredCheckLogSummaries:
    def test_fetch_required_check_log_summary_uses_job_link(self, repo: Path):
        sample_log = "\n".join(
            [
                "ci\tRun E2E tests\tRunning 21 tests using 1 worker",
                "ci\tRun E2E tests\tError: expect(locator).toBeVisible() failed",
                "ci\tRun E2E tests\tmake: *** [Makefile:88: e2e] Error 1",
            ]
        )

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            assert cmd == ["gh", "run", "view", "123", "--job", "456", "--log-failed"]
            return subprocess.CompletedProcess(cmd, 0, sample_log, "")

        with patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess):
            summary = orch._fetch_required_check_log_summary(
                repo,
                "https://github.com/org/repo/actions/runs/123/job/456",
            )

        assert "Error: expect(locator).toBeVisible() failed" in summary
        assert "make: *** [Makefile:88: e2e] Error 1" in summary

    def test_augment_required_checks_error_appends_summary(self, repo: Path):
        checks_error = "Required checks failing: ci (https://example.com/run/123/job/456)"
        with patch.object(
            orch,
            "_fetch_required_check_log_summary",
            return_value="Error: flaky mobile assertion",
        ):
            enriched = orch._augment_required_checks_error(repo, checks_error)

        assert "Required check log summary" in enriched
        assert "- ci: Error: flaky mobile assertion" in enriched


class TestMergeConflictRetry:
    """Test merge-conflict → implement retry in run_full_workflow."""

    def _make_run(self, repo: Path) -> orch.RunState:
        return orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_merge_conflict_triggers_implement_retry(self, repo: Path):
        run = self._make_run(repo)
        run.save(repo)

        call_counts = {"implement": 0, "verify": 0, "merge": 0}

        def mock_implement(r, root):
            call_counts["implement"] += 1
            return "passed"

        def mock_verify(r, root):
            call_counts["verify"] += 1
            return "passed"

        def mock_merge(r, root):
            call_counts["merge"] += 1
            if call_counts["merge"] <= 1:
                r.last_error = "gh pr merge failed: not mergeable"
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify
        handlers["merge"] = mock_merge

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                ),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "passed"
        assert call_counts["implement"] == 2  # initial + merge-conflict retry
        assert call_counts["verify"] == 2
        assert call_counts["merge"] == 2

    def test_review_merge_conflict_triggers_implement_retry(self, repo: Path):
        run = self._make_run(repo)
        run.save(repo)

        call_counts = {"implement": 0, "review": 0}

        def mock_implement(r, root):
            call_counts["implement"] += 1
            return "passed"

        def mock_review(r, root):
            call_counts["review"] += 1
            if call_counts["review"] <= 1:
                r.last_error = (
                    "PR for branch spec/my-feature is not mergeable "
                    "(mergeStateStatus=DIRTY). Resolve merge conflict and retry."
                )
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["review"] = mock_review

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                ),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "passed"
        assert call_counts["implement"] == 2
        assert call_counts["review"] == 2
        assert run.merge_conflict_error == ""

    def test_non_conflict_merge_failure_stops(self, repo: Path):
        run = self._make_run(repo)
        run.save(repo)

        def mock_merge(r, root):
            r.last_error = "gh auth failed: token expired"
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["merge"] = mock_merge

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                ),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "failed"

    def test_dirty_pr_with_clean_local_merge_does_not_retry_as_merge_conflict(self, repo: Path):
        run = self._make_run(repo)
        run.save(repo)

        call_counts = {"implement": 0, "review": 0}

        def mock_implement(r, root):
            call_counts["implement"] += 1
            return "passed"

        def mock_review(r, root):
            call_counts["review"] += 1
            r.last_error = (
                "PR for branch spec/my-feature is not mergeable "
                "(mergeStateStatus=DIRTY). Resolve merge conflict and retry."
            )
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["review"] = mock_review

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(status="noop"),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "failed"
        assert call_counts["implement"] == 1
        assert call_counts["review"] == 1
        assert "stale or remote-only" in run.last_error.lower()


class TestRetryFailurePackage:
    def test_stale_review_findings_are_labeled_stale(self, repo: Path):
        run = orch.RunState(
            run_id="retry-review-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        run.save(repo)
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)

        orch.ReviewResult(
            status="request_changes",
            summary="Old review findings",
            findings=[
                orch.ReviewFinding(
                    id="F-old",
                    title="Old finding",
                    severity="P2",
                    file="scripts/runtime_driver.py",
                    start_line=1,
                    end_line=1,
                    body="This may already be fixed.",
                )
            ],
            reviewed_head_sha="oldhead1234",
            reviewed_base_sha="base1234",
            source_check_url="https://example.com/check/stale",
        ).save(repo, run.run_id)

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_head_sha", return_value="newhead5678"),
        ):
            package = orch._build_retry_failure_package(run, repo)

        assert package.current_head_sha == "newhead5678"
        assert package.reviewed_head_sha == "oldhead1234"
        assert package.review_feedback_active is False
        assert package.stale_review_feedback is True
        assert package.review_findings_count == 1
        assert any("Stale review evidence" in part for part in package.summary_parts)


class TestNoProgressCircuitBreaker:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="no-progress-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_repeated_verify_failures_on_same_clean_head_block(self, repo: Path):
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            r.implement_head_sha_before = "a" * 40
            r.implement_head_sha_after = "a" * 40
            r.implement_has_new_commit = False
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "unchanged_tree"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            orch._record_gate_result(
                gate_file,
                r.spec_id,
                "test",
                "make test",
                1,
                stdout=failure_stdout,
                stderr="make[1]: *** [test] Error 1",
            )
            r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_no_progress_retry_threshold", return_value=2),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        assert result == "blocked"
        assert call_counts["implement"] == 3
        assert call_counts["verify"] == 3
        assert run.no_progress_retries == 2
        assert run.attempts == 2
        assert "No-progress circuit breaker triggered" in run.last_error

    def test_repeated_verify_failures_on_same_dirty_head_block(self, repo: Path):
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            r.implement_head_sha_before = "a" * 40
            r.implement_head_sha_after = "a" * 40
            r.implement_has_new_commit = False
            r.implement_staged_changes = True
            r.implement_unstaged_changes = True
            r.implement_tree_status = "staged_changes+unstaged_changes"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            orch._record_gate_result(
                gate_file,
                r.spec_id,
                "test",
                "make test",
                1,
                stdout=failure_stdout,
                stderr="make[1]: *** [test] Error 1",
            )
            r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_no_progress_retry_threshold", return_value=2),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        assert result == "blocked"
        assert call_counts["implement"] == 3
        assert call_counts["verify"] == 3
        assert run.no_progress_retries == 2
        assert run.attempts == 2
        assert "tree status: staged_changes+unstaged_changes" in run.last_error

    def test_real_code_change_resets_no_progress_counter(self, repo: Path):
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        heads = iter(
            [
                ("a" * 40, "a" * 40, False),
                ("a" * 40, "a" * 40, False),
                ("a" * 40, "b" * 40, True),
                ("b" * 40, "c" * 40, True),
            ]
        )
        failures = iter(
            [
                textwrap.dedent("""\
                    FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                    1 failed, 41 passed in 0.45s
                """),
                textwrap.dedent("""\
                    FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                    1 failed, 41 passed in 0.45s
                """),
                textwrap.dedent("""\
                    FAILED tests/test_api.py::test_beta - ValueError: bad
                    1 failed, 41 passed in 0.45s
                """),
            ]
        )

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            head_before, head_after, has_new_commit = next(heads)
            r.implement_head_sha_before = head_before
            r.implement_head_sha_after = head_after
            r.implement_has_new_commit = has_new_commit
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "new_commit" if has_new_commit else "unchanged_tree"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            if call_counts["verify"] <= 3:
                stdout = next(failures)
                orch._record_gate_result(
                    gate_file,
                    r.spec_id,
                    "test",
                    "make test",
                    1,
                    stdout=stdout,
                    stderr="make[1]: *** [test] Error 1",
                )
                r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
                return "failed"
