    def test_diagnostic_distinguishes_same_stdout_test_failures_on_same_head(self, repo: Path):
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)
        diagnostics = iter(
            [
                textwrap.dedent("""\
                    =================================== FAILURES ===================================
                    _________________________________ test_alpha __________________________________
                    tests/test_api.py:10: in test_alpha
                        assert value == 1
                    E   AssertionError: expected 1
                    =========================== short test summary info ============================
                    FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                    1 failed, 41 passed in 0.45s
                """),
                textwrap.dedent("""\
                    =================================== FAILURES ===================================
                    _________________________________ test_alpha __________________________________
                    tests/test_api.py:99: in test_alpha
                        assert value == 1
                    E   AssertionError: expected 1
                    =========================== short test summary info ============================
                    FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
                    1 failed, 41 passed in 0.45s
                """),
            ]
        )

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            r.implement_head_sha_before = "a" * 40
            r.implement_head_sha_after = "a" * 40
            r.implement_has_new_commit = False
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "unchanged_tree"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            if call_counts["verify"] <= 2:
                orch._record_gate_result(
                    gate_file,
                    r.spec_id,
                    "test",
                    "make test",
                    1,
                    stdout=failure_stdout,
                    stderr="make[1]: *** [test] Error 1",
                    diagnostic=next(diagnostics),
                )
                r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        # Threshold=3 so the same-test-node path (which increments counter)
        # does not trip the breaker during 2 failures. The test verifies that
        # different diagnostics produce different fingerprints.
        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_no_progress_retry_threshold", return_value=3),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        history = json.loads(gate_file.read_text())["gates"]["test"]["history"]
        assert result == "passed"
        assert call_counts["implement"] == 3
        assert call_counts["verify"] == 3
        assert history[0]["failure_fingerprint"] != history[1]["failure_fingerprint"]
        assert run.no_progress_retries == 0
        assert run.last_verify_failure_gate == ""

    def test_origin_master_merge_does_not_reset_no_progress_counter(self, repo: Path):
        """When the agent merges origin/master (new head) but the same tests
        keep failing, the circuit breaker should still trip."""
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        # Each implement creates a different head (simulating origin/master merges)
        # but the test failure is always the same.
        heads = iter(
            [
                ("a" * 40, "b" * 40, True),  # merge commit
                ("b" * 40, "c" * 40, True),  # another merge commit
                ("c" * 40, "d" * 40, True),  # another merge commit
            ]
        )
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_shares.py::test_create_share - assert 409 == 201
            1 failed, 41 passed in 0.45s
        """)

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            head_before, head_after, has_new_commit = next(heads)
            r.implement_head_sha_before = head_before
            r.implement_head_sha_after = head_after
            r.implement_has_new_commit = has_new_commit
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "new_commit"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            orch._record_gate_result(
                gate_file,
                r.spec_id,
                "test",
                "make test",
                1,
                stdout=failure_stdout,
                stderr="make[1]: *** [test] Error 1",
            )
            r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_no_progress_retry_threshold", return_value=2),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        assert result == "blocked"
        assert call_counts["implement"] == 3
        assert call_counts["verify"] == 3
        assert run.no_progress_retries == 2
        assert run.attempts == 2
        assert "No-progress circuit breaker triggered" in run.last_error
        # Head changed each time, so the message should reflect the new head
        assert "new head" in run.last_error

    def test_same_head_repeat_prepares_debugger_guided_retry_before_circuit_breaker(self, repo: Path):
        run = self._make_run()
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        pending_signatures: list[str] = []
        debugger_calls: list[str] = []
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            pending_signatures.append(r.pending_block_debugger_signature)
            r.implement_head_sha_before = "a" * 40
            r.implement_head_sha_after = "a" * 40
            r.implement_has_new_commit = False
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "unchanged_tree"
            orch.ImplementResult(status="passed", summary="done", attempt=r.attempts).save(repo, r.run_id)
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            if call_counts["verify"] <= 2:
                orch._record_gate_result(
                    gate_file,
                    r.spec_id,
                    "test",
                    "make test",
                    1,
                    stdout=failure_stdout,
                    stderr="make[1]: *** [test] Error 1",
                )
                r.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
                return "failed"
            return "passed"

        def mock_debugger(r, root, *, source_phase):
            del root
            debugger_calls.append(source_phase)
            r.pending_block_debugger_signature = "sig-guided"
            return orch.BlockDiagnosis(
                summary="The same test gate failed again on an unchanged head.",
                root_cause="The branch reported passed without changing the failing outcome.",
                confidence=0.92,
                category="no-progress",
                evidence=["gate-status.json"],
                next_best_action="Rerun the stored failing node first, then make a real code change.",
                requires_human_attention=False,
                needs_new_commit=True,
                blocker_signature="sig-guided",
            )

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(orch, "_maybe_run_block_debugger", side_effect=mock_debugger),
            patch.object(orch, "_no_progress_retry_threshold", return_value=5),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        assert result == "passed"
        assert call_counts["implement"] == 3
        assert call_counts["verify"] == 3
        assert debugger_calls == ["verify"]
        assert pending_signatures == ["", "", "sig-guided"]

    def test_same_head_repeat_requires_current_attempt_passed_implement_result(self, repo: Path):
        run = self._make_run()
        run.attempts = 1
        run.last_error = "Gate 'test' failed (exit 1). output: 1 failed, 41 passed in 0.45s"
        run.last_verify_failure_gate = "test"
        run.implement_head_sha_before = "a" * 40
        run.implement_head_sha_after = "a" * 40
        run.implement_has_new_commit = False
        run.implement_staged_changes = False
        run.implement_unstaged_changes = False
        run.implement_tree_status = "unchanged_tree"
