        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)
        for _ in range(2):
            orch._record_gate_result(
                gate_file,
                run.spec_id,
                "test",
                "make test",
                1,
                stdout=failure_stdout,
                stderr="make[1]: *** [test] Error 1",
            )

        # A prior passed implement attempt should not authorize a guided retry
        # for the current verify failure when no current-attempt implement ran.
        orch.ImplementResult(status="passed", summary="done", attempt=0).save(repo, run.run_id)

        with patch.object(orch, "_maybe_run_block_debugger") as mock_debugger:
            prepared = orch._maybe_prepare_debugger_guided_retry(run, repo)

        assert prepared is False
        mock_debugger.assert_not_called()

