class TestStaleMergeConflictErrorClearing:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="stale-mc-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_stale_merge_conflict_error_cleared_on_gate_failure(self, repo: Path):
        """A merge_conflict_error from a prior phase should not cause gate
        failures to be classified as merge_conflicts."""
        run = self._make_run()
        # Simulate a leftover merge_conflict_error from a previous phase
        run.merge_conflict_error = "not mergeable: conflicts in main.py"
        run.save(repo)
        gate_file = repo / ".spec-state" / "runs" / run.run_id / "gate-status.json"
        gate_file.parent.mkdir(parents=True, exist_ok=True)
        call_counts = {"implement": 0, "verify": 0}
        failure_stdout = textwrap.dedent("""\
            FAILED tests/test_api.py::test_alpha - AssertionError: expected 1
            1 failed, 41 passed in 0.45s
        """)

        def mock_implement(r, root):
            del root
            call_counts["implement"] += 1
            r.implement_head_sha_before = "a" * 40
            r.implement_head_sha_after = "b" * 40
            r.implement_has_new_commit = True
            r.implement_staged_changes = False
            r.implement_unstaged_changes = False
            r.implement_tree_status = "new_commit"
            return "passed"

        def mock_verify(r, root):
            del root
            call_counts["verify"] += 1
            if call_counts["verify"] <= 1:
                orch._record_gate_result(
                    gate_file,
                    r.spec_id,
                    "test",
                    "make test",
                    1,
                    stdout=failure_stdout,
                    stderr="make[1]: *** [test] Error 1",
                )
                r.last_error = "Gate 'test' failed (exit 1). output: 1 failed"
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["verify"] = mock_verify

        with patch.dict(orch.PHASE_HANDLERS, handlers):
            result = orch.run_full_workflow(run, repo, retry_cap=10)

        assert result == "passed"
        # The stale merge_conflict_error should have been cleared
        assert run.merge_conflict_error == ""
        # Retry should have been classified as verify_failures, not merge_conflicts
        assert run.verify_failures == 1
        assert run.merge_conflicts == 0


class TestRunFullWorkflowRetryHandling:
    def _make_run(self, repo: Path) -> orch.RunState:
        del repo
        return orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    def test_retry_cap_applies_across_verify_and_merge(self, repo: Path):
        run = self._make_run(repo)
        run.attempts = orch.RETRY_CAP  # Already at cap
        run.save(repo)

        def mock_merge(r, root):
            r.last_error = "gh pr merge failed: not mergeable"
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["merge"] = mock_merge

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            # Keep the retry-cap escalation path off the network: without this
            # the summary emitter shells out to real `gh pr list`, which hangs
            # under sandboxed CI and makes this test flaky/slow. With no PR
            # found the production code takes the same code path (pr_number=None).
            patch.object(orch, "_find_pr_for_branch", return_value=None),
            # Reaching the retry cap routes through
            # `_transition_to_blocked_with_debugger`, which spawns the real
            # blocked-run debugger agent in a temporary worktree. In a repo
            # where `origin/main` resolves (the orchestrator's own verify run)
            # that subprocess launches and hangs on the sandboxed network for
            # 20s+; stub it so the test exercises only the retry-cap logic.
            patch.object(orch, "_maybe_run_block_debugger", return_value=None),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                ),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        # Should not retry — cap already reached
        assert result == "blocked"

    def test_merge_conflict_clears_after_verify_passes(self, repo: Path):
        run = self._make_run(repo)
        run.save(repo)

        merge_calls = {"count": 0}

        def mock_merge(r, root):
            merge_calls["count"] += 1
            if merge_calls["count"] <= 1:
                r.last_error = "gh pr merge failed: not mergeable"
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["merge"] = mock_merge

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            patch.object(
                orch,
                "_check_local_mergeability_against_origin_master",
                return_value=orch.MergeOriginMasterResult(
                    status="conflict",
                    stderr="CONFLICT (content): Merge conflict in file.py",
                ),
            ),
        ):
            result = orch.run_full_workflow(run, repo)

        assert result == "passed"
        # merge_conflict_error should be cleared after verify passes
        assert run.merge_conflict_error == ""

    def test_required_checks_failure_triggers_implement_retry(self, repo: Path):
        run = self._make_run(repo)
