    def test_local_review_stale_after_merge_sync_blocks_at_retry_cap(self, repo: Path):
        """When local review keeps going stale after merge sync, the workflow
        should escalate to blocked once the retry budget is exhausted."""
        run = self._make_run(repo)
        run.attempts = 2  # Already at retry cap
        run.save(repo)

        def mock_merge(r, root):
            del root
            r.last_error = (
                "Local review must rerun after syncing with origin/main: "
                "review status approved covered abc1234, but the branch now points to def5678."
            )
            return "failed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["merge"] = mock_merge

        with (
            patch.dict(orch.PHASE_HANDLERS, handlers),
            # Keep the retry-cap escalation path off the network (see the
            # companion test above): otherwise the summary emitter shells out
            # to real `gh pr list`, which hangs under sandboxed CI.
            patch.object(orch, "_find_pr_for_branch", return_value=None),
            # The blocked transition also spawns the real block-debugger agent
            # subprocess when `origin/main` resolves; stub it so this test stays
            # off the network (see the companion test above).
            patch.object(orch, "_maybe_run_block_debugger", return_value=None),
        ):
            result = orch.run_full_workflow(run, repo, retry_cap=2)

        assert result == "blocked"
        assert run.attempts == 2  # Budget was not consumed further

    def test_base_branch_policy_race_retries_merge_not_implement(self, repo: Path):
        """When gh pr merge fails with 'base branch policy' (race after checks
        polled green), the orchestrator should retry merge directly instead of
        looping back to implement."""
        run = self._make_run(repo)
        run.save(repo)

        call_counts = {"implement": 0, "merge": 0}

        def mock_implement(r, root):
            call_counts["implement"] += 1
            return "passed"

        def mock_merge(r, root):
            call_counts["merge"] += 1
            if call_counts["merge"] == 1:
                r.last_error = (
                    "gh pr merge failed: X Pull request org/repo#1 is not "
                    "mergeable: the base branch policy prohibits the merge."
                )
                return "failed"
            return "passed"

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = mock_implement
        handlers["merge"] = mock_merge

        with patch.dict(orch.PHASE_HANDLERS, handlers):
            result = orch.run_full_workflow(run, repo)

        assert result == "passed"
        assert run.attempts == 0
        # implement should only run once (initial), not retried
        assert call_counts["implement"] == 1
        # merge should run twice (fail + retry)
        assert call_counts["merge"] == 2

    def test_base_branch_policy_race_stops_after_retry_cap(self, repo: Path):
        """Persistent branch-policy failures should stop after a bounded retry count."""
        run = self._make_run(repo)
        run.save(repo)

        call_counts = {"implement": 0, "merge": 0}

        def mock_implement(r, root):
            call_counts["implement"] += 1
