class TestWorkflowFailurePolicy:
    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="policy-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )

    @pytest.mark.parametrize(
        ("phase", "configure", "expected"),
        [
            (
                "implement",
                lambda run: setattr(run, "last_error", "Agent exited with code 1 (no_handshake)."),
                ("implement_failures", "implement", False, False, False),
            ),
            (
                "verify",
                lambda run: setattr(run, "last_error", "Gate 'test' failed (exit 1). output: 1 failed"),
                ("verify_failures", "implement", False, False, True),
            ),
            (
                "review",
                lambda run: (
                    setattr(run, "review_decision_status", "request_changes"),
                    setattr(run, "last_error", "review requested changes"),
                ),
                ("review_changes", "implement", False, False, False),
            ),
            (
                "merge",
                lambda run: setattr(
                    run,
                    "last_error",
                    "Local review must rerun after syncing with origin/main: reviewed abc123 but branch now points to def456.",
                ),
                ("verify_failures", "verify", False, False, False),
            ),
            (
                "merge",
                lambda run: setattr(
                    run,
                    "last_error",
                    "gh pr merge failed: GraphQL: Base branch was modified. Review and try the merge again. (mergePullRequest)",
                ),
                ("", "merge", False, True, False),
            ),
            (
                "merge",
                lambda run: setattr(run, "last_error", "Failed to mark PR #12 as ready"),
                ("", "merge", False, True, False),
            ),
        ],
    )
    def test_classifies_transition_matrix(self, phase: str, configure, expected: tuple[str, str, bool, bool, bool]):
        run = self._make_run()
        configure(run)

        policy = orch._workflow_failure_policy(run, phase)

        assert policy is not None
        assert (
            policy.retry_reason,
            policy.next_phase,
            policy.confirm_merge_conflict,
            policy.direct_phase_retry,
            policy.publish_retry_cap_draft,
        ) == expected

    def test_apply_verify_failure_policy_restarts_implement(self, repo: Path):
        run = self._make_run()
        run.last_error = "Gate 'lint' failed (exit 1). output: lint failed"
        policy = orch._workflow_failure_policy(run, "verify")
        assert policy is not None

        with patch.object(orch, "_maybe_trip_no_progress_circuit_breaker", return_value=None):
            terminal_status, phase_idx, merge_race_retries = orch._apply_workflow_failure_policy(
                run,
                repo,
                phase="verify",
                phase_order=list(orch.PHASES),
                current_retry_cap=3,
                merge_race_retries=0,
                policy=policy,
            )

        assert terminal_status is None
        assert phase_idx == list(orch.PHASES).index("implement")
        assert merge_race_retries == 0
        assert run.attempts == 1
        assert run.verify_failures == 1

    def _agent_error_run(
        self, *, committed: bool, dirty: bool = False, agent_reported: bool = True
    ) -> orch.RunState:
        run = self._make_run()
        run.last_error = (
            "Implemented and committed the contract; make test fails on 3 unrelated "
            "existing frontend currency-format assertions."
        )
        run.implement_agent_reported_failure = agent_reported
        run.implement_has_new_commit = committed
        run.implement_staged_changes = dirty
        run.implement_unstaged_changes = False
        return run

    def test_agent_reported_failure_on_a_clean_commit_retries(self):
        # An agent's `error` used to end the run at attempt 0 while every
        # neighbouring outcome had a path. Observed in production: a clean
        # commit, two environment-only assertion failures, and a run dead with
        # no retry spent.
        run = self._agent_error_run(committed=True)

        policy = orch._workflow_failure_policy(run, "implement")

        assert policy is not None
        assert policy.retry_reason == "implement_failures"
        assert policy.next_phase == "implement"

    def test_agent_reported_failure_without_a_commit_is_still_terminal(self):
        assert orch._workflow_failure_policy(self._agent_error_run(committed=False), "implement") is None

    def test_agent_reported_failure_with_a_dirty_tree_is_still_terminal(self):
        run = self._agent_error_run(committed=True, dirty=True)

        assert orch._workflow_failure_policy(run, "implement") is None

    def test_stale_clean_commit_state_does_not_make_a_prelaunch_failure_retryable(self):
        # phase_implement returns early on several prelaunch
        # failures, some deliberately non-retryable, before the implement_* commit
        # fields are reset. Judging those on the previous attempt's clean commit
        # would spend retry budget instead of surfacing the operator issue.
        run = self._agent_error_run(committed=True, agent_reported=False)
        run.last_error = (
            "Review-triggered implement retry could not position the workspace at the reviewed head."
        )

        assert orch._workflow_failure_policy(run, "implement") is None

    def test_implement_phase_clears_the_agent_report_flag_before_early_returns(self, tmp_path: Path):
        run = self._agent_error_run(committed=True)
        run.worktree_path = str(tmp_path / "definitely-missing")

        assert orch.phase_implement(run, tmp_path) == "failed"
        assert run.implement_agent_reported_failure is False
        assert orch._workflow_failure_policy(run, "implement") is None

    def test_clean_commit_retry_does_not_override_agent_auth(self):
        # Credentials are an operator problem in every phase; a clean commit must
        # not start spending retry budget on a 401.
        run = self._agent_error_run(committed=True)
        run.last_error = (
            "Agent CLI is not authenticated in this execution environment (no_handshake). "
            "Not logged in. Please run /login."
        )

        assert orch._workflow_failure_policy(run, "implement") is None

    def test_agent_auth_no_handshake_is_not_retryable(self):
        run = self._make_run()
        run.last_error = "Agent CLI is not authenticated in this execution environment (no_handshake). Not logged in. Please run /login."

        metadata = orch._classify_phase_result(run, "implement", "failed")

        assert metadata["failure_subtype"] == "agent_auth_missing"
        assert metadata["retryable"] is False
        assert orch._workflow_failure_policy(run, "implement") is None

    def test_agent_auth_detects_current_claude_401_phrasing(self):
        # This exact stream line once burned a full retry cap because
        # it matched no auth marker and carries no agent marker of its own.
        assert (
            orch._is_agent_auth_failure_message(
                "Failed to authenticate. API Error: 401 Invalid authentication credentials"
            )
            is True
        )
        run = self._make_run()
        run.last_error = (
            "Agent CLI is not authenticated in this execution environment "
            "(no_handshake). Last agent output: Failed to authenticate. "
            "API Error: 401 Invalid authentication credentials"
        )
        metadata = orch._classify_phase_result(run, "implement", "failed")
        assert metadata["failure_subtype"] == "agent_auth_missing"
        assert metadata["retryable"] is False

    def test_agent_auth_ignores_generic_401_without_auth_phrase(self):
        assert orch._is_agent_auth_failure_message("HTTP 401 from example.com") is False
        assert orch._is_agent_auth_failure_message("") is False

    def test_agent_capacity_parses_advertised_reset_window(self):
        message = "You've hit your session limit · resets 8:30pm (America/Los_Angeles)"

        delay = orch._agent_capacity_retry_delay_seconds(
            message,
            now=datetime(2026, 8, 18, 3, 22, tzinfo=timezone.utc),
        )

        assert delay == 485

    def test_agent_capacity_without_reset_uses_bounded_fallback(self):
        assert (
            orch._agent_capacity_retry_delay_seconds("You have hit your session limit")
            == orch.AGENT_CAPACITY_DEFAULT_BACKOFF_SECONDS
        )
        assert orch._agent_capacity_retry_delay_seconds("HTTP 429 from example.com") is None

    def test_agent_capacity_has_distinct_retryable_classification(self):
        run = self._make_run()
        run.last_error = (
            "Agent provider capacity window is exhausted (provider_capacity, no_handshake). "
            "Last agent output: You've hit your session limit · resets 8:30pm "
            "(America/Los_Angeles)"
        )

        metadata = orch._classify_phase_result(run, "implement", "failed")

        assert metadata["failure_subtype"] == "provider_capacity"
        assert metadata["retryable"] is True

    def test_forge_auth_failure_blocks_in_any_phase(self):
        # A gh auth outage during review must not burn multiple attempts and
        # stranded the run for 30h. It must classify non-retryable everywhere.
        message = "GitHub CLI not authenticated. Run 'gh auth login'."
        assert orch._is_forge_auth_failure_message(message) is True
        for phase in ("review", "publish", "merge"):
            run = self._make_run()
            run.last_error = message
            metadata = orch._classify_phase_result(run, phase, "failed")
            assert metadata["failure_subtype"] == "forge_auth_missing", phase
            assert metadata["retryable"] is False, phase
            assert orch._workflow_failure_policy(run, phase) is None, phase

    def test_forge_auth_predicate_ignores_unrelated_errors(self):
        assert orch._is_forge_auth_failure_message("git push failed: rejected") is False
        assert orch._is_forge_auth_failure_message("") is False

    def test_pending_operator_readiness_blocker_does_not_retry_implement(self):
        run = self._make_run()
        run.last_error = "Readiness promotion refused for deadbee: pending operator request: agent_question"

        policy = orch._workflow_failure_policy(run, "merge")

        assert policy is None


def _merge_ready_run(run: orch.RunState, head_sha: str = "deadbeef1234567") -> orch.RunState:
    run.verify_passed_once = True
    run.verify_head_sha = head_sha
    run.review_expected_head_sha = head_sha
    run.review_decision_status = "approved"
    return run


class TestMergeCompletionFence:
    """Tests for the merge-phase completion fence (spec: merge-time-completion-fence)."""

    def _make_run(self) -> orch.RunState:
        return _merge_ready_run(orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--abcd1234",
        ))

    def _publish_completion_tag(self, repo: Path, spec_id: str) -> None:
        _create_annotated_merge_tag(cwd=repo, spec_id=spec_id)
        _run_git(
            "push",
            "origin",
            f"refs/tags/{merge_tags.merge_tag_name(spec_id)}",
            cwd=repo,
        )

    def test_open_pr_not_merged_when_completion_tag_already_reachable(
        self,
        repo: Path,
    ):
        run = self._make_run()
        run.save(repo)
        self._publish_completion_tag(repo, run.spec_id)
        assert spec_status.is_spec_merged(repo, run.spec_id)

        auth_ok = subprocess.CompletedProcess(
            args=["gh", "auth", "status"],
            returncode=0,
            stdout="ok",
            stderr="",
        )
        find_pr_mock = MagicMock(
            return_value={
                "number": 12,
                "state": "OPEN",
                "headRefOid": "deadbeef1234567",
                "baseRefOid": "base1234",
            },
        )
        auto_merge_mock = MagicMock(return_value="merged")
        manual_merge_mock = MagicMock(return_value="passed")

        with (
            patch.object(orch, "run_subprocess", return_value=auth_ok),
            patch.object(orch, "_find_pr_for_branch", find_pr_mock),
            patch.object(orch, "_try_auto_merge", auto_merge_mock),
            patch.object(orch, "_manual_merge", manual_merge_mock),
        ):
            result = orch.phase_merge(run, repo)

        assert result == "passed"
        assert run.last_error == ""
        assert find_pr_mock.call_count == 0
        assert auto_merge_mock.call_count == 0
        assert manual_merge_mock.call_count == 0
        fence_warnings = [
            warning
            for warning in run.nonfatal_warnings
            if warning.get("failure_subtype") == "superseded_by_completed_spec"
        ]
        assert len(fence_warnings) == 1
