    def test_refresh_advances_remote_tracking_base_ref(self, repo: Path):
        """The fence must update refs/remotes/origin/master, not just FETCH_HEAD.

        Otherwise, when another machine pushes spec/merged/<id> on top of an
        advanced master, this worktree's stale origin/master can leave the
        completion tag unreachable from the base ref and the fence will not
        trip.
        """
        spec_id = "fence-refresh-target"
        # Capture the worktree's view of origin/master before the new commit.
        before_sha = _run_git_stdout("rev-parse", "origin/master", cwd=repo).strip()

        # Simulate another machine: clone the bare remote, push a new master
        # commit plus the spec/merged tag pointing at it, then have the fence
        # refresh this worktree.
        remote_path = (repo.parent / "remote.git").resolve()
        other = repo.parent / "other-clone"
        subprocess.run(
            ["git", "clone", "--branch", "master", str(remote_path), str(other)],
            check=True,
            capture_output=True,
        )
        _run_git("config", "user.email", "other@test.com", cwd=other)
        _run_git("config", "user.name", "Other", cwd=other)
        (other / "advance.txt").write_text("advance master from another machine\n")
        _run_git("add", "advance.txt", cwd=other)
        _run_git("commit", "-m", "advance master remotely", cwd=other)
        _run_git("push", "origin", "HEAD:refs/heads/master", cwd=other)
        _create_annotated_merge_tag(cwd=other, spec_id=spec_id)
        _run_git(
            "push",
            "origin",
            f"refs/tags/{merge_tags.merge_tag_name(spec_id)}",
            cwd=other,
        )

        # Local view is still stale before the fence runs.
        local_origin_before = _run_git_stdout(
            "rev-parse",
            "origin/master",
            cwd=repo,
        ).strip()
        assert local_origin_before == before_sha
        assert not spec_status.is_spec_merged(repo, spec_id)

        action, error, fenced_ref = spec_status.refresh_merge_completion_state(repo)
        assert action == "" and error == "", (action, error)
        assert fenced_ref == "refs/remotes/origin/master"

        # origin/master must now point at the new remote tip, otherwise
        # the merged tag would still not be reachable from base_ref.
        local_origin_after = _run_git_stdout(
            "rev-parse",
            "origin/master",
            cwd=repo,
        ).strip()
        remote_master = _run_git_stdout(
            "rev-parse",
            "master",
            cwd=other,
        ).strip()
        assert local_origin_after == remote_master
        assert local_origin_after != before_sha
        # And the completion tag must now be reachable, so the fence will trip.
        assert spec_status.is_spec_merged(repo, spec_id)

    def test_refresh_fails_closed_on_fetch_timeout(self, repo: Path):
        """A hung remote fetch must fail closed instead of blocking the merge."""

        def _raise_timeout(*args, **kwargs):
            raise subprocess.TimeoutExpired(cmd=args[0], timeout=kwargs.get("timeout", 0))

        with patch.object(spec_status.subprocess, "run", side_effect=_raise_timeout):
            action, error, fenced_ref = spec_status.refresh_merge_completion_state(
                repo,
                timeout=0.01,
            )

        assert "fetch origin" in action
        assert "+refs/heads/master:refs/remotes/origin/master" in action
        assert "timed out" in error.lower()
        assert fenced_ref == "refs/remotes/origin/master"

    def test_unqualified_base_ref_checks_refreshed_remote_tracking_ref(
        self,
        repo: Path,
    ):
        """With an unqualified base_ref like ``master`` the fence must consult
        the freshly fetched ``refs/remotes/origin/master``, not the stale local
        ``master`` branch — otherwise a tag pushed by another machine on top of
        an advanced master is unreachable from the local branch and the fence
        silently no-ops.
        """
        spec_id = "fence-unqualified-base"

        # Another machine advances master and publishes the completion tag.
        remote_path = (repo.parent / "remote.git").resolve()
        other = repo.parent / "other-clone-unqualified"
        subprocess.run(
            ["git", "clone", "--branch", "master", str(remote_path), str(other)],
            check=True,
            capture_output=True,
        )
        _run_git("config", "user.email", "other@test.com", cwd=other)
        _run_git("config", "user.name", "Other", cwd=other)
        (other / "advance-unqualified.txt").write_text("advance master\n")
        _run_git("add", "advance-unqualified.txt", cwd=other)
        _run_git("commit", "-m", "advance master remotely (unqualified)", cwd=other)
        _run_git("push", "origin", "HEAD:refs/heads/master", cwd=other)
        _create_annotated_merge_tag(cwd=other, spec_id=spec_id)
        _run_git(
            "push",
            "origin",
            f"refs/tags/{merge_tags.merge_tag_name(spec_id)}",
            cwd=other,
        )

        # Simulate a config where base_ref is the unqualified "master".
        # Before refresh, neither origin/master nor a stale local "master"
        # know about the new tag.
        assert not spec_status.is_spec_merged(repo, spec_id, base_ref="master")
        assert not spec_status.is_spec_merged(
            repo, spec_id, base_ref="refs/remotes/origin/master"
        )

        action, error, fenced_ref = spec_status.refresh_merge_completion_state(
            repo,
            base_ref="master",
        )
        assert action == "" and error == "", (action, error)
        # The fence must direct callers at refs/remotes/origin/master, not
        # the stale local master branch.
        assert fenced_ref == "refs/remotes/origin/master"
        assert spec_status.is_spec_merged(repo, spec_id, base_ref=fenced_ref)
        # And fence_base_ref agrees with what refresh returned.
        assert spec_status.fence_base_ref("master") == fenced_ref


