class TestMergeRetryOnBranchPolicy:
    """Tests for the merge retry loop when base-branch-policy errors occur."""

    def _make_run(self) -> orch.RunState:
        return _merge_ready_run(orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        ))

    def test_phase_merge_retries_on_base_branch_policy(self, repo: Path):
        """Transient base-branch-policy failure followed by success (manual path)."""
        run = self._make_run()
        run.save(repo)

        pr_data = {
            "number": 12,
            "state": "OPEN",
            "headRefOid": "deadbeef1234567",
            "baseRefOid": "base1234",
        }

        merge_attempt = 0

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            nonlocal merge_attempt
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                assert "--squash" in cmd
                assert "--auto" in cmd
                merge_attempt += 1
                if merge_attempt == 1:
                    return subprocess.CompletedProcess(cmd, 1, "", "Base branch policy error: checks not passing")
                return subprocess.CompletedProcess(cmd, 0, "merged", "")
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "worktree", "prune"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "tag", "--list"]:
                return subprocess.CompletedProcess(cmd, 0, f"spec/merged/{run.spec_id}\n", "")
            if cmd[:4] == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:4] == ["git", "symbolic-ref", "--short", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 0, "master\n", "")
            if cmd[:4] == ["git", "merge", "--ff-only", "origin/master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_data),
            patch.object(orch, "_try_auto_merge", return_value="unavailable"),
            patch.object(orch, "_required_checks_green", return_value=(True, "")),
            patch.object(
                orch,
                "_wait_for_pr_merged",
                return_value=(True, ""),
            ) as wait_mock,
            patch.object(orch, "run_or_fail", return_value=True),
            patch.object(orch, "_poll_sleep") as sleep_mock,
        ):
            result = orch.phase_merge(run, repo)

        assert result == "passed"
        assert merge_attempt == 2
        wait_mock.assert_called_once_with(repo, run.branch, 12)
        sleep_mock.assert_any_call(orch.MERGE_CHECKS_POLL_INTERVAL_SECONDS)

    def test_phase_merge_fails_after_repeated_branch_policy(self, repo: Path):
        """Repeated base-branch-policy failures exhaust retries and return failed (manual path)."""
        run = self._make_run()
        run.save(repo)

        pr_data = {
            "number": 12,
            "state": "OPEN",
            "headRefOid": "deadbeef1234567",
            "baseRefOid": "base1234",
        }

        merge_attempts = 0

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            nonlocal merge_attempts
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                assert "--squash" in cmd
                assert "--auto" in cmd
                merge_attempts += 1
                return subprocess.CompletedProcess(cmd, 1, "", "Base branch policy error: checks not passing")
            raise AssertionError(f"Unexpected command: {cmd}")

        clock = _FakeMergeClock()
        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_data),
            patch.object(orch, "_required_checks_green", return_value=(True, "")),
            patch.object(orch.time, "time", side_effect=clock.time),
            patch.object(orch, "_poll_sleep", side_effect=clock.sleep) as sleep_mock,
        ):
            result = orch.phase_merge(run, repo)

        expected_retries = max(
            3,
            orch.MERGE_CHECKS_TIMEOUT_SECONDS // max(1, orch.MERGE_CHECKS_POLL_INTERVAL_SECONDS),
        )
        assert result == "failed"
        assert merge_attempts == expected_retries
        # Sleep should be called between retries (not after the last one)
        assert sleep_mock.call_count == expected_retries - 1
        assert "gh pr merge failed" in run.last_error
        assert "Base branch policy" in run.last_error

    def test_phase_merge_fails_fast_when_checks_fail_after_policy_block(self, repo: Path):
        """Explicit failing required checks should stop policy retries immediately."""
        run = self._make_run()
        run.save(repo)

        pr_data = {
            "number": 12,
            "state": "OPEN",
            "headRefOid": "deadbeef1234567",
            "baseRefOid": "base1234",
        }

        merge_attempts = 0

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            nonlocal merge_attempts
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                merge_attempts += 1
                return subprocess.CompletedProcess(cmd, 1, "", "Base branch policy error: checks not passing")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_data),
            patch.object(orch, "_try_auto_merge", return_value="unavailable"),
            patch.object(
                orch,
                "_required_checks_green",
                side_effect=[
                    (True, ""),
                    (True, ""),
                    (False, "Required checks failing: ci / ci"),
                ],
            ),
            patch.object(
                orch,
                "_augment_required_checks_error",
                return_value="Required checks failing: ci / ci",
            ) as augment_mock,
            patch.object(orch.time, "time", side_effect=_FakeMergeClock().time),
            patch.object(orch, "_poll_sleep") as sleep_mock,
        ):
            result = orch.phase_merge(run, repo)

        assert result == "failed"
        assert merge_attempts == 1
        augment_mock.assert_called_once()
        sleep_mock.assert_not_called()
        assert "Merge refused" in run.last_error

    def test_phase_merge_retries_on_base_branch_modified(self, repo: Path):
        run = self._make_run()
        run.save(repo)

        pr_data = {
            "number": 12,
            "state": "OPEN",
            "headRefOid": "deadbeef1234567",
            "baseRefOid": "base1234",
        }

        merge_attempt = 0

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            nonlocal merge_attempt
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                assert "--squash" in cmd
                assert "--auto" in cmd
                merge_attempt += 1
                if merge_attempt == 1:
                    return subprocess.CompletedProcess(
                        cmd,
                        1,
                        "",
                        "GraphQL: Base branch was modified. Review and try the merge again. (mergePullRequest)",
                    )
                return subprocess.CompletedProcess(cmd, 0, "merged", "")
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "worktree", "prune"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "tag", "--list"]:
                return subprocess.CompletedProcess(cmd, 0, f"spec/merged/{run.spec_id}\n", "")
            if cmd[:4] == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:4] == ["git", "symbolic-ref", "--short", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 0, "master\n", "")
            if cmd[:4] == ["git", "merge", "--ff-only", "origin/master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_data),
            patch.object(orch, "_try_auto_merge", return_value="unavailable"),
            patch.object(orch, "_required_checks_green", return_value=(True, "")),
            patch.object(
                orch,
                "_wait_for_pr_merged",
                return_value=(True, ""),
            ) as wait_mock,
            patch.object(orch, "run_or_fail", return_value=True),
            patch.object(orch, "_poll_sleep") as sleep_mock,
        ):
            result = orch.phase_merge(run, repo)

        assert result == "passed"
        assert merge_attempt == 2
        wait_mock.assert_called_once_with(repo, run.branch, 12)
        assert sleep_mock.call_count == 1


