class TestPostMergeSync:
    """Tests for post-merge local master sync in phase_merge."""

    def _make_run(self) -> orch.RunState:
        return orch.RunState(
            run_id="test-spec-20260101T000000",
            spec_id="test-spec",
            branch="code/test-spec--20260101T000000",
            agent="codex",
        )

    def test_merge_syncs_local_master_when_not_on_master(self, repo: Path):
        """When HEAD is not master, update-ref is used and no warning is recorded."""
        run = self._make_run()
        run.save(repo)

        update_ref_called = False

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            nonlocal update_ref_called
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                return subprocess.CompletedProcess(cmd, 0, "merged", "")
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "worktree", "prune"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "tag", "--list"]:
                return subprocess.CompletedProcess(cmd, 0, f"spec/merged/{run.spec_id}\n", "")
            if cmd[:4] == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:4] == ["git", "symbolic-ref", "--short", "HEAD"]:
                # Not on master
                return subprocess.CompletedProcess(cmd, 0, "some-other-branch\n", "")
            if cmd[:2] == ["git", "update-ref"]:
                update_ref_called = True
                assert cmd[2:] == ["refs/heads/master", "origin/master"]
                return subprocess.CompletedProcess(cmd, 0, "", "")
            raise AssertionError(f"Unexpected command: {cmd}")

        pr_merged = {
            "number": 12,
            "state": "MERGED",
            "headRefOid": "deadbeef1234567",
        }

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_merged),
            patch.object(orch, "run_or_fail", return_value=True),
        ):
            result = orch.phase_merge(run, repo)

        assert result == "passed"
        assert update_ref_called
        assert run.nonfatal_warnings == []

    def test_merge_continues_when_branch_update_fails(self, repo: Path):
        """If update-ref fails, merge still passes and a non-fatal warning is recorded."""
        run = self._make_run()
        run.save(repo)

        def mock_run_subprocess(cmd, **kwargs):  # noqa: ARG001
            if cmd[:3] == ["gh", "auth", "status"]:
                return subprocess.CompletedProcess(cmd, 0, "ok", "")
            if cmd[:3] == ["gh", "pr", "merge"]:
                return subprocess.CompletedProcess(cmd, 0, "merged", "")
            if cmd[:3] == ["git", "worktree", "list"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "worktree", "prune"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:3] == ["git", "tag", "--list"]:
                return subprocess.CompletedProcess(cmd, 0, f"spec/merged/{run.spec_id}\n", "")
            if cmd[:4] == ["git", "fetch", "origin", "master"]:
                return subprocess.CompletedProcess(cmd, 0, "", "")
            if cmd[:4] == ["git", "symbolic-ref", "--short", "HEAD"]:
                return subprocess.CompletedProcess(cmd, 0, "some-other-branch\n", "")
            if cmd[:2] == ["git", "update-ref"]:
                # Simulate failure: e.g. ref locked or invalid new value
                return subprocess.CompletedProcess(
                    cmd,
                    1,
                    "",
                    "fatal: update_ref failed for ref 'refs/heads/master': cannot lock ref",
                )
            raise AssertionError(f"Unexpected command: {cmd}")

        pr_merged = {
            "number": 12,
            "state": "MERGED",
            "headRefOid": "deadbeef1234567",
        }

        with (
            patch.object(orch, "run_subprocess", side_effect=mock_run_subprocess),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_merged),
            patch.object(orch, "run_or_fail", return_value=True),
        ):
            result = orch.phase_merge(run, repo)

        assert result == "passed"
        assert len(run.nonfatal_warnings) == 1
        warning = run.nonfatal_warnings[0]
        assert warning["failure_subtype"] == "local_post_merge_sync_failed"
        assert warning["action"] == "git update-ref refs/heads/master origin/master"
        assert "cannot lock ref" in warning["detail"]

