    def test_launch_numbered_implement_artifacts_are_immutable_across_same_attempt(
        self,
        repo: Path,
    ):
        run = self._make_run(repo)
        first_launch = orch._reserve_implement_launch(run, repo)
        first = orch.ImplementContext(
            run_id=run.run_id,
            attempt_number=11,
            launch_number=first_launch,
            failure_summary="first launch",
        )
        first.save(repo, run.run_id)

        second_launch = orch._reserve_implement_launch(run, repo)
        second = orch.ImplementContext(
            run_id=run.run_id,
            attempt_number=11,
            launch_number=second_launch,
            failure_summary="second launch",
        )
        second.save(repo, run.run_id)
        first.failure_summary = "later annotation must not rewrite launch one"
        first.save(repo, run.run_id)

        run_dir = repo / ".spec-state" / "runs" / run.run_id
        launch_one = json.loads((run_dir / "implement-context.launch-1.json").read_text())
        launch_two = json.loads((run_dir / "implement-context.launch-2.json").read_text())
        assert launch_one["failure_summary"] == "first launch"
        assert launch_two["failure_summary"] == "second launch"
        assert orch.RunState.load(repo, run.run_id).implement_launches == 2

