    def test_status_prints_diagnosis_with_external_state_dir(
        self, repo: Path, capsys: pytest.CaptureFixture[str], tmp_path: Path
    ):
        """F2: spec status must not crash when the state dir is outside the repo root."""
        external_state = tmp_path / "external-state"
        external_state.mkdir()
        # Save run state and diagnosis into the external state dir so
        # cmd_status finds them when _state_root is patched.
        run = self._make_run(repo)  # saves to repo's .spec-state
        # Copy run state file to external state dir
        runs_dir = external_state / "runs"
        runs_dir.mkdir(parents=True)
        src_run = repo / ".spec-state" / "runs" / f"{run.run_id}.json"
        shutil.copy2(src_run, runs_dir / f"{run.run_id}.json")
        # Save and copy diagnosis
        diag_dir = runs_dir / run.run_id
        diag_dir.mkdir(parents=True)
        orch.BlockDiagnosis(
            summary="External diagnosis",
            root_cause="Same blocker",
            confidence=0.7,
            category="gate-failure",
            evidence=["gate-status.json"],
            next_best_action="Fix lint",
            requires_human_attention=False,
            needs_new_commit=True,
            blocker_signature="sig-ext",
        ).save(repo, run.run_id)
        src_diag = repo / ".spec-state" / "runs" / run.run_id / orch.BLOCK_DIAGNOSIS_FILENAME
        shutil.copy2(src_diag, diag_dir / orch.BLOCK_DIAGNOSIS_FILENAME)

        with (
            patch.object(orch, "resolve_repo_root", return_value=repo),
            patch.object(orch, "_state_root", return_value=external_state),
        ):
            rc = orch.cmd_status(argparse.Namespace(spec="my-feature", run=run.run_id))

        assert rc == 0
        out = capsys.readouterr().out
        assert "Blocked Run Diagnosis:" in out
        # Should fall back to absolute path rather than crashing
        assert "block-diagnosis.json" in out
        assert "Next Best Action: Fix lint" in out

