    def test_resume_blocked_run_clears_stale_diagnosis_state(self, repo: Path):
        """When blocker signature changed since diagnosis, pending debugger fields are cleared."""
        run = self._make_run(repo)
        run.pending_block_debugger_signature = "old-sig"
        run.last_block_debugger_guided_retry_signature = "old-sig"
        run.save(repo)

        orch.BlockDiagnosis(
            summary="Stale diagnosis",
            root_cause="Old blocker",
            confidence=0.8,
            category="gate-failure",
            evidence=["gate-status.json"],
            next_best_action="Fix lint",
            requires_human_attention=False,
            needs_new_commit=True,
            blocker_signature="old-sig",
            source_phase="verify",
        ).save(repo, run.run_id)

        with patch.object(orch, "_compute_blocker_signature", return_value="new-sig"):
            # Simulate the resume logic from cmd_run
            diagnosis = orch.BlockDiagnosis.load(repo, run.run_id)
            assert diagnosis is not None
            run.status = "failed"
            run.phase = "implement"
            if diagnosis is not None and not diagnosis.requires_human_attention:
                current_sig = orch._compute_blocker_signature(
                    run,
                    repo,
                    source_phase=diagnosis.source_phase or run.phase,
                )
                if current_sig == diagnosis.blocker_signature:
                    run.pending_block_debugger_signature = diagnosis.blocker_signature
                else:
                    run.pending_block_debugger_signature = ""
                    run.last_block_debugger_guided_retry_signature = ""

        assert run.phase == "implement"
        assert run.pending_block_debugger_signature == ""
        assert run.last_block_debugger_guided_retry_signature == ""

