    def test_temporary_debugger_worktree_locks_linked_gitdir(self, repo: Path):
        """The debugger worktree context manager also makes the linked gitdir read-only."""
        fake_gitdir = repo / "fake_linked_gitdir"

        was_readonly = {}

        original_make = orch._make_tree_readonly
        original_restore = orch._restore_tree_writable

        def tracking_make(root: Path, *, exclude: Path | None = None) -> None:
            original_make(root, exclude=exclude)
            was_readonly[str(root)] = True

        def tracking_restore(root: Path) -> None:
            original_restore(root)
            was_readonly[str(root)] = False

        with (
            patch.object(orch, "_cleanup_stale_block_debugger_worktrees"),
            patch.object(orch, "_resolve_worktree_linked_gitdir", return_value=fake_gitdir),
            patch.object(orch, "_setup_debugger_common_dir_guard", return_value=({}, [])),
            patch.object(orch, "_make_tree_readonly", side_effect=tracking_make),
            patch.object(orch, "_restore_tree_writable", side_effect=tracking_restore),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=[],
                    returncode=0,
                    stdout="",
                    stderr="",
                ),
            ),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(orch, "_cleanup_worktree_checkout", return_value=""),
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", repo / "tmp"),
            patch("tempfile.mkdtemp", return_value=str(repo / "tmp" / "debug-wt")),
        ):
            (repo / "tmp").mkdir(exist_ok=True)
            (repo / "tmp" / "debug-wt").mkdir(exist_ok=True)
            # The rmdir in the context manager expects the dir to exist then be removed
            # but since we mock run_subprocess (git worktree add), skip that check
            with patch.object(Path, "rmdir"):
                ctx = orch._temporary_block_debugger_worktree(repo, head_sha="abc123")
                with ctx as (_wt_path, _extra_env):
                    # Inside the context, both should be "readonly"
                    assert was_readonly.get(str(fake_gitdir)) is True

        # After exit, both should be restored
        assert was_readonly.get(str(fake_gitdir)) is False

    def test_temporary_debugger_worktree_reports_missing_host_ref(self, repo: Path):
        missing_sha = "e4ccde515dbbc5c5297fa0e3ca6f81c5f925d83f"

        def fake_run_subprocess(cmd, cwd=None, **kwargs):  # noqa: ARG001
            if cmd[:2] == ["git", "cat-file"]:
                return subprocess.CompletedProcess(cmd, 1, "", "fatal: Not a valid object name")
            raise AssertionError(f"Unexpected command after missing ref preflight: {cmd}")

        with (
            patch.object(orch, "_cleanup_stale_block_debugger_worktrees"),
            patch.object(orch, "run_subprocess", side_effect=fake_run_subprocess),
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", repo / "tmp"),
            pytest.raises(ValueError) as exc_info,
        ):
            (repo / "tmp").mkdir(exist_ok=True)
            with orch._temporary_block_debugger_worktree(repo, head_sha=missing_sha):
                pass

        message = str(exc_info.value)
        assert "missing-host-ref" in message
        assert "is not available in the host repository" in message
        assert ".spec-workspaces/<run>/source" in message

    def test_temporary_debugger_uses_private_clone_for_validated_surviving_workspace(
        self,
        repo: Path,
        tmp_path: Path,
    ):
        run_id = "container-run-20260101T000000"
        workspace_root = repo / ".spec-workspaces"
        source = workspace_root / run_id / "source"
        source.parent.mkdir(parents=True)
        _run_git("clone", str(repo), str(source), cwd=repo)
        _run_git("config", "user.email", "test@test.com", cwd=source)
        _run_git("config", "user.name", "Test", cwd=source)
        (source / "container-only.txt").write_text("container commit\n")
        _run_git("add", "container-only.txt", cwd=source)
        _run_git("commit", "-m", "container-only commit", cwd=source)
        container_head = _run_git_stdout("rev-parse", "HEAD", cwd=source).strip()
        assert _run_git_expect_fail("cat-file", "-e", f"{container_head}^{{commit}}", cwd=repo)

        run = self._make_run(repo)
        run.run_id = run_id
        run.backend = "container"
        run.worktree_path = str(source)
        config = replace(
            orch.SPEC_RUNTIME_CONFIG,
            execution=replace(
                orch.SPEC_RUNTIME_CONFIG.execution,
                backend="container",
                workspace_root=".spec-workspaces",
            ),
        )
        host_status_before = _run_git_stdout("status", "--porcelain", cwd=repo)
        source_status_before = _run_git_stdout("status", "--porcelain", cwd=source)
        source_head_before = _run_git_stdout("rev-parse", "HEAD", cwd=source)
        temp_root = tmp_path / "debug-clones"
        temp_root.mkdir()

        with (
            patch.object(orch, "SPEC_RUNTIME_CONFIG", config),
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", temp_root),
        ):
            validated = orch._validated_block_debugger_surviving_workspace(run, repo)
            assert validated == source.resolve()
            with orch._temporary_block_debugger_worktree(
                repo,
                head_sha=container_head,
                surviving_workspace=validated,
            ) as (debug_checkout, _extra_env):
                assert _run_git_stdout("rev-parse", "HEAD", cwd=debug_checkout).strip() == container_head
                assert _run_git_stdout("remote", cwd=debug_checkout).strip() == ""
                assert (debug_checkout / "container-only.txt").read_text() == "container commit\n"

        assert not list(temp_root.glob(f"{orch.LOCAL_BLOCK_DEBUGGER_WORKTREE_PREFIX}*"))
        assert _run_git_stdout("status", "--porcelain", cwd=repo) == host_status_before
        assert _run_git_stdout("status", "--porcelain", cwd=source) == source_status_before
        assert _run_git_stdout("rev-parse", "HEAD", cwd=source) == source_head_before
        assert _run_git_expect_fail("cat-file", "-e", f"{container_head}^{{commit}}", cwd=repo)

