class TestCmdCompleteStatusAliases:
    def test_ok_alias_maps_to_passed(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        run.save(repo)

        with (
            patch.object(orch, "resolve_common_root", return_value=repo),
            patch.dict(
                orch.os.environ,
                {"SPEC_ID": "other-spec", "SPEC_RUN_ID": "stale-run"},
                clear=False,
            ),
        ):
            code = orch.cmd_complete(argparse.Namespace(spec="my-feature", status="ok", summary=""))

        assert code == 0
        result = orch.ImplementResult.load(repo, run.run_id)
        assert result is not None
        assert result.status == "passed"
        assert result.attempt == run.attempts

    def test_error_alias_maps_to_failed(self, repo: Path):
        run = orch.RunState(
            run_id="my-feature-20260101T000001",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
