# ---------------------------------------------------------------------------
# No statuses.json dependency verification
# ---------------------------------------------------------------------------


class TestNoStatusesJsonDependency:
    def test_status_functions_no_json_dependency(self):
        """Status resolution functions must not use JSON status registry."""
        import inspect

        for fn in [
            spec_status.get_spec_status,
            spec_status.is_spec_merged,
            spec_status.is_spec_in_progress,
        ]:
            src = inspect.getsource(fn)
            assert "load_statuses" not in src, f"{fn.__name__} still uses load_statuses"
            assert "status_file_path" not in src, f"{fn.__name__} still uses status_file_path"

    def test_orchestrator_no_json_imports(self):
        """The runtime driver must not import JSON status writers."""
        src = Path(orch.__file__).read_text()
        assert "write_spec_status" not in src
        assert "status_file_path" not in src
        assert "set_spec_status" not in src


