        runs_dir = repo / ".spec-state" / "runs"
        save_run_lease(
            runs_dir,
            build_lease(
                run_id=run.run_id,
                spec_id=run.spec_id,
                phase="implement",
                process_pid=12345,
                process_started_at="Mon Mar 17 12:00:00 2026",
            ),
        )

        # Lease heartbeat is fresh but the recorded process is dead — the
        # canonical projection must reflect lease=stale rather than active.
        monkeypatch.setattr(orch, "is_pid_alive", lambda pid, started_at="": False)

        with patch.object(orch, "resolve_repo_root", return_value=repo):
            code = orch.cmd_status(argparse.Namespace(spec="my-feature", run=run.run_id))

        out = capsys.readouterr().out
