                orch.ReviewFinding(
                    id="latest-high-confidence",
                    title="Payload drift",
                    severity="P1",
                    file="api/routes.py",
                    start_line=12,
                    end_line=14,
                    body="Align the initial implementation with the persisted schema.",
                    confidence=0.95,
                )
