    def test_cmd_run_resume_preserves_saved_base_ref(self, repo: Path):
        """When --base is not passed, resuming a run must keep its saved
        base_ref (e.g. HEAD from a web handoff) instead of overwriting it
        with the configured default."""
        existing = orch.RunState(
            run_id="my-feature-20260102T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260102T000000",
            worktree_path=str(repo / ".worktrees" / "code-my-feature--20260102T000000"),
            phase="implement",
            status="failed",
            attempts=1,
            retry_cap=3,
            last_error="Agent exited with code 1 (no_handshake).",
            agent="codex",
            base_ref="HEAD",
        )
        existing.save(repo)
        captured: dict[str, object] = {}

        def fake_run_full_workflow(run: orch.RunState, _repo_root: Path, **kw: object) -> str:
            captured["base_ref"] = run.base_ref
            return "passed"

        # base=None simulates argparse when --base is not passed
        args = argparse.Namespace(spec="my-feature", agent="codex", base=None)
        with (
            patch.object(orch, "resolve_repo_root", return_value=repo),
            patch.object(orch, "run_full_workflow", side_effect=fake_run_full_workflow),
        ):
            code = orch.cmd_run(args)

        assert code == 0
        assert captured["base_ref"] == "HEAD"

