    def test_phase_scoping_launches_claude_and_renames_branch(self, repo: Path):
        worktree = repo / ".worktrees" / "task-task-token123--token123"
        worktree.mkdir(parents=True)
        claude_dir = worktree / ".claude"
        claude_dir.mkdir()

        run = orch.RunState(
            run_id="task-token123-20260101T000000",
            spec_id="task-token123",
            branch="task/task-token123--token123",
            worktree_path=str(worktree),
            run_mode="task",
            agent="claude",
        )

        def fake_subprocess_run(cmd, **kwargs):
            task_spec = worktree / "specs" / "tasks" / "my-fix.md"
            task_spec.parent.mkdir(parents=True, exist_ok=True)
            task_spec.write_text(
                textwrap.dedent("""\
                ---
                id: my-fix
                status: task
                depends_on: []
                description: Fix the bug
                ---

                ## Goal
                Fix the bug
            """)
            )
            return subprocess.CompletedProcess(cmd, 0)

        with (
            patch.object(orch.sys.stdin, "isatty", return_value=True),
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(orch, "_write_sandbox_config"),
            patch.object(orch, "_load_task_scoping_prompt", return_value="Test prompt"),
            patch.object(orch, "_state_root", return_value=repo / ".spec-state"),
            patch.object(
                orch.subprocess,
                "run",
                side_effect=fake_subprocess_run,
            ) as mock_run,
            patch.object(
                orch,
                "run_subprocess",
                side_effect=self._task_scoping_git_side_effect("specs/tasks/my-fix.md"),
            ) as mock_git,
        ):
            result = orch.phase_scoping(run, repo)

        assert result == "passed"
        # Verify Claude CLI was invoked
        called_cmd = mock_run.call_args[0][0]
        assert called_cmd[0] == "claude"
        assert "--mcp-config" in called_cmd
        # Verify branch rename was attempted (no worktree move).
        rename_calls = [
            call for call in mock_git.call_args_list if call[0][0][:3] == ["git", "branch", "-m"]
        ]
        assert len(rename_calls) == 1
        rename_args = rename_calls[0][0][0]
        assert rename_args[0:3] == ["git", "branch", "-m"]
        assert "my-fix" in rename_args[3] or "my-fix" in rename_args[4]
        assert run.spec_id == "my-fix"
        assert run.spec_path == "specs/tasks/my-fix.md"
        assert run.spec_revision.startswith("sha256:")
        assert (repo / ".spec-state" / "runs" / run.run_id / "spec.md").exists()
        # Worktree path must remain unchanged (spec requirement)
        assert run.worktree_path == str(worktree)

