    def test_resolve_scoped_task_spec_ignores_upstream_task_specs_added_after_snapshot(
        self,
        repo: Path,
    ):
        """Git diff narrows task candidates when a scoping branch rebased onto newer base."""
        worktree = repo / ".worktrees" / "task-task-token123--token123"
        task_specs = worktree / "specs" / "tasks"
        task_specs.mkdir(parents=True)
        upstream_spec = task_specs / "upstream-task.md"
        upstream_spec.write_text(
            textwrap.dedent("""\
            ---
            id: upstream-task
            status: task
            depends_on: []
            description: Merged upstream while scoping
            ---
            """)
        )
        scoped_spec = task_specs / "scoped-task.md"
        scoped_spec.write_text(
            textwrap.dedent("""\
            ---
            id: scoped-task
            status: task
            depends_on: []
            description: The real scoped task
            ---
            """)
        )
        run = orch.RunState(
            run_id="task-token123-20260101T000000",
            spec_id="task-token123",
            branch="task/task-token123--token123",
            worktree_path=str(worktree),
            run_mode="task",
            base_ref="origin/master",
            agent="claude",
        )

        with patch.object(
            orch,
            "run_subprocess",
            side_effect=[
                subprocess.CompletedProcess(
                    ["git"],
                    0,
                    "specs/tasks/scoped-task.md\n",
                    "",
                ),
                subprocess.CompletedProcess(["git"], 0, "", ""),
            ],
        ) as mock_git:
            resolved = orch._resolve_scoped_task_spec(
                repo,
                run,
                worktree,
                preexisting_task_specs=set(),
                preexisting_catalog_specs=set(),
        )

        assert resolved == scoped_spec
        diff_cmd = mock_git.call_args_list[0][0][0]
        assert diff_cmd[:3] == ["git", "diff", "--name-only"]
        assert "origin/master...HEAD" in diff_cmd

