class TestCmdStep:
    def test_cmd_step_new_run_supersedes_failed_run_and_carries_forward_prior_review_findings(  # noqa: E501
        self,
        repo: Path,
    ):
        prior_run = orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature--20260101T000000",
            worktree_path=str(repo / ".worktrees" / "code-my-feature--20260101T000000"),
            status="failed",
            agent="codex",
        )
        prior_run.save(repo)
        orch.ReviewResult(
            status="request_changes",
            summary="Fix payload handling before re-review.",
            findings=[
                orch.ReviewFinding(
                    id="finding-1",
                    title="Payload drift",
                    severity="P1",
                    file="api/routes.py",
                    start_line=12,
                    end_line=14,
                    body="Align the initial implementation with the persisted schema.",
                    confidence=0.95,
                )
            ],
        ).save(repo, prior_run.run_id)

        captured: dict[str, orch.RunState | str] = {}
        args = argparse.Namespace(
            spec="my-feature",
            phase="implement",
            agent="codex",
            base="origin/master",
            reset_intake=False,
        )

        def fake_run_single_phase(
            selected_run: orch.RunState,
            phase: str,
            _repo_root: Path,
        ) -> str:
            captured["run"] = selected_run
            captured["phase"] = phase
            return "passed"

        with (
            patch.object(orch, "resolve_repo_root", return_value=repo),
            patch.object(orch, "_select_step_run", return_value=None),
            patch.object(orch, "run_single_phase", side_effect=fake_run_single_phase),
        ):
            code = orch.cmd_step(args)

        assert code == 0
        assert captured["phase"] == "implement"
        new_run = captured["run"]
        assert isinstance(new_run, orch.RunState)
        assert new_run.run_id != prior_run.run_id
        assert new_run.prior_review_run_id == prior_run.run_id
        assert new_run.prior_review_summary == "Fix payload handling before re-review."
        assert len(new_run.prior_review_findings) == 1
        assert new_run.prior_review_findings[0]["id"] == "finding-1"

        prior_reloaded = orch.RunState.load(repo, prior_run.run_id)
        assert prior_reloaded.status == "superseded"
        assert prior_reloaded.superseded_by == new_run.run_id

