class TestWaitingForInputWorkflow:
    """Tests for the needs-input/waiting-for-input orchestrator workflow."""

    def _make_run(self, agent: str = "claude") -> orch.RunState:
        return orch.RunState(
            run_id="my-feature-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
            agent=agent,
        )

    # -------------------------------------------------------------------
    # (1) phase_implement handling needs-input
    # -------------------------------------------------------------------

    def test_implement_needs_input_sets_waiting_status(self, repo: Path):
        """When agent reports needs-input, phase_implement returns
        'waiting-for-input' and saves question to run state."""
        run = self._make_run()
        worktree = repo / ".worktrees" / run.spec_id
        worktree.mkdir(parents=True, exist_ok=True)
        orch.ImplementResult(
            status="needs-input",
            summary="Which API version should we target?",
            attempt=0,
        ).save(repo, run.run_id)

        def report_needs_input(*_args, **_kwargs):
            orch.ImplementResult(
                status="needs-input",
                summary="Which API version should we target?",
                attempt=0,
                launch_number=run.implement_launches,
            ).save(repo, run.run_id)
            return 0

        with (
            patch.object(orch, "resolve_worktree_path", return_value=worktree),
            patch.object(
                orch,
                "_build_agent_command",
                return_value=["/bin/sh", "-c", "exit 0"],
            ),
            patch.object(
                orch,
                "_launch_implement_attempt",
                side_effect=report_needs_input,
            ),
        ):
            status = orch.phase_implement(run, repo)

        assert status == "waiting-for-input"
        assert run.status == "waiting-for-input"
        assert run.input_question == "Which API version should we target?"
        request = orch.OperatorRequest.load(repo, run.run_id)
        assert request is not None
        assert request.kind == "agent_question"
        assert request.prompt == "Which API version should we target?"

    def test_implement_needs_input_propagates_through_workflow(self, repo: Path):
        """run_full_workflow returns 'waiting-for-input' when implement
        reports needs-input, without consuming retry budget."""
        run = self._make_run()
        run.save(repo)
        attempts_before = run.attempts

        handlers = {p: MagicMock(return_value="passed") for p in orch.PHASES}
        handlers["implement"] = MagicMock(return_value="waiting-for-input")

        with patch.dict(orch.PHASE_HANDLERS, handlers):
            result = orch.run_full_workflow(run, repo)

        assert result == "waiting-for-input"
        assert run.attempts == attempts_before

    # -------------------------------------------------------------------
    # (2) cmd_input success/failure behavior
    # -------------------------------------------------------------------

    def test_input_resolves_existing_container_backend_workspace(self, repo: Path):
        run = self._make_run()
        run.backend = "container"
        run.backend_workspace_root = ".spec-workspaces"
        registered_worktree = repo / ".worktrees" / "registered"
        registered_worktree.mkdir(parents=True)
        backend_source = repo / ".spec-workspaces" / run.run_id / "source"
        backend_source.mkdir(parents=True)
        backend = MagicMock()
        backend.identity = eb.BackendIdentity(
            backend="worktree",
            safety_mode="host",
            workspace_root=".worktrees",
            backend_explicit=False,
        )

        with (
            patch.object(orch, "resolve_worktree_path", return_value=registered_worktree),
            patch.object(orch, "_resolve_execution_backend", return_value=backend),
        ):
            resolved = orch._resolve_existing_workspace_path(run, repo)

        assert resolved == backend_source
        backend.prepare_workspace.assert_not_called()

    @pytest.mark.parametrize(
        "kind, requested_by_phase, session_completed, expected_action",
        [
            ("agent_question", "implement", False, orch.OPERATOR_CONTINUATION_RESUME_IMPLEMENT),
            ("agent_question", "implement", True, orch.OPERATOR_CONTINUATION_CONTINUE_WORKFLOW),
            ("agent_question", "verify", True, orch.OPERATOR_CONTINUATION_RESUME_IMPLEMENT),
            ("debugger_guidance", "verify", True, orch.OPERATOR_CONTINUATION_RESUME_IMPLEMENT),
        ],
    )
    def test_operator_continuation_policy_table(
        self,
        kind: str,
        requested_by_phase: str,
        session_completed: bool,
        expected_action: str,
    ):
        request = orch.OperatorRequest(
            kind=kind,
            prompt="Which path should we take?",
            requested_by_phase=requested_by_phase,
        )

        assert (
            orch._select_operator_continuation(
                request,
                session_completed_implement=session_completed,
            )
            == expected_action
        )

    def test_resolve_operator_request_answer_only_resumes_implement(self, repo: Path):
        run = self._make_run()
        run.status = "waiting-for-input"
        run.phase = "implement"
        run.save(repo)
        orch.OperatorRequest(
            kind="agent_question",
            prompt="Which API version?",
            requested_by_phase="implement",
        ).save(repo, run.run_id)
        orch.ImplementResult(status="passed", summary="old result", attempt=run.attempts).save(repo, run.run_id)

        continuation = orch.resolve_operator_request(
            repo,
            run,
            "Use v2.",
            source="unit-test",
            session_completed_implement=False,
        )

        reloaded = orch.RunState.load(repo, run.run_id)
        request = orch.OperatorRequest.load(repo, run.run_id)
        assert continuation.action == orch.OPERATOR_CONTINUATION_RESUME_IMPLEMENT
        assert reloaded.status == "pending"
        assert reloaded.phase == "implement"
        assert request is not None
        assert request.continuation == orch.OPERATOR_CONTINUATION_RESUME_IMPLEMENT
        assert request.response == "Use v2."
        assert orch.ImplementResult.load(repo, run.run_id) is None

    def test_resolve_operator_request_completed_input_session_continues_workflow(self, repo: Path):
        run = self._make_run()
        run.status = "waiting-for-input"
        run.phase = "implement"
        run.save(repo)
        orch.OperatorRequest(
            kind="agent_question",
            prompt="Which API version?",
            requested_by_phase="implement",
        ).save(repo, run.run_id)
        orch.ImplementResult(status="passed", summary="Resolved in session", attempt=run.attempts).save(repo, run.run_id)

        continuation = orch.resolve_operator_request(
            repo,
            run,
            "Resolved in session",
            source="spec input",
            session_completed_implement=True,
        )

        reloaded = orch.RunState.load(repo, run.run_id)
        request = orch.OperatorRequest.load(repo, run.run_id)
        assert continuation.action == orch.OPERATOR_CONTINUATION_CONTINUE_WORKFLOW
        assert reloaded.status == "passed"
        assert reloaded.phase == "implement"
        assert request is not None
        assert request.continuation == orch.OPERATOR_CONTINUATION_CONTINUE_WORKFLOW
        assert orch.ImplementResult.load(repo, run.run_id) is not None

    def test_cmd_input_rejects_non_waiting_run(self, repo: Path, capsys):
        """cmd_input refuses to act on runs not in waiting-for-input status."""
