        assert reloaded is not None
        assert reloaded.status == "pending"
        assert reloaded.phase == "implement"
        request = orch.OperatorRequest.load(repo, run.run_id)
        assert request is not None
        assert request.kind == "debugger_guidance"
        assert request.response == "Retry with the targeted lint fix."
        resume_mock.assert_called_once()
        resume_args = resume_mock.call_args.args[0]
        assert resume_args.spec == "my-feature"
        assert resume_args.run == run.run_id
        assert resume_args.retry_cap == reloaded.retry_cap

