# ---------------------------------------------------------------------------
# _ensure_orchestrator_process_group – SIGTTOU regression
# ---------------------------------------------------------------------------


@pytest.mark.skipif(os.name != "posix", reason="POSIX-only signal handling")
class TestEnsureOrchestratorProcessGroupSigttou:
    """Regression test: tcsetpgrp() must be wrapped with SIGTTOU ignored.

    Without temporarily ignoring SIGTTOU, calling tcsetpgrp() after setpgrp()
    causes the kernel to stop the process (the ``make task`` hang).
    """

    def _make_run(self):
        return orch.RunState(
            run_id="test-run",
            spec_id="test-spec",
            branch="test-branch",
        )

    def test_sigttou_ignored_during_tcsetpgrp(self):
        """SIGTTOU must be SIG_IGN when tcsetpgrp is called."""
        import signal
        import types

        # Track signal.signal calls and tcsetpgrp ordering to verify that
        # SIGTTOU is ignored *before* tcsetpgrp is invoked.
        call_log: list[tuple[str, object]] = []

        real_signal_fn = signal.signal

        # Create a proxy signal module that intercepts signal.signal() calls
        # while delegating everything else to the real module.
        proxy_signal = types.ModuleType("signal_proxy")
        proxy_signal.__dict__.update(signal.__dict__)

        def tracking_signal(signum, handler):
            if signum == signal.SIGTTOU:
                call_log.append(("signal", handler))
            return real_signal_fn(signum, handler)

        proxy_signal.signal = tracking_signal

        def spy_tcsetpgrp(fd, pgid):
            call_log.append(("tcsetpgrp", None))

        mock_stdin = MagicMock()
        mock_stdin.fileno.return_value = 0

        run = self._make_run()
        with (
            patch.object(run, "save"),
            patch("os.getpgrp", side_effect=[os.getpid() + 1, os.getpid()]),
            patch("os.setpgrp"),
            patch("sys.stdin", mock_stdin),
            patch("os.tcsetpgrp", side_effect=spy_tcsetpgrp),
            patch.object(orch, "signal", proxy_signal),
        ):
            orch._ensure_orchestrator_process_group(run, Path("/tmp/fake"))

        # Expected ordering: set SIG_IGN → tcsetpgrp → restore handler
        assert len(call_log) >= 3, f"expected >= 3 calls, got {call_log}"
        assert call_log[0] == ("signal", signal.SIG_IGN), "SIGTTOU must be set to SIG_IGN before tcsetpgrp"
        assert call_log[1][0] == "tcsetpgrp", "tcsetpgrp must be called after SIGTTOU is ignored"

    def test_sigttou_restored_after_tcsetpgrp(self):
        """The original SIGTTOU handler must be restored after tcsetpgrp."""
        import signal

        mock_stdin = MagicMock()
        mock_stdin.fileno.return_value = 0

        original_handler = signal.getsignal(signal.SIGTTOU)
        run = self._make_run()
        with (
            patch.object(run, "save"),
            patch("os.getpgrp", side_effect=[os.getpid() + 1, os.getpid()]),
            patch("os.setpgrp"),
            patch("sys.stdin", mock_stdin),
            patch("os.tcsetpgrp"),
        ):
            orch._ensure_orchestrator_process_group(run, Path("/tmp/fake"))

        assert signal.getsignal(signal.SIGTTOU) == original_handler

    def test_sigttou_restored_on_tcsetpgrp_exception(self):
        """SIGTTOU handler is restored even when tcsetpgrp raises."""
        import signal

        mock_stdin = MagicMock()
        mock_stdin.fileno.return_value = 0

        original_handler = signal.getsignal(signal.SIGTTOU)
        run = self._make_run()
        with (
            patch.object(run, "save"),
            patch("os.getpgrp", side_effect=[os.getpid() + 1, os.getpid()]),
            patch("os.setpgrp"),
            patch("sys.stdin", mock_stdin),
            patch("os.tcsetpgrp", side_effect=OSError("not a tty")),
        ):
            orch._ensure_orchestrator_process_group(run, Path("/tmp/fake"))

        assert signal.getsignal(signal.SIGTTOU) == original_handler


