class TestContainerOutboxCompletionResult:
    """Validation of completion reports read from the container outbox."""

    def _make_workspace(self, tmp_path: Path, payload: dict) -> Path:
        run_root = tmp_path / "run"
        worktree = run_root / "source"
        worktree.mkdir(parents=True)
        (run_root / "logs").mkdir()
        (run_root / "backend-state").mkdir()
        (run_root / "backend-state" / "container-backend-state.json").write_text("{}")
        (run_root / "outbox").mkdir()
        (run_root / "outbox" / "completion-report.json").write_text(
            json.dumps(payload)
        )
        return worktree

    def _payload(self, *, spec_id: str, run_id: str) -> dict:
        return {
            "artifact": "spec-container-completion-report",
            "version": 1,
            "spec_id": spec_id,
            "run_id": run_id,
            "implement_result": {
                "status": "ok",
                "summary": "done",
                "attempt": 1,
            },
        }

    def test_loads_result_when_run_and_spec_match(self, tmp_path: Path):
        worktree = self._make_workspace(
            tmp_path, self._payload(spec_id="real-spec", run_id="run-1")
        )

        result = orch._load_container_outbox_completion_result(
            worktree, "run-1", spec_id="real-spec"
        )

        assert result is not None
        assert result.status == "ok"

    def test_rejects_report_with_mismatched_spec_id(
        self, tmp_path: Path, caplog: pytest.LogCaptureFixture
    ):
        # Observed in the wild: a fixture test exercising `spec report` under
        # inherited SPEC_RUN_ID/SPEC_COMPLETION_OUTBOX env writes a report that
        # carries the LIVE run_id but its own fixture spec id.
        worktree = self._make_workspace(
            tmp_path, self._payload(spec_id="my-feature", run_id="run-1")
        )

        with caplog.at_level(logging.WARNING, logger="spec_runtime.orchestrator"):
            result = orch._load_container_outbox_completion_result(
                worktree, "run-1", spec_id="real-spec"
            )

        assert result is None
        assert any("spec_id" in record.message for record in caplog.records)

    def test_skips_spec_id_check_when_not_provided(self, tmp_path: Path):
        worktree = self._make_workspace(
            tmp_path, self._payload(spec_id="whatever", run_id="run-1")
        )

        result = orch._load_container_outbox_completion_result(worktree, "run-1")

        assert result is not None


class TestCodexIsolatedHomeRequiresAuthCopy:
    """Backend-aware auth.json copy/symlink selection."""

    @staticmethod
    def _identity(name: str):
        from spec_runtime.execution_backend import BackendIdentity

        return BackendIdentity(
            backend=name,
            safety_mode="strict",
            workspace_root="",
            backend_explicit=False,
        )

    def test_returns_false_for_worktree_backend(self):
        """WorktreeExecutionBackend launches the agent as a host subprocess —
        an absolute auth.json symlink resolves correctly, no copy needed."""

        class _Fake:
            pass

        _Fake.__name__ = "WorktreeExecutionBackend"
        fake = _Fake()
        fake.identity = self._identity("container")
        assert orch._codex_isolated_home_requires_auth_copy(fake) is False

    def test_returns_false_for_local_backend(self):
        """Non-container identities never bind-mount; the symlink works."""

        class _Fake:
            pass

        fake = _Fake()
        fake.identity = self._identity("local")
        assert orch._codex_isolated_home_requires_auth_copy(fake) is False

    def test_returns_true_for_container_backend(self):
        """ContainerExecutionBackend bind-mounts the worktree but not the user
        home, so the auth.json symlink target is unreachable in the worker."""

        class _Fake:
            pass

        _Fake.__name__ = "ContainerExecutionBackend"
        fake = _Fake()
        fake.identity = self._identity("container")
        assert orch._codex_isolated_home_requires_auth_copy(fake) is True


class TestSyncOrchestratorPathsIntoWorkspace:
    """Orchestrator-written paths must reach the workspace the agent actually
    sees. For backends without ``sync_host_paths_into_workspace`` (worktree,
    local clone, container bind mode) this is a no-op; for the container
    backend in volume mode it forwards the call so files written to the host
    worktree after seeding become visible inside ``/workspace/source``."""

    def test_noop_when_backend_has_no_sync_method(self, tmp_path: Path):
        class _Fake:
            pass

        fake = _Fake()
        # No exception when the attribute is missing.
        orch._sync_orchestrator_paths_into_workspace(
            fake, tmp_path, (".spec-codex-home",),
        )

    def test_forwards_paths_to_backend(self, tmp_path: Path):
        calls: list[tuple[Path, tuple[str, ...]]] = []

        class _Fake:
            def sync_host_paths_into_workspace(self, workspace_path, relative_paths):
                calls.append((workspace_path, tuple(relative_paths)))

        orch._sync_orchestrator_paths_into_workspace(
            _Fake(), tmp_path, (".spec-codex-home", ".claude/mcp-servers.json"),
        )
        assert calls == [(tmp_path, (".spec-codex-home", ".claude/mcp-servers.json"))]

    def test_swallows_backend_errors_with_warning(
        self, tmp_path: Path, caplog: pytest.LogCaptureFixture
    ):
        """A sync failure must not abort the launch — the agent will surface
        the missing config itself, and the warning carries the diagnostic."""

        class _Fake:
            def sync_host_paths_into_workspace(self, workspace_path, relative_paths):
                raise RuntimeError("sync failed")

        with caplog.at_level(logging.WARNING, logger="spec_runtime.orchestrator"):
            orch._sync_orchestrator_paths_into_workspace(
                _Fake(), tmp_path, (".spec-codex-home",),
            )
        assert any("sync failed" in record.message for record in caplog.records)


class TestBlockDebuggerWorktreePreSeal:
    """Pre-seal hook lets the orchestrator stage MCP config before chmod."""

    def test_pre_seal_runs_before_readonly_chmod(self, tmp_path: Path):
        """Files written by the pre-seal callback must be created while the
        worktree is still writable so the agent's MCP config can be staged
        without PermissionError."""
        repo = tmp_path / "repo"
        repo.mkdir()
        wt = repo / "tmp" / "debug-wt"

        pre_seal_writes_succeeded: list[bool] = []

        def _pre_seal(worktree_path: Path) -> Path | None:
            target = worktree_path / ".staged" / "config.json"
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_text("{}")
                pre_seal_writes_succeeded.append(True)
            except PermissionError:
                pre_seal_writes_succeeded.append(False)
            return None

        with (
            patch.object(orch, "_cleanup_stale_block_debugger_worktrees"),
            patch.object(orch, "_resolve_worktree_linked_gitdir", return_value=None),
            patch.object(orch, "_setup_debugger_common_dir_guard", return_value=({}, [])),
            patch.object(orch, "_make_tree_readonly"),
            patch.object(orch, "_restore_tree_writable"),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=[], returncode=0, stdout="", stderr="",
                ),
            ),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(orch, "_cleanup_worktree_checkout", return_value=""),
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", repo / "tmp"),
            patch("tempfile.mkdtemp", return_value=str(wt)),
        ):
            (repo / "tmp").mkdir(exist_ok=True)
            wt.mkdir(parents=True, exist_ok=True)
            with patch.object(Path, "rmdir"):
                ctx = orch._temporary_block_debugger_worktree(
                    repo, head_sha="abc123", pre_seal=_pre_seal,
                )
                with ctx as (_path, _env):
                    pass

        assert pre_seal_writes_succeeded == [True]
        assert (wt / ".staged" / "config.json").is_file()

    def test_pre_seal_exclude_path_keeps_subtree_writable(self, tmp_path: Path):
        """The Codex isolated CODEX_HOME needs to stay writable so Codex can
        emit its own session state at runtime; pre-seal returns that path so
        the chmod skips it."""
        repo = tmp_path / "repo"
        repo.mkdir()
        wt = repo / "tmp" / "debug-wt"

        def _pre_seal(worktree_path: Path) -> Path | None:
            home = worktree_path / ".spec-codex-home"
            home.mkdir(parents=True, exist_ok=True)
            (home / "config.toml").write_text("")
            return home

        captured: dict[str, Path | None] = {"exclude": None}

        original_make = orch._make_tree_readonly

        def _tracking_make(root: Path, *, exclude: Path | None = None) -> None:
            captured["exclude"] = exclude
            original_make(root, exclude=exclude)

        with (
            patch.object(orch, "_cleanup_stale_block_debugger_worktrees"),
            patch.object(orch, "_resolve_worktree_linked_gitdir", return_value=None),
            patch.object(orch, "_setup_debugger_common_dir_guard", return_value=({}, [])),
            patch.object(orch, "_make_tree_readonly", side_effect=_tracking_make),
            patch.object(orch, "_restore_tree_writable"),
            patch.object(
                orch,
                "run_subprocess",
                return_value=subprocess.CompletedProcess(
                    args=[], returncode=0, stdout="", stderr="",
                ),
            ),
            patch.object(orch, "_head_sha", return_value="abc123"),
            patch.object(orch, "_cleanup_worktree_checkout", return_value=""),
            patch.object(orch, "LOCAL_REVIEW_WORKTREE_ROOT", repo / "tmp"),
            patch("tempfile.mkdtemp", return_value=str(wt)),
        ):
            (repo / "tmp").mkdir(exist_ok=True)
            wt.mkdir(parents=True, exist_ok=True)
            with patch.object(Path, "rmdir"):
                ctx = orch._temporary_block_debugger_worktree(
                    repo, head_sha="abc123", pre_seal=_pre_seal,
                )
                with ctx as (_path, _env):
                    pass

        assert captured["exclude"] == wt / ".spec-codex-home"


class TestMakeTreeReadonlyExclude:
    """Excluded subtrees stay writable after the readonly chmod."""

    def test_exclude_keeps_subtree_writable(self, tmp_path: Path):
        root = tmp_path / "root"
        keep = root / "keep-writable"
        locked = root / "locked"
        keep.mkdir(parents=True)
        locked.mkdir(parents=True)
        (keep / "file.txt").write_text("k")
        (locked / "file.txt").write_text("l")

        try:
            orch._make_tree_readonly(root, exclude=keep)
            # Excluded subtree retains owner write permission.
            assert os.stat(keep).st_mode & stat.S_IWUSR
            assert os.stat(keep / "file.txt").st_mode & stat.S_IWUSR
            # Locked sibling has owner write removed.
            assert not (os.stat(locked / "file.txt").st_mode & stat.S_IWUSR)
        finally:
            orch._restore_tree_writable(root)

    def test_readonly_and_restore_never_chmod_external_symlink_targets(self, tmp_path: Path):
        root = tmp_path / "root"
        root.mkdir()
        locked = root / "locked.txt"
        locked.write_text("locked")
        external_file = tmp_path / "external.txt"
        external_file.write_text("external")
        external_dir = tmp_path / "external-dir"
        external_dir.mkdir()
        external_nested = external_dir / "nested.txt"
        external_nested.write_text("nested")
        (root / "file-link").symlink_to(external_file)
        (root / "dir-link").symlink_to(external_dir, target_is_directory=True)

        external_modes = {
            path: stat.S_IMODE(os.stat(path).st_mode)
            for path in (external_file, external_dir, external_nested)
        }

        try:
            orch._make_tree_readonly(root)
            assert not (os.stat(locked).st_mode & stat.S_IWUSR)
            for path, mode in external_modes.items():
                assert stat.S_IMODE(os.stat(path).st_mode) == mode
        finally:
            orch._restore_tree_writable(root)

        for path, mode in external_modes.items():
            assert stat.S_IMODE(os.stat(path).st_mode) == mode


class TestUserMcpServersForPassthrough:
    """Read user MCP configs and apply [mcp].allow_from_user filtering."""

    @pytest.fixture(autouse=True)
    def _use_fixture_home(self, monkeypatch: pytest.MonkeyPatch) -> None:
        monkeypatch.delenv("CODEX_HOME", raising=False)

    def test_codex_passthrough_returns_named_servers(
        self, tmp_path: Path, monkeypatch: pytest.MonkeyPatch
    ):
        fake_home = tmp_path / "home"
