# ---------------------------------------------------------------------------
# Container backend lost-commit detection
# ---------------------------------------------------------------------------


class _FakeContainerBackend:
    identity = eb.BackendIdentity(
        backend="container",
        safety_mode="host-mediated",
        workspace_root=".spec-workspaces",
    )


class _FakeWorktreeBackend:
    identity = eb.BackendIdentity(
        backend="worktree",
        safety_mode="host",
        workspace_root=".spec-workspaces",
    )


class TestContainerLostImplementationDetection:
    def _worktree_with_base(self, tmp_path: Path) -> tuple[Path, str]:
        work = tmp_path / "source"
        work.mkdir()
        _run_git("init", "-q", cwd=work)
        _run_git("config", "user.email", "test@test.com", cwd=work)
        _run_git("config", "user.name", "Test", cwd=work)
        (work / "base.txt").write_text("base\n")
        _run_git("add", "base.txt", cwd=work)
        _run_git("commit", "-q", "-m", "base", cwd=work)
        _run_git("branch", "-f", "origin/master", "HEAD", cwd=work)
        base_sha = _run_git_stdout("rev-parse", "HEAD", cwd=work).strip()
        return work, base_sha

    def _outcome(
        self, base_sha: str, head_after: str, *, dirty: bool
    ) -> orch.ImplementAttemptOutcome:
        return orch.ImplementAttemptOutcome(
            exit_code=0,
            head_before=base_sha,
            head_after=head_after,
            has_new_commit=base_sha != head_after,
            has_uncommitted_changes=dirty,
        )

    def _run(self) -> orch.RunState:
        run = orch.RunState(
            run_id="lost-commit-20260101T000000",
            spec_id="my-feature",
            branch="spec/my-feature",
        )
        run.base_ref = "origin/master"
        return run

    def _result(self, commits: list[str] | None = None) -> orch.ImplementResult:
        return orch.ImplementResult(
            status="passed",
            summary="done",
            attempt=0,
            commits=commits if commits is not None else ["e4ccde5 agent work"],
        )

    def test_flags_passed_run_with_head_stuck_at_base(self, tmp_path: Path):
        work, base_sha = self._worktree_with_base(tmp_path)
        outcome = self._outcome(base_sha, base_sha, dirty=False)
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeContainerBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result()
            )
        assert error is not None
        assert "preserves no implementation" in error

    def test_no_flag_when_agent_claims_no_commits(self, tmp_path: Path):
        # A genuine no-op pass (empty commit list) must not be flagged, matching
        # existing container passes that report success without a new commit.
        work, base_sha = self._worktree_with_base(tmp_path)
        outcome = self._outcome(base_sha, base_sha, dirty=False)
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeContainerBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result(commits=[])
            )
        assert error is None

    def test_allows_run_with_new_commit_above_base(self, tmp_path: Path):
        work, base_sha = self._worktree_with_base(tmp_path)
        (work / "impl.txt").write_text("impl\n")
        _run_git("add", "impl.txt", cwd=work)
        _run_git("commit", "-q", "-m", "impl work", cwd=work)
        head_after = _run_git_stdout("rev-parse", "HEAD", cwd=work).strip()
        outcome = self._outcome(base_sha, head_after, dirty=False)
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeContainerBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result()
            )
        assert error is None

    def test_allows_run_with_uncommitted_changes(self, tmp_path: Path):
        work, base_sha = self._worktree_with_base(tmp_path)
        outcome = self._outcome(base_sha, base_sha, dirty=True)
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeContainerBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result()
            )
        assert error is None

    def test_allows_preserved_head_above_base_without_new_commit_this_attempt(
        self, tmp_path: Path
    ):
        # Review-retry style: head already carries prior implementation above the
        # base and this attempt adds no new commit. Must NOT be flagged.
        work, base_sha = self._worktree_with_base(tmp_path)
        (work / "impl.txt").write_text("impl\n")
        _run_git("add", "impl.txt", cwd=work)
        _run_git("commit", "-q", "-m", "prior impl", cwd=work)
        head = _run_git_stdout("rev-parse", "HEAD", cwd=work).strip()
        outcome = self._outcome(head, head, dirty=False)  # head_before == head_after
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeContainerBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result()
            )
        assert error is None

    def test_ignores_non_container_backend(self, tmp_path: Path):
        work, base_sha = self._worktree_with_base(tmp_path)
        outcome = self._outcome(base_sha, base_sha, dirty=False)
        with patch.object(orch, "_EXECUTION_BACKEND_OVERRIDE", _FakeWorktreeBackend()):
            error = orch._detect_container_lost_implementation(
                self._run(), work, outcome, self._result()
            )
        assert error is None


class _ReseedRecordingContainerBackend:
    """Container backend fake that records reseed_workspace_volume calls (AC4)."""

    identity = eb.BackendIdentity(
        backend="container",
        safety_mode="host-mediated",
        workspace_root=".spec-workspaces",
    )

    def __init__(self) -> None:
        self.reseed_calls: list[Path] = []

    def reseed_workspace_volume(self, workspace) -> None:
        self.reseed_calls.append(workspace.path)


class TestPositionReviewRetryWorkspaceHead:
    """Container review retries must be positioned at the reviewed head
    before the lineage guard, not left at the base the pre-implement restore
    reset them to."""

    BRANCH = "code/my-feature"

    def _init_repo(self, path: Path) -> None:
        path.mkdir(parents=True, exist_ok=True)
        _run_git("init", "-q", "-b", self.BRANCH, cwd=path)
        _run_git("config", "user.email", "test@test.com", cwd=path)
        _run_git("config", "user.name", "Test", cwd=path)

    def _commit(self, path: Path, name: str, body: str) -> str:
        (path / name).write_text(body)
        _run_git("add", name, cwd=path)
        _run_git("commit", "-q", "-m", name, cwd=path)
        return _run_git_stdout("rev-parse", "HEAD", cwd=path).strip()

    def _workspace(self, work: Path) -> eb.WorkspaceHandle:
        run_root = work.parent
        (run_root / "outbox").mkdir(parents=True, exist_ok=True)
        return eb.WorkspaceHandle(
            path=work,
            outbox_path=run_root / "outbox",
            branch=self.BRANCH,
            backend="container",
        )

    def _run(self) -> orch.RunState:
        return orch.RunState(
            run_id="review-retry-20260101T000000",
            spec_id="my-feature",
            branch=self.BRANCH,
        )

    def _ctx(self, reviewed_head: str, *, triggering_phase: str = "review") -> orch.ImplementContext:
        return orch.ImplementContext(
            implement_reason="review_feedback",
            triggering_phase=triggering_phase,
            reviewed_head_sha=reviewed_head,
        )

    def _build_present(self, tmp_path: Path) -> tuple[Path, str, str]:
        """Work repo that already has the reviewed head object but HEAD reset to base."""
        origin = tmp_path / "origin"
        self._init_repo(origin)
        base = self._commit(origin, "base.txt", "base\n")
        reviewed = self._commit(origin, "impl.txt", "impl\n")
        run_root = tmp_path / "run"
        run_root.mkdir()
        work = run_root / "source"
        _run_git("clone", "-q", "-b", self.BRANCH, str(origin), str(work), cwd=tmp_path)
        _run_git("config", "user.email", "test@test.com", cwd=work)
        _run_git("config", "user.name", "Test", cwd=work)
        # Simulate the pre-implement restore rolling HEAD back to base.
        _run_git("reset", "--hard", base, cwd=work)
        return work, base, reviewed

    def _build_missing(self, tmp_path: Path) -> tuple[Path, str, str]:
        """Work repo at base, reviewed head only reachable via origin fetch."""
        origin = tmp_path / "origin"
        self._init_repo(origin)
        base = self._commit(origin, "base.txt", "base\n")
        run_root = tmp_path / "run"
        run_root.mkdir()
        work = run_root / "source"
        _run_git("clone", "-q", "-b", self.BRANCH, str(origin), str(work), cwd=tmp_path)
        _run_git("config", "user.email", "test@test.com", cwd=work)
        _run_git("config", "user.name", "Test", cwd=work)
        # Reviewed head is created in origin AFTER the clone, so work lacks the object.
        reviewed = self._commit(origin, "impl.txt", "impl\n")
        return work, base, reviewed

    def test_reviewed_head_present_resets_without_fetch(self, tmp_path: Path):
        work, base, reviewed = self._build_present(tmp_path)
        assert orch._head_sha(work) == base
        run = self._run()
        backend = _FakeContainerBackend()
        ctx = self._ctx(reviewed)

        with patch.object(orch, "run_git_fetch_with_timeout") as fetch:
            orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        fetch.assert_not_called()
        assert orch._head_sha(work) == reviewed
        # Branch now points at the reviewed head.
        assert _run_git_stdout("rev-parse", self.BRANCH, cwd=work).strip() == reviewed
        # Lineage guard passes because current head == reviewed head.
        ctx.current_head_sha = orch._head_sha(work)
        ctx.triggering_review_result_path = "runs/review-result.attempt-1.json"
        assert orch._validate_review_retry_lineage(run, work, work, ctx) == ""

    def test_reviewed_head_missing_fetches_branch_then_resets(self, tmp_path: Path):
        work, base, reviewed = self._build_missing(tmp_path)
        assert orch._commit_present(work, reviewed).returncode != 0
        run = self._run()
        backend = _FakeContainerBackend()
        ctx = self._ctx(reviewed)

        real_fetch = orch.run_git_fetch_with_timeout
        calls: list = []

        def spy(args, **kwargs):
            calls.append(args)
            return real_fetch(args, **kwargs)

        with patch.object(orch, "run_git_fetch_with_timeout", side_effect=spy):
            orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        assert calls == [["origin", f"{self.BRANCH}:refs/remotes/origin/{self.BRANCH}"]]
        assert orch._head_sha(work) == reviewed
        # phase_implement no longer blocks with a lineage error.
        ctx.current_head_sha = orch._head_sha(work)
        ctx.triggering_review_result_path = "runs/review-result.attempt-1.json"
        assert orch._validate_review_retry_lineage(run, work, work, ctx) == ""

    def test_reviewed_head_still_missing_after_fetch_fails_cleanly(self, tmp_path: Path):
        work, base, _reviewed = self._build_missing(tmp_path)
        run = self._run()
        backend = _FakeContainerBackend()
        # A head that exists nowhere: fetch succeeds (branch fetched) but the
        # object is still absent afterwards.
        missing_head = "0" * 40
        ctx = self._ctx(missing_head)

        with pytest.raises(ValueError) as excinfo:
            orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        message = str(excinfo.value)
        assert orch._short_sha(missing_head) in message
        assert self.BRANCH in message
        # Not a misleading base-drift lineage block.
        assert "drift" not in message.lower()
        # The workspace was not moved off base.
        assert orch._head_sha(work) == base

    def test_fetch_timeout_fails_cleanly(self, tmp_path: Path):
        work, base, reviewed = self._build_missing(tmp_path)
        run = self._run()
        backend = _FakeContainerBackend()
        ctx = self._ctx(reviewed)

        def boom(args, **kwargs):
            raise orch.GitFetchTimeoutError(["git", "fetch", *args], 60.0)

        with patch.object(orch, "run_git_fetch_with_timeout", side_effect=boom):
            with pytest.raises(ValueError) as excinfo:
                orch._position_review_retry_workspace_head(
                    run, self._workspace(work), backend, ctx
                )

        message = str(excinfo.value)
        assert "timed out" in message
        assert orch._short_sha(reviewed) in message
        assert self.BRANCH in message
        assert orch._head_sha(work) == base

    def test_non_review_container_retry_is_noop(self, tmp_path: Path):
        work, base, reviewed = self._build_present(tmp_path)
        run = self._run()
        backend = _FakeContainerBackend()
        # Verify-triggered retry carries no reviewed_head_sha to target.
        ctx = self._ctx("", triggering_phase="verify")

        with patch.object(orch, "run_git_fetch_with_timeout") as fetch:
            orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        fetch.assert_not_called()
        assert orch._head_sha(work) == base

    def test_non_container_backend_is_noop(self, tmp_path: Path):
        work, base, reviewed = self._build_present(tmp_path)
        run = self._run()
        backend = _FakeWorktreeBackend()
        ctx = self._ctx(reviewed)

        with patch.object(orch, "run_git_fetch_with_timeout") as fetch:
            orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        fetch.assert_not_called()
        assert orch._head_sha(work) == base

    def test_volume_mode_reseeds_worker_after_reposition(self, tmp_path: Path):
        work, base, reviewed = self._build_present(tmp_path)
        run = self._run()
        backend = _ReseedRecordingContainerBackend()
        ctx = self._ctx(reviewed)

        orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)

        assert orch._head_sha(work) == reviewed
        # AC4: the repositioned head is pushed toward the worker volume.
        assert backend.reseed_calls == [work]

    def test_end_to_end_lineage_pass_reproduces_305(self, tmp_path: Path):
        # Workspace restored to base, origin/<branch> reachable at the reviewed
        # head: restore -> position -> lineage must pass.
        work, base, reviewed = self._build_missing(tmp_path)
        run = self._run()
        backend = _FakeContainerBackend()
        ctx = self._ctx(reviewed)
        ctx.triggering_review_result_path = "runs/review-result.attempt-1.json"

        orch._position_review_retry_workspace_head(run, self._workspace(work), backend, ctx)
        head_before = orch._head_sha(work)
        ctx.current_head_sha = head_before

        assert head_before == reviewed
        assert orch._validate_review_retry_lineage(run, work, work, ctx) == ""


class TestReviewRetryHistoryRewritten:
    """A review retry that reports success but rewrote history (the
    reviewed head is no longer an ancestor of the new head) must fail the
    attempt instead of recording a false success."""

    def _init_repo(self, path: Path) -> None:
        path.mkdir(parents=True, exist_ok=True)
        _run_git("init", "-q", "-b", "code/my-feature", cwd=path)
        _run_git("config", "user.email", "test@test.com", cwd=path)
        _run_git("config", "user.name", "Test", cwd=path)

    def _commit(self, path: Path, name: str, body: str) -> str:
        (path / name).write_text(body)
        _run_git("add", name, cwd=path)
        _run_git("commit", "-q", "-m", name, cwd=path)
        return _run_git_stdout("rev-parse", "HEAD", cwd=path).strip()

    def _ctx(self, reviewed_head: str, *, triggering_phase: str = "review") -> orch.ImplementContext:
        return orch.ImplementContext(
            implement_reason="review_feedback",
            triggering_phase=triggering_phase,
            reviewed_head_sha=reviewed_head,
        )

    def _run(self) -> orch.RunState:
        return orch.RunState(
            run_id="review-retry-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature",
        )

    def test_append_on_top_of_reviewed_head_is_not_rewrite(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        appended = self._commit(work, "fix.txt", "fix\n")
        ctx = self._ctx(reviewed)
        assert orch._review_retry_history_rewritten(work, ctx, appended) is False

    def test_recommit_from_base_is_a_rewrite(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        base = self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        # Agent recreated the branch from base: reviewed head
        # is no longer an ancestor of the new head.
        _run_git("reset", "--hard", base, cwd=work)
        rewritten = self._commit(work, "impl.txt", "different impl\n")
        assert rewritten != reviewed
        ctx = self._ctx(reviewed)
        assert orch._review_retry_history_rewritten(work, ctx, rewritten) is True

    def test_non_review_phase_is_never_flagged(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        base = self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        _run_git("reset", "--hard", base, cwd=work)
        rewritten = self._commit(work, "impl.txt", "different\n")
        ctx = self._ctx(reviewed, triggering_phase="verify")
        assert orch._review_retry_history_rewritten(work, ctx, rewritten) is False

    def test_head_equal_to_reviewed_is_not_rewrite(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        ctx = self._ctx(reviewed)
        assert orch._review_retry_history_rewritten(work, ctx, reviewed) is False

    def test_interpret_outcome_fails_a_rewritten_passed_attempt(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        base = self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        _run_git("reset", "--hard", base, cwd=work)
        rewritten = self._commit(work, "impl.txt", "different\n")
        run = self._run()
        ctx = self._ctx(reviewed)
        outcome = orch.ImplementAttemptOutcome(
            exit_code=0,
            head_before=reviewed,
            head_after=rewritten,
            has_new_commit=True,
            has_uncommitted_changes=False,
        )
        passed = orch.ImplementResult(status="passed", summary="done", attempt=0, commits=[])
        status = orch._interpret_implement_attempt_outcome(
            run, work, work, ctx, outcome, prefetched_result=(passed, False)
        )
        assert status == "failed"
        assert "rewrote history" in run.last_error
        assert orch._short_sha(reviewed) in run.last_error

    def test_interpret_outcome_passes_an_appended_attempt(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        appended = self._commit(work, "fix.txt", "fix\n")
        run = self._run()
        ctx = self._ctx(reviewed)
        outcome = orch.ImplementAttemptOutcome(
            exit_code=0,
            head_before=reviewed,
            head_after=appended,
            has_new_commit=True,
            has_uncommitted_changes=False,
        )
        passed = orch.ImplementResult(status="passed", summary="done", attempt=0, commits=[])
        status = orch._interpret_implement_attempt_outcome(
            run, work, work, ctx, outcome, prefetched_result=(passed, False)
        )
        assert status == "passed"

    def test_interpret_outcome_fails_a_passed_attempt_with_no_appended_commit(self, tmp_path: Path):
        # AC2: an explicit review-retry success that left HEAD unchanged (no new
        # commit on top of the reviewed head) re-submits the already-rejected
        # head and must fail rather than record a false success.
        work = tmp_path / "work"
        self._init_repo(work)
        self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        run = self._run()
        ctx = self._ctx(reviewed)
        outcome = orch.ImplementAttemptOutcome(
            exit_code=0,
            head_before=reviewed,
            head_after=reviewed,
            has_new_commit=False,
            has_uncommitted_changes=False,
        )
        passed = orch.ImplementResult(status="passed", summary="done", attempt=0, commits=[])
        status = orch._interpret_implement_attempt_outcome(
            run, work, work, ctx, outcome, prefetched_result=(passed, False)
        )
        assert status == "failed"
        assert "appended no commit" in run.last_error
        assert orch._short_sha(reviewed) in run.last_error

    def test_missing_appended_commit_helper_ignores_non_review_phase(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        self._commit(work, "base.txt", "base\n")
        reviewed = self._commit(work, "impl.txt", "impl\n")
        ctx = self._ctx(reviewed, triggering_phase="verify")
        assert orch._review_retry_missing_appended_commit(work, ctx, reviewed) is False


class TestReviewedHeadUnrecoverableClassification:
    """An unreachable reviewed head must surface as needs-attention
    (non-retryable) rather than a retry that silently implements from base."""

    def _run(self) -> orch.RunState:
        return orch.RunState(
            run_id="review-retry-20260101T000000",
            spec_id="my-feature",
            branch="code/my-feature",
        )

    def test_unrecoverable_reviewed_head_is_non_retryable(self):
        run = self._run()
        run.last_error = (
            "Review-triggered retry could not position the workspace at reviewed head "
            "1234567 for branch 'code/my-feature' (stale or missing remote head): boom"
        )
        metadata = orch._classify_phase_result(run, "implement", "failed")
        assert metadata["failure_subtype"] == "reviewed_head_unrecoverable"
        assert metadata["retryable"] is False


class TestRecoveryCommitExcludes:
    """The no-handshake recovery commit must never sweep untracked
    test scratch (``.tmp/``, ``pytest-of-*``) into the branch."""

    def _init_repo(self, path: Path) -> None:
        path.mkdir(parents=True, exist_ok=True)
        _run_git("init", "-q", "-b", "code/my-feature", cwd=path)
        _run_git("config", "user.email", "test@test.com", cwd=path)
        _run_git("config", "user.name", "Test", cwd=path)
        (path / "base.txt").write_text("base\n")
        _run_git("add", "base.txt", cwd=path)
        _run_git("commit", "-q", "-m", "base", cwd=path)

    def test_temp_artifacts_are_excluded_from_git_add(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        (work / ".tmp").mkdir()
        (work / ".tmp" / "scratch.txt").write_text("scratch\n")
        (work / "pytest-of-user" / "case0").mkdir(parents=True)
        (work / "pytest-of-user" / "case0" / "artifact.log").write_text("x" * 100)
        (work / "real_change.py").write_text("print('real')\n")

        orch._seed_recovery_commit_excludes(work)
        _run_git("add", "-A", cwd=work)
        staged = _run_git_stdout("diff", "--cached", "--name-only", cwd=work).split()

        assert "real_change.py" in staged
        assert not any(name.startswith(".tmp/") for name in staged)
        assert not any(name.startswith("pytest-of-user/") for name in staged)

    def test_is_idempotent_and_preserves_existing_excludes(self, tmp_path: Path):
        work = tmp_path / "work"
        self._init_repo(work)
        exclude_path = work / ".git" / "info" / "exclude"
        exclude_path.parent.mkdir(parents=True, exist_ok=True)
        exclude_path.write_text("# existing\ncustom-pattern\n")

        orch._seed_recovery_commit_excludes(work)
        orch._seed_recovery_commit_excludes(work)
        contents = exclude_path.read_text()

        assert "custom-pattern" in contents
        assert contents.count("pytest-of-*") == 1
        assert contents.count(".tmp/") == 1

    def test_exclude_is_synced_into_container_volume_workspace(self, tmp_path: Path):
        # In container volume mode the authoritative git dir lives inside the
        # Docker volume, not the host mirror this function writes. The seeded
        # info/exclude must be pushed into the workspace or the recovery agent's
        # `git add` (which runs in the volume) never honors it.
        work = tmp_path / "work"
        self._init_repo(work)

        class _RecordingBackend:
            def __init__(self) -> None:
                self.calls: list[tuple[Path, tuple[str, ...]]] = []

            def sync_host_paths_into_workspace(
                self, workspace_path: Path, relative_paths
            ) -> None:
                self.calls.append((workspace_path, tuple(relative_paths)))

        backend = _RecordingBackend()
        orch._seed_recovery_commit_excludes(work, backend)

        assert backend.calls == [(work, (".git/info/exclude",))]

    def test_no_backend_does_not_attempt_workspace_sync(self, tmp_path: Path):
        # Bind/worktree callers pass no backend; the host write alone suffices
        # and nothing should try to reach a container volume.
        work = tmp_path / "work"
        self._init_repo(work)
        # Must not raise even though no backend is supplied.
        orch._seed_recovery_commit_excludes(work, None)
        exclude_path = work / ".git" / "info" / "exclude"
        assert "pytest-of-*" in exclude_path.read_text()

    def test_exclude_synced_even_when_patterns_already_present(self, tmp_path: Path):
        # A second seeding round appends nothing, but a freshly reseeded volume
        # may still lack the patterns, so the sync must run regardless.
        work = tmp_path / "work"
        self._init_repo(work)

        class _RecordingBackend:
            def __init__(self) -> None:
                self.calls: list[tuple[Path, tuple[str, ...]]] = []

            def sync_host_paths_into_workspace(
                self, workspace_path: Path, relative_paths
            ) -> None:
                self.calls.append((workspace_path, tuple(relative_paths)))

        backend = _RecordingBackend()
        orch._seed_recovery_commit_excludes(work, backend)
        orch._seed_recovery_commit_excludes(work, backend)

        assert len(backend.calls) == 2
        assert all(call == (work, (".git/info/exclude",)) for call in backend.calls)

class TestPassedVerifyResume:
    def test_passed_verify_run_is_workflow_resumable(self):
        """A manual `spec phase --phase verify` recovery leaves
        status=passed phase=verify; resume must advance it, not strand it."""
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1", status="passed", phase="verify")
        assert run.is_auto_resumable is True
        assert run.is_workflow_resumable is True

    def test_failed_verify_stays_out_of_late_phase_resume(self):
        assert "verify" not in orch.FAILED_LATE_PHASE_RESUME_PHASES
        assert "verify" in orch.AUTO_RESUME_PHASES


def test_auto_resume_phases_consistent_across_modules():
    """autopilot.resolve_resume_run and the orchestrator resume path must
    agree on which passed phases are resumable:
    the dispatcher had a stale duplicate of this constant)."""
    assert frozenset(orch.AUTO_RESUME_PHASES) == autopilot.AUTO_RESUME_PHASES


class TestMidExecutionDbDeathClassification:
    def test_gate_failure_with_dead_db_is_environment_failure(self):
        """Postgres dying mid-test must classify as infrastructure,
        not a test regression that burns implement retries."""
        msg = (
            "Gate 'test' failed (exit 1). output: E psycopg2.OperationalError: "
            "server closed the connection unexpectedly"
        )
        assert orch._is_verify_environment_failure_message(msg) is True
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        run.last_error = msg
        assert orch._workflow_failure_policy(run, "verify") is None

    def test_plain_test_regression_still_retries(self):
        msg = "Gate 'test' failed (exit 1). output: FAILED tests/test_x.py::test_y - assert 1 == 2"
        assert orch._is_verify_environment_failure_message(msg) is False
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        run.last_error = msg
        assert orch._workflow_failure_policy(run, "verify") is not None

    def test_db_mention_without_gate_context_does_not_classify(self):
        assert orch._is_verify_environment_failure_message(
            "psycopg2.OperationalError mentioned in prose"
        ) is False


class TestConsumedRequestDispatch:
    def test_dispatch_resumes_run_with_consumed_operator_request(self, repo: Path):
        """A waiting-for-input record whose operator request was
        already consumed must be dispatchable (projection RETRYABLE), not
        skipped forever by the raw-status early return."""
        import json as _json

        runs_dir = repo / ".spec-state" / "runs"
        (runs_dir / "stranded-run-1").mkdir(parents=True, exist_ok=True)
        (runs_dir / "stranded-run-1" / "operator-request.json").write_text(
            _json.dumps({"status": "consumed"})
        )
        (runs_dir / "stranded-run-1.json").write_text(
            _json.dumps(
                {
                    "spec_id": "stranded-spec",
                    "run_id": "stranded-run-1",
                    "status": "waiting-for-input",
                    "phase": "implement",
                    "branch": "code/stranded-spec--1",
                }
            )
        )
        (repo / "specs" / "stranded-spec.md").write_text(
            "---\nid: stranded-spec\nstatus: not-started\ndepends_on: []\n"
            "description: stranded\n---\n\n## Goal\nx\n"
        )

        queue = autopilot.build_dispatch_queue(repo)
        item = next((i for i in queue if i.spec_id == "stranded-spec"), None)
        assert item is not None
        assert item.run_id == "stranded-run-1"

    def test_dispatch_still_skips_pending_operator_request(self, repo: Path):
        import json as _json

        runs_dir = repo / ".spec-state" / "runs"
        (runs_dir / "asking-run-1").mkdir(parents=True, exist_ok=True)
        (runs_dir / "asking-run-1" / "operator-request.json").write_text(
            _json.dumps({"status": "pending"})
        )
        (runs_dir / "asking-run-1.json").write_text(
            _json.dumps(
                {
                    "spec_id": "asking-spec",
                    "run_id": "asking-run-1",
                    "status": "waiting-for-input",
                    "phase": "implement",
                    "branch": "code/asking-spec--1",
                }
            )
        )
        (repo / "specs" / "asking-spec.md").write_text(
            "---\nid: asking-spec\nstatus: not-started\ndepends_on: []\n"
            "description: asking\n---\n\n## Goal\nx\n"
        )

        queue = autopilot.build_dispatch_queue(repo)
        assert all(i.spec_id != "asking-spec" for i in queue)


class TestReviewAgentAuthOutage:
    _MSG = (
        "Independent review status 'failed' via review-decision-gate "
        "(conclusion=failure, findings=0): Local review agent failed "
        "(exit_code=1): failed to connect to websocket: HTTP error: 401 "
        "Unauthorized, url: wss://chatgpt.com/backend-api/codex/responses"
    )

    def test_review_agent_401_classifies_non_retryable(self):
        """Observed 2026-07-15: expired codex credentials failed review with
        zero findings; retrying burns attempts until an operator re-logs-in."""
        assert orch._is_agent_auth_failure_message(self._MSG) is True
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        run.last_error = self._MSG
        metadata = orch._classify_phase_result(run, "review", "failed")
        assert metadata["failure_subtype"] == "agent_auth_missing"
        assert metadata["retryable"] is False
        assert orch._workflow_failure_policy(run, "review") is None

    def test_request_changes_review_still_retries_implement(self):
        run = orch.RunState(run_id="r", spec_id="s", branch="code/s--1")
        run.last_error = "Independent review requested changes via review-decision-gate"
        run.review_decision_status = "request_changes"
        policy = orch._workflow_failure_policy(run, "review")
        assert policy is not None
        assert policy.next_phase == "implement"

    def test_bare_401_without_agent_context_does_not_classify(self):
        assert orch._is_agent_auth_failure_message("HTTP 401 Unauthorized from example.com") is False


class TestRepositionRestoredWorkspaceHead:
    """Verify/merge-triggered snapshot restores must not lose the branch head."""

    def _init_repo_with_impl_commit(self, tmp_path: Path) -> tuple[Path, str, str]:
        worktree = tmp_path / "source"
        worktree.mkdir()
        env = {"GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@t", "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@t"}

        def git(*args):
            result = subprocess.run(
                ["git", *args], cwd=worktree, capture_output=True, text=True, env={**os.environ, **env}
            )
            assert result.returncode == 0, result.stderr
            return result.stdout.strip()

        git("init", "-b", "code/my-feature--x")
        (worktree / "a.txt").write_text("base\n")
        git("add", "a.txt")
        git("commit", "-m", "base")
        base = git("rev-parse", "HEAD")
        (worktree / "a.txt").write_text("impl\n")
        git("add", "a.txt")
        git("commit", "-m", "impl")
        impl = git("rev-parse", "HEAD")
        return worktree, base, impl

    def _backend(self, record: list | None = None):
        class _FakeBackend:
            def __init__(self):
                self.reseeded = record if record is not None else []

            def reseed_workspace_volume(self, workspace):
                self.reseeded.append(workspace.path)

        return _FakeBackend()

    def _workspace(self, worktree: Path, tmp_path: Path) -> orch.WorkspaceHandle:
        outbox = tmp_path / "outbox"
        outbox.mkdir(exist_ok=True)
        return orch.WorkspaceHandle(
            path=worktree, outbox_path=outbox, branch="code/my-feature--x", backend="container"
        )

    def test_verify_triggered_restore_repositions_to_prior_head(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)
        assert (worktree / "a.txt").read_text() == "base\n"

        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        orch._reposition_restored_workspace_head(self._workspace(worktree, tmp_path), self._backend(), ctx, impl)

        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=worktree, capture_output=True, text=True
        ).stdout.strip()
        assert head == impl
        assert (worktree / "a.txt").read_text() == "impl\n"

    def test_review_triggered_with_reviewed_head_defers_to_review_positioning(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)

        ctx = SimpleNamespace(triggering_phase="review", reviewed_head_sha=impl)
        orch._reposition_restored_workspace_head(self._workspace(worktree, tmp_path), self._backend(), ctx, impl)

        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=worktree, capture_output=True, text=True
        ).stdout.strip()
        assert head == base

    def test_empty_prior_head_is_a_noop(self, tmp_path: Path):
        worktree, base, _ = self._init_repo_with_impl_commit(tmp_path)
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)
        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        orch._reposition_restored_workspace_head(self._workspace(worktree, tmp_path), self._backend(), ctx, "")
        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=worktree, capture_output=True, text=True
        ).stdout.strip()
        assert head == base

    def test_reposition_reseeds_worker_volume(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)
        reseeded: list = []
        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        orch._reposition_restored_workspace_head(
            self._workspace(worktree, tmp_path), self._backend(reseeded), ctx, impl
        )
        assert reseeded == [worktree]

    def _purge_commit(self, worktree: Path, base: str) -> None:
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)
        subprocess.run(["git", "reflog", "expire", "--expire=now", "--all"], cwd=worktree, capture_output=True)
        subprocess.run(["git", "gc", "--prune=now", "--aggressive", "-q"], cwd=worktree, capture_output=True)

    def test_unpushed_head_rehydrates_from_rescue_bundle(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        rescue_dir = tmp_path / "rescue" / "20260101T000000000000"
        rescue_dir.mkdir(parents=True)
        bundle_path = rescue_dir / "unpushed.bundle"
        subprocess.run(
            ["git", "bundle", "create", str(bundle_path), "HEAD"],
            cwd=worktree, capture_output=True,
        )
        (tmp_path / "rescue" / "index.json").write_text(
            json.dumps([{ "head_sha": impl, "artifacts": {"bundle": str(bundle_path)} }])
        )
        self._purge_commit(worktree, base)
        probe = subprocess.run(["git", "cat-file", "-e", impl], cwd=worktree, capture_output=True)
        assert probe.returncode != 0, "impl commit should be purged before rehydration"

        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        orch._reposition_restored_workspace_head(
            self._workspace(worktree, tmp_path), self._backend(), ctx, impl
        )
        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=worktree, capture_output=True, text=True
        ).stdout.strip()
        assert head == impl
        assert (worktree / "a.txt").read_text() == "impl\n"

    def test_unrecoverable_head_raises_instead_of_continuing_from_base(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        self._purge_commit(worktree, base)
        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        with pytest.raises(ValueError, match="cannot be recovered"):
            orch._reposition_restored_workspace_head(
                self._workspace(worktree, tmp_path), self._backend(), ctx, impl
            )

    def test_thin_rescue_bundle_rehydrates_after_refilling_from_origin(self, tmp_path: Path):
        """Production stall: a verify retry stranded the run because the rescue
        bundle was thin and its prerequisite (the base-ref commit the agent had
        merged in) was gone from the restored .git."""
        env = {
            "GIT_AUTHOR_NAME": "t",
            "GIT_AUTHOR_EMAIL": "t@t",
            "GIT_COMMITTER_NAME": "t",
            "GIT_COMMITTER_EMAIL": "t@t",
        }

        def git(cwd, *args):
            result = subprocess.run(
                ["git", *args], cwd=cwd, capture_output=True, text=True,
                env={**os.environ, **env},
            )
            assert result.returncode == 0, result.stderr
            return result.stdout.strip()

        origin = tmp_path / "origin"
        origin.mkdir()
        git(origin, "init", "-b", "master")
        (origin / "a.txt").write_text("base\n")
        git(origin, "add", "a.txt")
        git(origin, "commit", "-m", "base")
        base = git(origin, "rev-parse", "HEAD")
        # master advances while the agent works — this is the prerequisite that
        # goes missing when the snapshot restore replaces .git.
        (origin / "b.txt").write_text("later master\n")
        git(origin, "add", "b.txt")
        git(origin, "commit", "-m", "later master")
        advanced = git(origin, "rev-parse", "HEAD")

        worktree = tmp_path / "source"
        git(tmp_path, "clone", str(origin), str(worktree))
        git(worktree, "checkout", "-b", "code/my-feature--x", base)
        (worktree / "a.txt").write_text("impl\n")
        git(worktree, "add", "a.txt")
        git(worktree, "commit", "-m", "impl")
        git(worktree, "merge", "--no-edit", advanced)
        impl = git(worktree, "rev-parse", "HEAD")

        rescue_dir = tmp_path / "rescue" / "20260101T000000000000"
        rescue_dir.mkdir(parents=True)
        bundle_path = rescue_dir / "unpushed.bundle"
        # Thin bundle: everything the branch adds on top of the advanced master.
        git(worktree, "bundle", "create", str(bundle_path), "HEAD", "--not", advanced)
        (tmp_path / "rescue" / "index.json").write_text(
            json.dumps([{"head_sha": impl, "artifacts": {"bundle": str(bundle_path)}}])
        )

        # Simulate the restore: back to base, and the advanced commit is gone.
        subprocess.run(["git", "checkout", "-q", "-B", "code/my-feature--x", base], cwd=worktree, capture_output=True)
        subprocess.run(["git", "remote", "set-branches", "origin", "nothing"], cwd=worktree, capture_output=True)
        subprocess.run(["git", "update-ref", "-d", "refs/remotes/origin/master"], cwd=worktree, capture_output=True)
        subprocess.run(["git", "update-ref", "-d", "refs/remotes/origin/HEAD"], cwd=worktree, capture_output=True)
        subprocess.run(["git", "branch", "-D", "master"], cwd=worktree, capture_output=True)
        self._purge_commit(worktree, base)
        for sha in (impl, advanced):
            probe = subprocess.run(["git", "cat-file", "-e", sha], cwd=worktree, capture_output=True)
            assert probe.returncode != 0, f"{sha} should be purged before rehydration"
        subprocess.run(["git", "remote", "set-branches", "origin", "*"], cwd=worktree, capture_output=True)

        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        orch._reposition_restored_workspace_head(
            self._workspace(worktree, tmp_path), self._backend(), ctx, impl
        )

        head = subprocess.run(
            ["git", "rev-parse", "HEAD"], cwd=worktree, capture_output=True, text=True
        ).stdout.strip()
        assert head == impl
        assert (worktree / "a.txt").read_text() == "impl\n"

    def test_reseed_failure_fails_the_retry(self, tmp_path: Path):
        worktree, base, impl = self._init_repo_with_impl_commit(tmp_path)
        subprocess.run(["git", "reset", "--hard", base], cwd=worktree, capture_output=True)

        class _FailingReseedBackend:
            def reseed_workspace_volume(self, workspace):
                raise RuntimeError("volume seed failed")

        ctx = SimpleNamespace(triggering_phase="verify", reviewed_head_sha="")
        with pytest.raises(ValueError, match="re-seed the worker volume"):
            orch._reposition_restored_workspace_head(
                self._workspace(worktree, tmp_path), _FailingReseedBackend(), ctx, impl
            )


class TestAutoMergeTimeoutClassification:
    """Every auto-merge wait timeout must classify as pending-checks."""

    def _merge_ok(self):
        forge = MagicMock()
        forge.merge_pr.return_value = SimpleNamespace(ok=True, message="")
        return forge

    @pytest.mark.parametrize(
        "checks_result",
        [
            (True, ""),  # required set green/ambiguous while PR stays BLOCKED
            (False, "Required checks still pending: test"),
        ],
    )
    def test_wait_timeout_is_pending_checks_regardless_of_required_set(
        self, tmp_path: Path, checks_result
    ):
        run = orch.RunState(run_id="r1", spec_id="s1", branch="code/s1--x")
        pr_data = {"state": "OPEN", "mergeStateStatus": "BLOCKED", "number": 7}
        with (
            patch.object(orch, "_forge", return_value=self._merge_ok()),
            patch.object(orch, "_find_pr_for_branch", return_value=pr_data),
            patch.object(orch, "_required_checks_green", return_value=checks_result),
            patch.object(orch, "_disable_pr_auto_merge", return_value=""),
            patch.object(orch, "MERGE_CHECKS_TIMEOUT_SECONDS", 0),
        ):
            result = orch._try_auto_merge(run, tmp_path, 7)
        assert result == "failed"
        assert orch._is_auto_merge_pending_checks_timeout(run.last_error), run.last_error


class TestStaleHandshakeGuards:
    """Stale completion artifacts must not be replayed as fresh handshakes."""

    def test_prelaunch_discard_removes_outbox_and_results(self, tmp_path: Path):
        repo = tmp_path / "repo"
        run_root = tmp_path / "ws"
        worktree = run_root / "source"
        (worktree / ".spec-state").mkdir(parents=True)
        (run_root / "logs").mkdir(parents=True)
        (run_root / "backend-state").mkdir()
        (run_root / "backend-state" / "container-backend-state.json").write_text("{}")
        outbox = run_root / "outbox"
        outbox.mkdir()
        (outbox / "completion-report.json").write_text("{}")
        run_id = "spec-x-20260101T000000"
        for root in (repo / ".spec-state", worktree / ".spec-state"):
            d = root / "runs" / run_id
            d.mkdir(parents=True)
            (d / "implement-result.json").write_text("{}")

        with patch.object(orch, "_state_root", return_value=repo / ".spec-state"):
            orch._discard_prelaunch_completion_artifacts(repo, worktree, run_id)

        assert not (outbox / "completion-report.json").exists()
        assert not (repo / ".spec-state" / "runs" / run_id / "implement-result.json").exists()
        assert not (worktree / ".spec-state" / "runs" / run_id / "implement-result.json").exists()

    def test_prelaunch_discard_noop_when_nothing_present(self, tmp_path: Path):
        repo = tmp_path / "repo"
        worktree = tmp_path / "ws" / "source"
        worktree.mkdir(parents=True)
        with patch.object(orch, "_state_root", return_value=repo / ".spec-state"):
            orch._discard_prelaunch_completion_artifacts(repo, worktree, "spec-y-1")

    def test_prelaunch_discard_clears_worktree_alias_but_preserves_history(self, tmp_path: Path):
        repo = tmp_path / "repo"
        worktree = tmp_path / "wt"
        worktree.mkdir(parents=True)
        run_id = "spec-wt-1"
        result = orch.ImplementResult(
            status="passed",
            summary="launch one",
            attempt=20,
            launch_number=1,
        )
        with patch.object(orch, "_state_root", return_value=repo / ".spec-state"):
            result.save(repo, run_id)
            orch._discard_prelaunch_completion_artifacts(repo, worktree, run_id)

        run_dir = repo / ".spec-state" / "runs" / run_id
        assert not (run_dir / "implement-result.json").exists()
        assert (run_dir / "implement-result.attempt-21.json").exists()
        assert (run_dir / "implement-result.launch-1.json").exists()

    def test_same_attempt_result_from_launch_n_cannot_satisfy_launch_n_plus_one(
        self,
        tmp_path: Path,
    ):
        repo = tmp_path / "repo"
        worktree = tmp_path / "wt"
        worktree.mkdir(parents=True)
        run_id = "spec-wt-2"
        orch.ImplementResult(
            status="passed",
            summary="stale launch",
            attempt=20,
            launch_number=1,
        ).save_to_state_root(worktree / ".spec-state", run_id)

        loaded, _ = orch._load_matching_implement_result(
            repo_root=repo,
            worktree_path=worktree,
            run_id=run_id,
            attempt=20,
            launch_number=2,
        )

        assert loaded is None

    def test_wait_does_not_terminate_new_agent_for_prior_launch_result(
        self,
        tmp_path: Path,
    ):
        repo = tmp_path / "repo"
        worktree = tmp_path / "wt"
        worktree.mkdir(parents=True)
        run_id = "spec-wt-3"
        orch.ImplementResult(
            status="passed",
            summary="stale launch",
            attempt=20,
            launch_number=1,
        ).save(repo, run_id)
        proc = _make_fake_popen(poll_sequence=[None, 0])(["agent"])

        with (
            patch.object(orch, "_poll_sleep"),
            patch.object(orch, "AGENT_EXIT_GRACE_SECONDS", 0),
            patch.object(orch, "_terminate_agent_process") as terminate,
        ):
            returncode = orch._wait_for_agent_exit(
                proc=proc,
                agent="codex",
                repo_root=repo,
                worktree_path=worktree,
                run_id=run_id,
                attempt=20,
                launch_number=2,
            )

        assert returncode == 0
        terminate.assert_not_called()

    def test_legacy_launch_zero_requires_explicit_safe_compatibility(self, tmp_path: Path):
        repo = tmp_path / "repo"
        worktree = tmp_path / "wt"
        worktree.mkdir(parents=True)
